// #region 🖲️File Provider

// #region 🧱Memory File Provider
// In-memory file storage provider for temporary or test scenarios.

/**
 * Creates a file provider factory that stores files in memory.
 **/
export function createMemoryFileProvider(config?: MemoryFileProviderConfig): FileProviderFactory {
  const storage = new Map<string, Blob>();

  return async (kitId: string): Promise<FileProvider> => {
    const getKey = (kitId: string, fileId: string, path: string): string => {
      return `${kitId}/${fileId}/${path}`;
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const key = getKey(kitId, fileId, path);
        storage.set(key, blob);
        return `memory://${key}`;
      },

      download: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const blob = storage.get(key);

        if (!blob) {
          throw new Error(`File not found in memory: ${key}`);
        }

        return blob;
      },

      delete: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        storage.delete(key);
        return `memory://${getKey(kitId, fileId, path)}`;
      },

      getUrl: (kitId, fileId, path) => {
        return `memory://${getKey(kitId, fileId, path)}`;
      },
    };
  };
}

// #endregion 🧱Memory File Provider

// #region 🧲Remote File Provider
// Remote file storage provider backed by a REST API.

/**
 * Creates a file provider factory that uploads and downloads files from a remote server.
 **/
export function createRemoteFileProvider(config: RemoteFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const getUrl = (kitId: string, fileId: string, path: string): string => {
      return `${config.baseUrl}/kits/${kitId}/files/${fileId}`;
    };

    const headers = {
      ...config.headers,
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const formData = new FormData();
        formData.append("file", blob, path);

        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "POST",
          headers,
          body: formData,
        });

        if (!response.ok) {
          throw new Error(`Remote upload failed: ${response.statusText}`);
        }

        const result = await response.json();
        return result.url || getUrl(kitId, fileId, path);
      },

      download: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "GET",
          headers,
        });

        if (!response.ok) {
          throw new Error(`Remote download failed: ${response.statusText}`);
        }

        const blob = await response.blob();
        return blob;
      },

      delete: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "DELETE",
          headers,
        });
        if (!response.ok) {
          throw new Error(`Remote delete failed: ${response.statusText}`);
        }
      },

      getUrl: (kitId, fileId, path) => {
        return getUrl(kitId, fileId, path);
      },
    };
  };
}

// #endregion 🧲Remote File Provider

// #region 🗻Composite File Provider
// Composite file storage provider that delegates to multiple underlying providers.

/**
 * Creates a file provider factory that composes memory, local, and remote providers.
 **/
export function createCompositeFileProvider(config: CompositeFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const providers: FileProvider[] = [];

    if (config.memory) {
      const memoryProvider = await createMemoryFileProvider()(kitId);
      providers.push(memoryProvider);
    }

    if (config.remote) {
      const remoteProvider = await createRemoteFileProvider(config.remote)(kitId);
      providers.push(remoteProvider);
    }

    if (providers.length === 0) {
      throw new Error("At least one provider must be configured");
    }

    return {
      upload: async (kitId, fileId, path, blob) => {
        const results = await Promise.allSettled(providers.map((p) => p.upload(kitId, fileId, path, blob)));

        const successful = results.filter((r) => r.status === "fulfilled");
        if (successful.length === 0) {
          throw new Error(`All providers failed to upload file ${path}`);
        }

        const lastSuccessful = results.reverse().find((r) => r.status === "fulfilled") as PromiseFulfilledResult<string>;
        return lastSuccessful.value;
      },

      download: async (kitId, fileId, path) => {
        for (const provider of providers) {
          try {
            return await provider.download(kitId, fileId, path);
          } catch (error) {
            console.warn(`Provider failed to download ${path}, trying next:`, error);
          }
        }
        throw new Error(`All providers failed to download file ${path}`);
      },

      delete: async (kitId, fileId, path) => {
        await Promise.allSettled(providers.map((p) => p.delete(kitId, fileId, path)));
      },

      getUrl: (kitId, fileId, path) => {
        return providers[providers.length - 1].getUrl(kitId, fileId, path);
      },
    };
  };
}

// #endregion 🗻Composite File Provider

// #endregion 🖲️File Provider

// #region 🔑Entity Store Wrappers
// Compatibility wrappers for entity-level access backed by KitStore snapshots.

export class DesignEntityStore {
  constructor(
    private kitStore: KitStore,
    private designId: string,
  ) {}
  snapshot(): Design {
    const kit = this.kitStore.getSnapshot().kit;
    return kit.designs?.find((d) => d.id === this.designId) ?? ({ id: this.designId, pieces: [], connections: [] } as Design);
  }
}

export class QualityEntityStore {
  constructor(
    private kitStore: KitStore,
    private qualityId: string,
  ) {}
  snapshot(): Quality | undefined {
    const kit = this.kitStore.getSnapshot().kit;
    return kit.qualities?.find((q) => q.id === this.qualityId);
  }
}

type KitFileState = {
  blobs: Map<string, Blob>;
  objectUrls: Map<string, string>;
  providerUrls: Map<string, string>;
  pendingBlobDownloads: Map<string, Promise<string | null>>;
  providerFactory?: FileProviderFactory;
  provider?: FileProvider;
  providerKitId?: string;
};

type KitBinaryStore = KitStore & {
  readFile?: (path: string) => Promise<Blob | null>;
  writeFile?: (path: string, blob: Blob) => Promise<void>;
  deleteFile?: (path: string) => Promise<void>;
  createDirectory?: (path: string) => Promise<void>;
  moveEntry?: (fromPath: string, toPath: string) => Promise<void>;
};

const getOrCreateKitFileState = (kitStore: KitStore): KitFileState => {
  const storeWithFiles = kitStore as KitStore & { __semioKitFileState?: KitFileState };
  if (!storeWithFiles.__semioKitFileState) {
    storeWithFiles.__semioKitFileState = {
      blobs: new Map(),
      objectUrls: new Map(),
      providerUrls: new Map(),
      pendingBlobDownloads: new Map(),
    };
  }
  return storeWithFiles.__semioKitFileState;
};

const getStoredKitFileUrls = (kitStore: KitStore): Map<string, string> => {
  const kit = kitStore.getSnapshot().kit;
  const fileState = getOrCreateKitFileState(kitStore);
  const fileUrls = new Map<string, string>();

  for (const file of kit.files ?? []) {
    const readableUrl = getReadableKitFileUrl(fileState, file);
    if (readableUrl) {
      fileUrls.set(getKitFileStoragePath(kit, file), readableUrl);
    }
  }

  return fileUrls;
};

const isBrowserReadableFileUrl = (url: string): boolean => /^(blob:|data:|https?:)/i.test(url);

const getReadableKitFileUrl = (fileState: KitFileState, file: SemioFile): string | null => {
  const cachedBlobUrl = fileState.objectUrls.get(file.id);
  if (cachedBlobUrl) {
    return cachedBlobUrl;
  }

  const cachedProviderUrl = fileState.providerUrls.get(file.id);
  if (cachedProviderUrl && isBrowserReadableFileUrl(cachedProviderUrl)) {
    return cachedProviderUrl;
  }

  if (file.blob && isBrowserReadableFileUrl(file.blob)) {
    return file.blob;
  }

  if (file.remote && isBrowserReadableFileUrl(file.remote)) {
    return file.remote;
  }

  return null;
};

const getKitFileStoragePath = (kit: Kit, file: SemioFile): string => {
  const foldersById = new Map((kit.folders ?? []).map((folder) => [folder.id, folder]));
  const pathSegments: string[] = [file.name];
  let currentFolderId = file.folder?.id;

  while (currentFolderId) {
    const folder = foldersById.get(currentFolderId);
    if (!folder) {
      break;
    }
    pathSegments.unshift(folder.name);
    currentFolderId = folder.parent?.id;
  }

  return pathSegments.join("/");
};

const getKitFolderStoragePath = (kit: Kit, folderLike: Pick<Folder, "id" | "name" | "parent"> | { id: string }): string => {
  const foldersById = new Map((kit.folders ?? []).map((folder) => [folder.id, folder]));
  const visited = new Set<string>();
  const pathSegments: string[] = [];
  let currentFolder: Pick<Folder, "id" | "name" | "parent"> | undefined = "name" in folderLike ? folderLike : foldersById.get(folderLike.id);

  while (currentFolder) {
    if (visited.has(currentFolder.id)) {
      break;
    }
    visited.add(currentFolder.id);
    pathSegments.unshift(currentFolder.name);
    const parentId = currentFolder.parent?.id;
    currentFolder = parentId ? foldersById.get(parentId) : undefined;
  }

  return pathSegments.join("/");
};

const revokeKitFileObjectUrl = (kitStore: KitStore, fileId: string): void => {
  const fileState = getOrCreateKitFileState(kitStore);
  const currentObjectUrl = fileState.objectUrls.get(fileId);
  if (currentObjectUrl) {
    URL.revokeObjectURL(currentObjectUrl);
    fileState.objectUrls.delete(fileId);
  }
};

const createKitFileObjectUrl = (kitStore: KitStore, fileId: string, blob: Blob): string => {
  const fileState = getOrCreateKitFileState(kitStore);
  revokeKitFileObjectUrl(kitStore, fileId);
  const objectUrl = URL.createObjectURL(blob);
  fileState.objectUrls.set(fileId, objectUrl);
  return objectUrl;
};

const getExistingKitFileProvider = (kitStore: KitStore): FileProvider | null => {
  return getOrCreateKitFileState(kitStore).provider ?? null;
};

const getKitFileProvider = async (kitStore: KitStore, kitId: string): Promise<FileProvider | null> => {
  const fileState = getOrCreateKitFileState(kitStore);
  if (fileState.provider && fileState.providerKitId === kitId) {
    return fileState.provider;
  }

  if (!fileState.providerFactory) {
    return null;
  }

  fileState.provider = await fileState.providerFactory(kitId);
  fileState.providerKitId = kitId;
  return fileState.provider;
};

const fetchReadableKitFileBlob = async (url: string): Promise<Blob | null> => {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      return null;
    }
    return await response.blob();
  } catch {
    return null;
  }
};

const uploadKitFileToProvider = async (kitStore: KitStore, kit: Kit, file: SemioFile, blob: Blob): Promise<void> => {
  const fileState = getOrCreateKitFileState(kitStore);
  fileState.blobs.set(file.id, blob);
  revokeKitFileObjectUrl(kitStore, file.id);
  const storagePath = getKitFileStoragePath(kit, file);

  // 🔖EmbedInJsonFileKit
  // For file kits, embed the blob as a data URL in file.blob so everything
  // stays inside the single *.kit.semio.json file on save.
  // Specs: Use embedFileBlob presence, not instanceof JsonFileKitStore — desktop may load two bundle copies of the class so instanceof would skip embedding. kitStore may be a CollaborativeKitStore wrapper, so also check the inner store exposed via `.store`.
  const innerCandidate = (kitStore as { store?: unknown }).store;
  const embedTarget = typeof (kitStore as any)?.embedFileBlob === "function" ? (kitStore as any) : typeof (innerCandidate as any)?.embedFileBlob === "function" ? (innerCandidate as any) : null;
  if (embedTarget) {
    try {
      await embedTarget.embedFileBlob(file.id, blob);
    } catch (error) {
      console.error(`uploadKitFileToProvider: failed to embed blob for ${file.id}:`, error);
    }
    return;
  }

  const binaryStore = kitStore as KitBinaryStore;
  if (typeof binaryStore.writeFile === "function") {
    await binaryStore.writeFile(storagePath, blob);
  }

  const provider = await getKitFileProvider(kitStore, kit.id);
  if (!provider) {
    return;
  }

  await provider.upload(kit.id, file.id, storagePath, blob);
  const providerUrl = provider.getUrl(kit.id, file.id, storagePath);
  if (providerUrl) {
    fileState.providerUrls.set(file.id, providerUrl);
  }
};

const deleteKitFileFromProvider = async (kitStore: KitStore, kit: Kit, file: SemioFile | undefined): Promise<void> => {
  if (!file) {
    return;
  }

  const fileState = getOrCreateKitFileState(kitStore);
  fileState.blobs.delete(file.id);
  fileState.providerUrls.delete(file.id);
  revokeKitFileObjectUrl(kitStore, file.id);
  const storagePath = getKitFileStoragePath(kit, file);

  const binaryStore = kitStore as KitBinaryStore;
  if (typeof binaryStore.deleteFile === "function") {
    await binaryStore.deleteFile(storagePath);
  }

  const provider = await getKitFileProvider(kitStore, kit.id);
  if (!provider) {
    return;
  }

  await provider.delete(kit.id, file.id, storagePath);
};

const syncKitFileCommandResult = async (kitStore: KitStore, kit: Kit, command: string, args: any[], result: KitCommandResult): Promise<void> => {
  const binaryStore = kitStore as KitBinaryStore;
  const nextKit = result.diff ? applyKitDiff(kit, result.diff) : kit;

  if (command === "semio.kit.addFile") {
    const file = args[0] as SemioFile | undefined;
    const blob = args[1] as Blob | undefined;
    if (file && blob) {
      await uploadKitFileToProvider(kitStore, kit, file, blob);
    }
    return;
  }

  if (command === "semio.kit.addFiles") {
    const filesToAdd = (args[1] as { file: SemioFile; blob?: Blob }[] | undefined) ?? [];
    await Promise.all(
      filesToAdd.map(async ({ file, blob }) => {
        if (blob) {
          await uploadKitFileToProvider(kitStore, kit, file, blob);
        }
      }),
    );
    return;
  }

  if (command === "semio.kit.updateFile") {
    const fileId = args[0] as string | undefined;
    const fileDiff = args[1] as FileDiff | undefined;
    const blob = args[2] as Blob | undefined;
    if (!fileId || !blob) {
      return;
    }

    const existingFile = kit.files?.find((file) => file.id === fileId);
    if (!existingFile) {
      return;
    }

    const updatedFile = { ...existingFile, ...fileDiff };
    await uploadKitFileToProvider(kitStore, kit, updatedFile, blob);
    return;
  }

  if (command === "semio.kit.removeFile") {
    const fileId = args[0] as string | undefined;
    const existingFile = kit.files?.find((file) => file.id === fileId);
    await deleteKitFileFromProvider(kitStore, kit, existingFile);
    return;
  }

  if (command === "semio.kit.createFolder") {
    const folder = args[0] as Folder | undefined;
    if (!folder || typeof binaryStore.createDirectory !== "function") {
      return;
    }
    await binaryStore.createDirectory(getKitFolderStoragePath(nextKit, folder));
    return;
  }

  if (command === "semio.kit.updateFolder") {
    const folderId = args[0] as string | undefined;
    if (!folderId || typeof binaryStore.moveEntry !== "function") {
      return;
    }
    const currentFolder = kit.folders?.find((folder) => folder.id === folderId);
    const updatedFolder = nextKit.folders?.find((folder) => folder.id === folderId);
    if (!currentFolder || !updatedFolder) {
      return;
    }
    const currentPath = getKitFolderStoragePath(kit, currentFolder);
    const nextPath = getKitFolderStoragePath(nextKit, updatedFolder);
    if (currentPath && nextPath && currentPath !== nextPath) {
      await binaryStore.moveEntry(currentPath, nextPath);
    }
    return;
  }

  if (command === "semio.kit.import") {
    const importedFiles = result.diff?.files?.added ?? [];
    const importedBlobs = result.files ?? [];
    await Promise.all(
      importedFiles.map(async (file, index) => {
        const blob = importedBlobs[index];
        if (blob) {
          await uploadKitFileToProvider(kitStore, kit, file as SemioFile, blob);
        }
      }),
    );
    return;
  }

  if (command !== "semio.kit.moveToFolder") {
    return;
  }

  const artifactId = args[0] as string | undefined;
  const artifactKind = args[1] as "type" | "design" | "quality" | "file" | "folder" | undefined;
  if (!artifactId || !artifactKind) {
    return;
  }

  if (artifactKind === "file" && typeof binaryStore.moveEntry === "function") {
    const currentFile = kit.files?.find((file) => file.id === artifactId);
    const updatedFile = nextKit.files?.find((file) => file.id === artifactId);
    if (!currentFile || !updatedFile) {
      return;
    }
    const currentPath = getKitFileStoragePath(kit, currentFile);
    const nextPath = getKitFileStoragePath(nextKit, updatedFile);
    if (currentPath && nextPath && currentPath !== nextPath) {
      await binaryStore.moveEntry(currentPath, nextPath);
    }
    return;
  }

  if (artifactKind === "folder") {
    const currentFolder = kit.folders?.find((folder) => folder.id === artifactId);
    const updatedFolder = nextKit.folders?.find((folder) => folder.id === artifactId);
    if (!currentFolder || !updatedFolder) {
      return;
    }
    if (typeof binaryStore.moveEntry !== "function") {
      return;
    }
    const currentPath = getKitFolderStoragePath(kit, currentFolder);
    const nextPath = getKitFolderStoragePath(nextKit, updatedFolder);
    if (currentPath && nextPath && currentPath !== nextPath) {
      await binaryStore.moveEntry(currentPath, nextPath);
    }
  }
};

export class CollaborativeKitStore {
  private _kitStore: KitStore;
  constructor(kitStore: KitStore) {
    this._kitStore = kitStore;
  }
  get store(): KitStore {
    return this._kitStore;
  }
  get isLocallyPersisted(): boolean {
    const kind = (this._kitStore as any).__semioKitPersistenceKind as KitKind | undefined;
    return kind === "file" || kind === "folder";
  }
  get isRemotelySynced(): boolean {
    const kind = (this._kitStore as any).__semioKitPersistenceKind as KitKind | undefined;
    return kind === "remote";
  }
  get kitKind(): KitKind {
    return ((this._kitStore as any).__semioKitPersistenceKind as KitKind | undefined) ?? "temporary";
  }
  snapshot(): Kit {
    return this._kitStore.getSnapshot().kit;
  }
  design(id: string): DesignEntityStore {
    return new DesignEntityStore(this._kitStore, id);
  }
  quality(id: string): QualityEntityStore {
    return new QualityEntityStore(this._kitStore, id);
  }
  get fileUrls(): Map<string, string> {
    return getStoredKitFileUrls(this._kitStore);
  }
  change(partial: Partial<Kit>): void {
    const current = this._kitStore.getSnapshot().kit;
    const diff: any = {};
    for (const [key, value] of Object.entries(partial)) {
      if (value !== (current as any)[key]) {
        diff[key] = value;
      }
    }
    this._kitStore.apply(diff);
  }
  apply(diff: any, meta?: any): void {
    this._kitStore.apply(diff, meta);
  }
  // Forwards to JsonFileKitStore.embedFileBlob so uploadKitFileToProvider can
  // embed dropped blobs without unwrapping the wrapper. No-op when the inner
  // store does not implement embedding (folder/remote/temporary kits).
  async embedFileBlob(fileId: string, blob: Blob): Promise<void> {
    const inner = this._kitStore as { embedFileBlob?: (g: string, b: Blob) => Promise<void> };
    if (typeof inner.embedFileBlob === "function") {
      await inner.embedFileBlob(fileId, blob);
    }
  }
  async readFile(path: string): Promise<Blob | null> {
    const inner = this._kitStore as KitBinaryStore;
    if (typeof inner.readFile !== "function") {
      return null;
    }
    return inner.readFile(path);
  }
  async writeFile(path: string, blob: Blob): Promise<void> {
    const inner = this._kitStore as KitBinaryStore;
    if (typeof inner.writeFile !== "function") {
      return;
    }
    await inner.writeFile(path, blob);
  }
  async deleteFile(path: string): Promise<void> {
    const inner = this._kitStore as KitBinaryStore;
    if (typeof inner.deleteFile !== "function") {
      return;
    }
    await inner.deleteFile(path);
  }
  async createDirectory(path: string): Promise<void> {
    const inner = this._kitStore as KitBinaryStore;
    if (typeof inner.createDirectory !== "function") {
      return;
    }
    await inner.createDirectory(path);
  }
  async moveEntry(fromPath: string, toPath: string): Promise<void> {
    const inner = this._kitStore as KitBinaryStore;
    if (typeof inner.moveEntry !== "function") {
      return;
    }
    await inner.moveEntry(fromPath, toPath);
  }
  getFileUrl(id: string): string | null {
    const kit = this._kitStore.getSnapshot().kit;
    const fileState = getOrCreateKitFileState(this._kitStore);
    const file = kit.files?.find((existingFile) => existingFile.id === id);
    if (!file) {
      return null;
    }

    const readableUrl = getReadableKitFileUrl(fileState, file);
    if (readableUrl) {
      return readableUrl;
    }

    const provider = getExistingKitFileProvider(this._kitStore);
    if (!provider) {
      return file.remote && isBrowserReadableFileUrl(file.remote) ? file.remote : null;
    }

    const storagePath = getKitFileStoragePath(kit, file);
    const providerUrl = provider.getUrl(kit.id, file.id, storagePath);
    if (!providerUrl) {
      return file.remote && isBrowserReadableFileUrl(file.remote) ? file.remote : null;
    }

    fileState.providerUrls.set(id, providerUrl);
    if (isBrowserReadableFileUrl(providerUrl)) {
      return providerUrl;
    }

    return file.remote && isBrowserReadableFileUrl(file.remote) ? file.remote : null;
  }
  async getFileBlobUrl(id: string): Promise<string | null> {
    const fileState = getOrCreateKitFileState(this._kitStore);
    const cachedBlobUrl = fileState.objectUrls.get(id);
    if (cachedBlobUrl) {
      return cachedBlobUrl;
    }

    const pending = fileState.pendingBlobDownloads.get(id);
    if (pending) {
      return pending;
    }

    const downloadPromise = this._downloadFileBlobUrl(id, fileState);
    fileState.pendingBlobDownloads.set(id, downloadPromise);
    try {
      return await downloadPromise;
    } finally {
      fileState.pendingBlobDownloads.delete(id);
    }
  }
  private async _downloadFileBlobUrl(id: string, fileState: KitFileState): Promise<string | null> {
    const kit = this._kitStore.getSnapshot().kit;

    const cachedBlob = fileState.blobs.get(id);
    if (cachedBlob) {
      console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): using cached blob`);
      return createKitFileObjectUrl(this._kitStore, id, cachedBlob);
    }

    const file = kit.files?.find((existingFile) => existingFile.id === id);
    if (!file) {
      console.warn(`[DEBUG] _downloadFileBlobUrl(${id}): file not found in kit`);
      return null;
    }

    const storagePath = getKitFileStoragePath(kit, file);
    const binaryStore = this._kitStore as KitBinaryStore;
    if (typeof binaryStore.readFile === "function") {
      try {
        const blob = await binaryStore.readFile(storagePath);
        if (blob) {
          console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): loaded from binary store, size=${blob.size}`);
          fileState.blobs.set(id, blob);
          return createKitFileObjectUrl(this._kitStore, id, blob);
        }
      } catch (error) {
        console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): binary store read failed:`, error);
      }
    }

    const provider = await getKitFileProvider(this._kitStore, kit.id);
    if (provider) {
      try {
        const blob = await provider.download(kit.id, file.id, storagePath);
        console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): loaded from provider, size=${blob.size}`);
        fileState.blobs.set(id, blob);
        const providerUrl = provider.getUrl(kit.id, file.id, storagePath);
        if (providerUrl) {
          fileState.providerUrls.set(id, providerUrl);
        }
        return createKitFileObjectUrl(this._kitStore, id, blob);
      } catch (error) {
        console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): provider download failed:`, error);
      }
    } else {
      console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): no provider available`);
    }

    const readableUrl = getReadableKitFileUrl(fileState, file);
    if (readableUrl) {
      console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): trying readable URL: ${readableUrl}`);
      const blob = await fetchReadableKitFileBlob(readableUrl);
      if (blob) {
        console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): fetched from readable URL, size=${blob.size}`);
        fileState.blobs.set(id, blob);
        return createKitFileObjectUrl(this._kitStore, id, blob);
      }
    }

    const fallbackUrl = this.getFileUrl(id);
    console.debug(`[DEBUG] _downloadFileBlobUrl(${id}): all methods exhausted, fallback URL: ${fallbackUrl}`);
    return fallbackUrl;
  }
  subscribe(listener: () => void): () => void {
    return this._kitStore.subscribe(listener);
  }
  getSnapshot(): KitStoreSnapshot {
    return this._kitStore.getSnapshot();
  }
  /** Kit command dispatch (shared with {@link executeKitCommand}); used by tests and imperative callers. */
  execute<T = KitCommandResult>(command: string, origin?: string, ...args: any[]): Promise<T> {
    return executeKitCommand(this._kitStore, command, origin, ...args) as Promise<T>;
  }
}
// #endregion 🔑Entity Store Wrappers

type RootHostElement = HTMLElement & { __semioReactRoot__?: Root };

const getOrCreateDomRoot = (element: HTMLElement): Root => {
  const rootHost = element as RootHostElement;
  if (!rootHost.__semioReactRoot__) {
    rootHost.__semioReactRoot__ = createRoot(element);
  }
  return rootHost.__semioReactRoot__;
};

const clearDomRoot = (element: HTMLElement, root: Root): void => {
  const rootHost = element as RootHostElement;
  if (rootHost.__semioReactRoot__ === root) {
    delete rootHost.__semioReactRoot__;
  }
};

export type SketchpadKitStoreFactory = (kit: Kit) => KitStore | Promise<KitStore>;

export interface SketchpadKitKindAvailability {
  temporary: boolean;
  file: boolean;
  folder: boolean;
  remote: boolean;
}

// #region 🥈Entity Hooks
// Storage-agnostic entity scope providers and hooks.
// All entity data is accessed via KitStore.getSnapshot().kit selectors.

// ✍️#region 🎭Author Scope
type AuthorScope = { id: string };
const AuthorScopeContext = createContext<AuthorScope | null>(null);
export const AuthorScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(AuthorScopeContext.Provider, { value }, props.children as any);
};
const useAuthorScope = () => useContext(AuthorScopeContext);
// #endregion 🎭Author Scope

// 🔭#region 🏂Type Scope
type TypeScope = { id: string };
const TypeScopeContext = createContext<TypeScope | null>(null);
export const TypeScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(TypeScopeContext.Provider, { value }, props.children as any);
};
export const useTypeScope = () => useContext(TypeScopeContext);
export const useIsInTypeScope = () => useTypeScope() !== null;
// #endregion 🏂Type Scope

// 🔭#region 🎼Quality Scope
type QualityScope = { id: string };
const QualityScopeContext = createContext<QualityScope | null>(null);
export const QualityScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(QualityScopeContext.Provider, { value }, props.children as any);
};
export const useQualityScope = () => useContext(QualityScopeContext);
export const useIsInQualityScope = () => useQualityScope() !== null;
// #endregion 🎼Quality Scope

// 🔭#region 🎀Design Scope
type DesignScope = { id: string };
export const DesignScopeContext = createContext<DesignScope | null>(null);
export const DesignScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(DesignScopeContext.Provider, { value }, props.children as any);
};
export const useDesignScope = () => useContext(DesignScopeContext);
export const useIsInDesignScope = () => useDesignScope() !== null;
// #endregion 🎀Design Scope

// 🔭#region 🖲️Piece Scope
type PieceScope = { id: string };
const PieceScopeContext = createContext<PieceScope | null>(null);
export const PieceScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(PieceScopeContext.Provider, { value }, props.children as any);
};
export const usePieceScope = () => useContext(PieceScopeContext);
// #endregion 🖲️Piece Scope

// 🔌#region 🎛️Connection Scope
type ConnectionScope = { id: string };
const ConnectionScopeContext = createContext<ConnectionScope | null>(null);
export const ConnectionScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = useMemo(() => ({ id: props.id }), [props.id]);
  return React.createElement(ConnectionScopeContext.Provider, { value }, props.children as any);
};
export const useConnectionScope = () => useContext(ConnectionScopeContext);
// #endregion 🎛️Connection Scope

// #region ⏰Entity Data Hooks

/** Kit snapshot from {@link KitProvider} only — not {@link useSketchpadStore}. */
function useLocalKitSnapshot(): Kit | null {
  const runtime = useKitRuntimeSafe();
  return runtime?.snapshot.kit ?? null;
}

export function useAuthor<T>(selector?: (author: Author) => T, id?: Id, deep: boolean = false): T | Author | null {
  const authorScope = useAuthorScope();
  const authorId = authorScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !authorId) return null;
  const author = kit.authors?.find((a) => a.id === authorId) ?? null;
  if (!author) return null;
  return selector ? selector(author) : (author as any);
}

export function useType<T>(selector?: (type: Type) => T, id?: Id, deep: boolean = false): T | Type | null {
  const typeScope = useTypeScope();
  const typeId = typeScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !typeId) return null;
  const type = kit.types?.find((t) => t.id === typeId) ?? null;
  if (!type) return null;
  return selector ? selector(type) : (type as any);
}

export function useQuality<T>(selector?: (quality: Quality) => T, id?: Id, deep: boolean = false): T | Quality | null {
  const qualityScope = useQualityScope();
  const qualityId = qualityScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !qualityId) return null;
  const quality = kit.qualities?.find((q) => q.id === qualityId) ?? null;
  if (!quality) return null;
  return selector ? selector(quality) : (quality as any);
}

export function useDesign<T = Design>(selector?: (design: Design) => T, deep?: boolean, id?: string): T | Design | null {
  const designScope = useDesignScope();
  const designId = designScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !designId) return null;
  const design = kit.designs?.find((d) => d.id === designId) ?? null;
  if (!design) return null;
  return selector ? selector(design) : (design as any);
}

export function usePiece<T>(selector?: (piece: Piece) => T, id?: Id, deep: boolean = false): T | Piece | null {
  const designScope = useDesignScope();
  const pieceScope = usePieceScope();
  const pieceId = pieceScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !pieceId || !designScope) return null;
  const design = kit.designs?.find((d) => d.id === designScope.id);
  const piece = design?.pieces?.find((p) => p.id === pieceId) ?? null;
  if (!piece) return null;
  return selector ? selector(piece) : (piece as any);
}

export function useConnection<T>(selector?: (connection: Connection) => T, id?: Id, deep: boolean = false): T | Connection | null {
  const designScope = useDesignScope();
  const connectionScope = useConnectionScope();
  const connectionId = connectionScope?.id ?? id;
  const kit = useLocalKitSnapshot();
  if (!kit || !connectionId || !designScope) return null;
  const design = kit.designs?.find((d) => d.id === designScope.id);
  const connection = design?.connections?.find((c) => c.id === connectionId) ?? null;
  if (!connection) return null;
  return selector ? selector(connection) : (connection as any);
}

const EMPTY_PIECES: Piece[] = [];
const EMPTY_CONNECTIONS: Connection[] = [];

export function usePieces(): Piece[] {
  const designScope = useDesignScope();
  const kit = useLocalKitSnapshot();
  if (!kit || !designScope) return EMPTY_PIECES;
  const design = kit.designs?.find((d) => d.id === designScope.id);
  return design?.pieces ?? EMPTY_PIECES;
}

export function useConnections(): Connection[] {
  const designScope = useDesignScope();
  const kit = useLocalKitSnapshot();
  if (!kit || !designScope) return EMPTY_CONNECTIONS;
  const design = kit.designs?.find((d) => d.id === designScope.id);
  return design?.connections ?? EMPTY_CONNECTIONS;
}

