// #region ⏱️Kit
// Storage-agnostic kit store hooks using KitStore interface.

/**
 * Execute a kit command against a KitStore.
 * Looks up the command in kitCommands, builds context from snapshot, applies diff.
 **/
async function executeKitCommand(kitStore: KitStore, command: string, origin?: string, ...args: any[]): Promise<KitCommandResult> {
  const callback = kitCommands[command as keyof typeof kitCommands];
  if (!callback) throw new Error(`Command "${command}" not found in kit commands`);
  const context: KitCommandContext = {
    kit: kitStore.getSnapshot().kit,
    fileUrls: getStoredKitFileUrls(kitStore),
    origin,
  };
  const result = (callback as any)(context, ...args);
  if (result.diff) {
    kitStore.apply(result.diff, { origin });
  }
  await syncKitFileCommandResult(kitStore, context.kit, command, args, result);
  return result;
}
/**
 * KitScope holds the data fields for a KitScope record.
 **/
type KitScope = { id: string };
/**
 * KitScopeContext holds the data fields for a KitScopeContext record.
 **/
export const KitScopeContext = createContext<KitScope | null>(null);

/**
 * Registers the sketchpad kit's inner {@link KitStore} with {@link KitRegistryProvider}
 * and wraps children with {@link KitProvider} so `@semio/react` command/query hooks work.
 */
function KitWasmRuntimeBridge(props: { kitId: string; children: React.ReactNode }): React.ReactElement {
  const { kitId, children } = props;
  const sketchpadStore = useSketchpadStore();
  const registry = useKitRegistrySafe();
  const [, bump] = useReducer((x: number) => x + 1, 0);

  useEffect(() => {
    if (!registry || !sketchpadStore.hasKit(kitId)) return;
    const innerStore = sketchpadStore.kit(kitId).store;
    let cancelled = false;
    void (async () => {
      await registry.open(kitId, { store: innerStore });
      if (!cancelled) bump();
    })();
    return () => {
      cancelled = true;
      registry.close(kitId);
    };
  }, [sketchpadStore, kitId, registry]);

  if (!sketchpadStore.hasKit(kitId)) {
    return React.createElement(React.Fragment, null, children);
  }

  const innerStore = sketchpadStore.kit(kitId).store;
  if (registry) {
    const status = registry.status(kitId);
    const entry = registry.get(kitId);
    if (status === "ready" && entry) {
      return React.createElement(KitProvider, { kitId, store: entry.store, kitClient: entry.kitClient, children });
    }
  }
  return React.createElement(KitProvider, { store: innerStore, children });
}

/**
 * React context provider scoping kit by id.
 **/
export const KitScopeProvider = (props: { id: string; children: React.ReactNode }) => {
  return React.createElement(KitWasmRuntimeBridge, { kitId: props.id, children: props.children as any });
};
/**
 * Resolves the active kit id: R3F {@link SceneContextBridge} re-provides {@link KitScopeContext};
 * the DOM tree uses {@link useActiveKitId} from {@link KitProvider}.
 **/
export const useKitScope = (): KitScope | null => {
  const bridged = useContext(KitScopeContext);
  if (bridged) return bridged;
  const g = useActiveKitId();
  return g != null && g !== "" ? { id: g } : null;
};
/**
 * Hook returning whether a kit scope is active.
 **/
export const useIsInKitScope = () => useKitScope() !== null;

/**
 * {@link KitStore} from the nearest {@link KitProvider} / {@link useKitRuntimeSafe} when the active runtime kit matches.
 * When `explicitKitId` is set (e.g. {@link useKitCommandsById}), only `runtime.kitId === explicitKitId` is required
 * so callers need not be under {@link useKitScope} as long as {@link KitProvider} is for that kit.
 */
function useKitStoreFromProvider(explicitKitId?: string): KitStore | null {
  const runtime = useKitRuntimeSafe();
  if (!runtime) return null;
  const kitScope = useKitScope();
  const effectiveKitId = explicitKitId ?? kitScope?.id;
  if (!effectiveKitId) return null;
  if (runtime.kitId !== effectiveKitId) return null;
  return runtime.store;
}

/**
 * Hook for accessing kit data with optional selector.
 **/
export function useKit<T>(selector?: (kit: Kit) => T, id?: Id): T | Kit | null {
  const kitScope = useKitScope();
  const resolvedId = id ?? kitScope?.id;
  const kitStore = useKitStoreFromProvider(resolvedId ?? undefined);
  const subscribe = useCallback(
    (cb: () => void) => {
      if (!kitStore) return () => {};
      return kitStore.subscribe(cb);
    },
    [kitStore],
  );
  const getSnapshot = useCallback(() => {
    if (!kitStore) return null;
    const kit = kitStore.getSnapshot().kit;
    return selector ? selector(kit) : kit;
  }, [kitStore, selector]);
  return useSyncExternalStore(subscribe, getSnapshot) as T | Kit | null;
}

