// #region 📮Machine

// #region ⚙️Types
// Type definitions for app state, machine input, and context structures.

/**
 * Default panel visibility configuration with all panels hidden.
 **/
export const defaultPanelVisibility: PanelVisibility = {
  toolbar: true,
  leftSidePanel: false,
  rightSidePanel: true,
  details: true,
};

// #region 🔬App State Types
// State shape interfaces for all application views: home, kit, design, type, quality.

/**
 * Selection state for the home app view.
 **/
export interface HomeAppSelection {
  kits?: Id[];
}
/**
 * State for the home app view including panel visibility, selection, and sorting.
 **/
export interface HomeAppState {
  panelVisibility: PanelVisibility;
  selection?: HomeAppSelection;
  hover?: { kits?: Id[] };
  sortColumn?: string;
  sortDirection?: "asc" | "desc";
  loadingKits: Array<{ tempId: string; name: string }>;
}

/**
 * Kind of feedback: bug report or idea suggestion.
 **/
export type FeedbackKind = "bug" | "idea";
/**
 * Kind of app context for feedback submission.
 **/
export type FeedbackAppKind = "home" | "kit" | "design" | "type" | "quality" | "docs" | "feedback";
/**
 * Form data shape for feedback submissions.
 **/
export interface FeedbackFormData {
  kind: FeedbackKind;
  title: string;
  description: string;
  app?: FeedbackAppKind;
  name?: string;
  email?: string;
}
/**
 * State for the feedback app view.
 **/
export interface FeedbackAppState {
  panelVisibility: PanelVisibility;
  formData: FeedbackFormData;
  isSubmitting: boolean;
  isSubmitted: boolean;
  error?: string;
}
/**
 * Force simulation settings for the kit diagram view.
 **/
export interface DiagramForceSettings {
  chargeStrength: number;
  linkDistance: number;
  collideRadius: number;
  centerStrength: number;
}
/**
 * Default force simulation settings for the kit diagram.
 **/
export const defaultDiagramForceSettings: DiagramForceSettings = {
  chargeStrength: -150,
  linkDistance: 100,
  collideRadius: 40,
  centerStrength: 0.05,
};
/**
 * Fullscreen window options for the kit app view.
 **/
export enum KitAppFullscreenWindow {
  None = "none",
  Table = "table",
  Diagram = "diagram",
}

/**
 * Selection state for the type app view.
 **/
export interface TypeAppSelection {
  connectors?: Id[];
  representations?: Id[];
}
/**
 * Hover state for the type app view.
 **/
export interface TypeAppHover {
  connector?: Id;
  representation?: Id;
}
/**
 * Fullscreen window options for the type app view.
 **/
export enum TypeAppFullscreenWindow {
  None = "none",
  Connectors = "connectors",
  Representations = "representations",
}

/**
 * Fullscreen window options for the design app view.
 **/
export enum DesignAppFullscreenWindow {
  None = "none",
  Diagram = "diagram",
  Accessl = "accessl",
}

/**
 * Single step in a tutorial sequence.
 **/
export interface TutorialStep {
  id: string;
  title: string;
  description?: string;
  target?: string;
  action?: string;
  completed?: boolean;
}

/**
 * Context state for managing the active tutorial and progress.
 **/
export interface SketchpadTutorialContext {
  activeTutorial?: string;
  currentStepIndex: number;
  steps: TutorialStep[];
  completedSteps: Set<string>;
  isRecording: boolean;
  recordingState: "idle" | "recording" | "paused";
  recordedEvents: any[];
}

// #endregion 🔬App State Types

/**
 * Input configuration for the sketchpad XState machine.
 **/
export interface SketchpadMachineInput {
  id?: string;
  initialState?: Partial<SketchpadState>;
}

/**
 * Context state shape for the sketchpad XState machine.
 **/
export interface SketchpadContext {
  id?: string;
  sketchpad: SketchpadState;

  kits: Record<Id, AnyActorRef>;

  homeApp: HomeAppState;
  kitApps: Record<Id, KitAppState>;
  typeApps: Record<string, TypeAppState>;
  designApps: Record<string, DesignAppState>;
  qualityApps: Record<string, QualityAppState>;
  feedbackApp: FeedbackAppState;
  tutorial: TutorialState;

  backgroundOperations: Record<string, { type: string; status: "pending" | "running" | "completed" | "failed"; error?: string }>;
}

/**
 * Union type of all events the sketchpad machine can receive.
 **/
export type SketchpadEvent =
  | { type: "NAVIGATE"; path: string }
  | { type: "NAVIGATE_BACK" }
  | { type: "NAVIGATE_FORWARD" }
  | { type: "SET_THEME"; theme: Theme }
  | { type: "SET_LANGUAGE"; language: string }
  | { type: "SET_EXPERTISE"; expertise: Expertise }
  | { type: "SET_MODE"; mode: Mode }
  | { type: "SET_DEVICE"; device: Device }
  | { type: "TOGGLE_FULLSCREEN" }
  | { type: "SET_PANEL_SIZE"; panel: keyof PanelSizes; size: number }
  | { type: "CREATE_KIT"; kit: Kit; kind?: KitKind }
  | { type: "DELETE_KIT"; id: Id }
  | { type: "CHANGE"; diff: SketchpadDiff }
  // Home app events
  | { type: "HOME.TOGGLE_PANEL"; panel: keyof PanelVisibility }
  | { type: "HOME.SET_PANEL_VISIBILITY"; panelVisibility: PanelVisibility }
  | { type: "HOME.SET_SORT"; column: string; direction: "asc" | "desc" }
  | { type: "HOME.SELECT_KIT"; id: Id }
  | { type: "HOME.DESELECT_KIT"; id: Id }
  | { type: "HOME.CLEAR_SELECTION" }
  | { type: "HOME.SET_HOVER"; kits?: Id[] }
  | { type: "HOME.CLEAR_HOVER" }
  // Kit app events (scoped by kitId)
  | { type: "KIT.INIT"; kitId: Id; state: KitAppState }
  | { type: "KIT.SYNC"; kitId: Id; state: Partial<KitAppState> }
  | { type: "KIT.TOGGLE_PANEL"; kitId: Id; panel: keyof PanelVisibility }
  | { type: "KIT.SET_PANEL_VISIBILITY"; kitId: Id; panelVisibility: PanelVisibility }
  | { type: "KIT.SET_FILTER"; kitId: Id; search: string }
  | { type: "KIT.TOGGLE_ROW"; kitId: Id; rowId: string }
  | { type: "KIT.SET_EXPANDED_ROWS"; kitId: Id; expandedRows: Set<string> }
  | { type: "KIT.SET_SORT"; kitId: Id; column: string; direction: "asc" | "desc" }
  | { type: "KIT.SELECT_TYPE"; kitId: Id; typeId: Id }
  | { type: "KIT.DESELECT_TYPE"; kitId: Id; typeId: Id }
  | { type: "KIT.SELECT_DESIGN"; kitId: Id; designId: Id }
  | { type: "KIT.DESELECT_DESIGN"; kitId: Id; designId: Id }
  | { type: "KIT.SET_SELECTION"; kitId: Id; selection: KitAppSelection }
  | { type: "KIT.CLEAR_SELECTION"; kitId: Id }
  | { type: "KIT.SET_HOVER"; kitId: Id; hover: any }
  | { type: "KIT.CLEAR_HOVER"; kitId: Id }
  | { type: "KIT.SET_FULLSCREEN"; kitId: Id; window: KitAppFullscreenWindow }
  | { type: "KIT.SET_WINDOW_LAYOUT"; kitId: Id; windowLayout: any }
  | { type: "KIT.SET_DIAGRAM_FORCE"; kitId: Id; diagramForce: Partial<DiagramForceSettings> }
  // Type app events (scoped by kitId:typeId)
  | { type: "TYPE.INIT"; kitId: Id; typeId: Id; state: TypeAppState }
  | { type: "TYPE.SYNC"; kitId: Id; typeId: Id; state: Partial<TypeAppState> }
  | { type: "TYPE.TOGGLE_PANEL"; kitId: Id; typeId: Id; panel: keyof PanelVisibility }
  | { type: "TYPE.SET_PANEL_VISIBILITY"; kitId: Id; typeId: Id; panelVisibility: PanelVisibility }
  | { type: "TYPE.SET_ACTIVE_TOOL"; kitId: Id; typeId: Id; tool: ToolKind }
  | { type: "TYPE.SET_FULLSCREEN_WINDOW"; kitId: Id; typeId: Id; window: TypeAppFullscreenWindow }
  | { type: "TYPE.SET_SELECTION"; kitId: Id; typeId: Id; selection: TypeAppSelection }
  | { type: "TYPE.CLEAR_SELECTION"; kitId: Id; typeId: Id }
  | { type: "TYPE.SELECT_CONNECTOR"; kitId: Id; typeId: Id; connectorId: Id }
  | { type: "TYPE.DESELECT_CONNECTOR"; kitId: Id; typeId: Id; connectorId: Id }
  | { type: "TYPE.SET_HOVER"; kitId: Id; typeId: Id; hover: { connector?: Id; representation?: Id } }
  | { type: "TYPE.CLEAR_HOVER"; kitId: Id; typeId: Id }
  | { type: "TYPE.FOCUS_CONNECTOR"; kitId: Id; typeId: Id; connectorId?: Id }
  | { type: "TYPE.SELECT_REPRESENTATION_TAG"; kitId: Id; typeId: Id; tagId: Id }
  | { type: "TYPE.DESELECT_REPRESENTATION_TAG"; kitId: Id; typeId: Id; tagId: Id }
  | { type: "TYPE.SET_REPRESENTATION_TAGS"; kitId: Id; typeId: Id; tags: Id[] }
  | { type: "TYPE.SET_CAMERA"; kitId: Id; typeId: Id; camera: any }
  | { type: "TYPE.SELECT_ALL"; kitId: Id; typeId: Id }
  | { type: "TYPE.DESELECT_ALL"; kitId: Id; typeId: Id }
  | { type: "TYPE.CLEAR_FOCUS"; kitId: Id; typeId: Id }
  | { type: "TYPE.SELECT_REPRESENTATION"; kitId: Id; typeId: Id; representationId: Id }
