/**
 * ErrorBoundary holds the data fields for a ErrorBoundary record.
 **/
class ErrorBoundary extends React.Component<{ children: React.ReactNode; fallback: React.ReactNode }, { hasError: boolean; error: Error | null }> {
  constructor(props: { children: React.ReactNode; fallback: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {}

  componentDidUpdate(prevProps: { children: React.ReactNode; fallback: React.ReactNode }) {
    if (prevProps.children !== this.props.children && this.state.hasError) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback;
    }
    return this.props.children;
  }
}
/**
 * useKitAppYjsToXStateSync holds the data fields for a useKitAppYjsToXStateSync record.
 **/
function useKitAppYjsToXStateSync() {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const kitId = kitScope?.id ?? "";
  const sketchpadStore = useSketchpadStore();
  const sketchpadCommands = useSketchpadCommands();
  const hasKit = useHasKit(kitId);
  const initializedKeyRef = useRef<string | null>(null);
  const syncedKeyRef = useRef<string | null>(null);

  useLayoutEffect(() => {
    if (!kitId || !hasKit) return;

    if (!sketchpadStore.hasKitApp({ kit: kitId })) {
      sketchpadCommands.createKitApp("semio.sketchpad.app.kit.autoCreateForSync", { kit: kitId });
    }
  }, [kitId, hasKit, sketchpadStore, sketchpadCommands]);

  useLayoutEffect(() => {
    if (!kitId || !hasKit) return;
    const initKey = kitId;
    if (initializedKeyRef.current === initKey) return;

    let xstateInitialState;
    if (sketchpadStore.hasKitApp({ kit: kitId })) {
      const store = sketchpadStore.kitApp(kitId);
      const initialState = store.snapshot();

      xstateInitialState = {
        ...createDefaultKitAppState(),
        ...initialState,
        activeTool: initialState.activeTool ?? ToolKind.SELECTION_NORMAL,
        expandedRows: new Set(initialState.expandedRows || []),
        transaction: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      };
    } else {
      xstateInitialState = {
        ...createDefaultKitAppState(),
        panelVisibility: defaultPanelVisibility,
        activeTool: ToolKind.SELECTION_NORMAL,
        expandedRows: new Set(),
        transaction: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      };
    }

    actor.send({
      type: "KIT.INIT",
      kitId,
      state: xstateInitialState,
    });
    initializedKeyRef.current = initKey;
  }, [actor, sketchpadStore, kitId, hasKit]);

  useEffect(() => {
    if (!kitId || !hasKit || initializedKeyRef.current !== kitId) return;
    if (syncedKeyRef.current === kitId) return;
    if (!sketchpadStore.hasKitApp({ kit: kitId })) return;

    const store = sketchpadStore.kitApp(kitId);
    const currentState = store.snapshot();

    const xstateState = {
      ...currentState,
      expandedRows: new Set(currentState.expandedRows || []),
    };

    actor.send({
      type: "KIT.SYNC",
      kitId,
      state: xstateState,
    });
    syncedKeyRef.current = kitId;
  }, [actor, sketchpadStore, kitId, hasKit]);
}

/** App holds the data fields for a App record.
 **/
/**
 **/
const KitTableApp: FC = () => {
  useKitAppYjsToXStateSync();
  const transaction = useKitAppTransaction();
  const { undo, redo, deleteSelected } = useKitAppCommands();
  useHotkeys("ctrl+z", () => undo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+y", () => redo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+shift+z", () => redo?.(), { enableOnFormTags: true });
  useHotkeys("delete,backspace", () => deleteSelected?.(), { enableOnFormTags: true });

  return (
    <ErrorBoundary
      fallback={
        <div className="flex items-center justify-center h-full">
          <p className="text-sm text-muted-foreground">Failed to load kit app</p>
        </div>
      }
    >
      <TransactionProvider transaction={transaction}>
        <KitDropZone>
          <Canvas>
            <Window id="kit-table">
              <AppContent />
            </Window>
          </Canvas>
        </KitDropZone>
      </TransactionProvider>
    </ErrorBoundary>
  );
};

// #endregion 🛎️Table

// #region 🧫Diagram
// Diagram MUST render the interactive force-directed Kit diagram with type and design nodes.

/**
 * KitDiagramNode holds the data fields for a KitDiagramNode record.
 **/
interface KitDiagramNode extends Record<string, unknown> {
  id: string;
  name: string;
  kind: KitDiagramNodeKind;
  icon?: string | React.ReactNode;
  parentId?: string;
}

/**
 * KitDiagramEdge holds the data fields for a KitDiagramEdge record.
 **/
interface KitDiagramEdge {
  id: string;
  source: string;
  target: string;
  relationship: "part-of" | "reference";
}

/** KitArtifactNode holds the data fields for a KitArtifactNode record.
 **/
/**
 **/
const KitArtifactNode: FC<NodeProps<Node<KitDiagramNode>>> = ({ data }) => {
  const [selection] = useKitAppSelection();
  const [hover] = useKitAppHover();
  const strategy = useMemo(() => getKitDiagramShapeStrategy(data.kind), [data.kind]);
  const frame = useMemo(() => getKitDiagramNodeFrameForKind(data.kind), [data.kind]);
  const renderPayload = useMemo<KitDiagramShapeRenderPayload>(() => strategy.getRenderPayload(), [strategy]);

  const isHovered = useMemo(() => {
    if (!hover) return false;
    if (data.kind === "type") return hover.type === data.id;
    if (data.kind === "design") return hover.design === data.id;
    if (data.kind === "quality") return hover.quality === data.id;
    if (data.kind === "port") return hover.port === data.id;
    if (data.kind === "file") return hover.file === data.id;
    if (data.kind === "folder") return hover.folder === data.id;
    if (data.kind === "author") return hover.author === data.id;
    return false;
  }, [hover, data.kind, data.id]);

  const isSelected = useMemo(() => {
    if (!selection) return false;
    switch (data.kind) {
      case "type":
        return selection.types?.includes(data.id) ?? false;
      case "design":
        return selection.designs?.includes(data.id) ?? false;
      case "quality":
        return selection.qualities?.includes(data.id) ?? false;
      case "port":
        return selection.ports?.includes(data.id) ?? false;
      case "file":
        return selection.files?.includes(data.id) ?? false;
      case "folder":
        return selection.folders?.includes(data.id) ?? false;
      case "author":
        return selection.authors?.includes(data.id) ?? false;
      default:
        return false;
    }
  }, [selection, data.kind, data.id]);

  return (
    <div
      data-kit-node="v3"
      data-kit-node-shape={strategy.id}
      data-kit-node-kind={data.kind}
      style={{
        width: `${frame.width}px`,
        height: `${frame.height}px`,
        position: "relative",
        background: "transparent",
        border: "0",
        outline: "0",
        boxShadow: "none",
        pointerEvents: "auto",
        padding: 0,
        margin: 0,
      }}
      title={data.name || data.id.substring(0, 8)}
    >
      <Handle type="target" position={Position.Top} className="!bg-transparent !border-none !w-0 !h-0 !min-w-0 !min-h-0" />
      <Handle type="source" position={Position.Bottom} className="!bg-transparent !border-none !w-0 !h-0 !min-w-0 !min-h-0" />
      <Handle type="target" position={Position.Left} className="!bg-transparent !border-none !w-0 !h-0 !min-w-0 !min-h-0" />
      <Handle type="source" position={Position.Right} className="!bg-transparent !border-none !w-0 !h-0 !min-w-0 !min-h-0" />
      <TableAvatar
        id="semio.sketchpad.app.kit.diagram.node.avatar"
        className={`!absolute !inset-0 ${renderPayload.className ?? ""}`}
        name={data.name}
        icon={data.icon}
        isSelected={isSelected}
        isHovered={isHovered}
        style={{ width: `${frame.width}px`, height: `${frame.height}px`, ...(renderPayload.style as React.CSSProperties | undefined) }}
      />
    </div>
  );
};

/**
 * kitNodeTypes holds the data fields for a kitNodeTypes record.
 **/
const kitNodeTypes = {
  artifact: KitArtifactNode,
};

/**
 * edgeStyle holds the data fields for a edgeStyle record.
 **/
const edgeStyle = {
  "part-of": { stroke: "var(--accent-secondary)", strokeWidth: 3 },
  reference: { stroke: "var(--foreground)", strokeWidth: 1, strokeDasharray: "5,5" },
};

/**
 * KIT_DIAGRAM_DEBUG holds the data fields for a KIT_DIAGRAM_DEBUG record.
 **/
const KIT_DIAGRAM_DEBUG = false;
/**
 * KIT_DIAGRAM_DEBUG_INTERVAL_MS holds the data fields for a KIT_DIAGRAM_DEBUG_INTERVAL_MS record.
 **/
const KIT_DIAGRAM_DEBUG_INTERVAL_MS = 400;

/**
 * KIT_DIAGRAM_FALLBACK_KIND holds the data fields for a KIT_DIAGRAM_FALLBACK_KIND record.
 **/
const KIT_DIAGRAM_FALLBACK_KIND: KitDiagramNodeKind = "quality";
/**
 * KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE holds the data fields for a KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE record.
 **/
const KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE = Math.max(KIT_DIAGRAM_DEFAULT_SHAPE_STRATEGY.frame.width, KIT_DIAGRAM_DEFAULT_SHAPE_STRATEGY.frame.height) * 0.55;

/** isKitDiagramNodeKind holds the data fields for a isKitDiagramNodeKind record.
 **/
/**
 **/
const isKitDiagramNodeKind = (value: string): value is KitDiagramNodeKind => value === "type" || value === "design" || value === "quality" || value === "port" || value === "file" || value === "folder" || value === "author";
/**
 * toReactFlowPosition holds the data fields for a toReactFlowPosition record.
 **/
const toReactFlowPosition = (side: "top" | "right" | "bottom" | "left"): Position => {
  if (side === "top") return Position.Top;
  if (side === "right") return Position.Right;
  if (side === "bottom") return Position.Bottom;
  return Position.Left;
};
/**
 * resolveDiagramNodeKind holds the data fields for a resolveDiagramNodeKind record.
 **/
const resolveDiagramNodeKind = (node: any): KitDiagramNodeKind => {
  const dataKind = (node?.data as KitDiagramNode | undefined)?.kind;
  if (dataKind && isKitDiagramNodeKind(dataKind)) return dataKind;
  const idKind = typeof node?.id === "string" ? node.id.split(":", 2)[0] : "";
  if (isKitDiagramNodeKind(idKind)) return idKind;
  return KIT_DIAGRAM_FALLBACK_KIND;
};
/**
 * resolveDiagramNodePosition holds the data fields for a resolveDiagramNodePosition record.
 **/
const resolveDiagramNodePosition = (node: any): { x: number; y: number } => {
  const position = node?.internals?.positionAbsolute ?? node?.positionAbsolute ?? node?.position;
  if (position && Number.isFinite(position.x) && Number.isFinite(position.y)) return position;
  return { x: 0, y: 0 };
};
/**
 * resolveDiagramNodeFrame holds the data fields for a resolveDiagramNodeFrame record.
 **/
const resolveDiagramNodeFrame = (node: any, kind: KitDiagramNodeKind) => normalizeKitDiagramFrame({ width: node?.width, height: node?.height }, getKitDiagramNodeFrameForKind(kind));
/**
 * resolveDiagramEdgeAnchors holds the data fields for a resolveDiagramEdgeAnchors record.
 **/
const resolveDiagramEdgeAnchors = (sourceNode: any, targetNode: any) => {
  const sourceKind = resolveDiagramNodeKind(sourceNode);
  const targetKind = resolveDiagramNodeKind(targetNode);
  const sourcePosition = resolveDiagramNodePosition(sourceNode);
  const targetPosition = resolveDiagramNodePosition(targetNode);
  const sourceFrame = resolveDiagramNodeFrame(sourceNode, sourceKind);
  const targetFrame = resolveDiagramNodeFrame(targetNode, targetKind);
  const anchors = resolveKitDiagramAnchorPair({ kind: sourceKind, position: sourcePosition, frame: sourceFrame }, { kind: targetKind, position: targetPosition, frame: targetFrame });
  return {
    sx: anchors.source.absolutePoint.x,
    sy: anchors.source.absolutePoint.y,
    tx: anchors.target.absolutePoint.x,
    ty: anchors.target.absolutePoint.y,
    sourcePos: toReactFlowPosition(anchors.source.localPoint.side),
    targetPos: toReactFlowPosition(anchors.target.localPoint.side),
  };
};

/** FloatingEdge holds the data fields for a FloatingEdge record.
 **/
/**
 **/
const FloatingEdge: FC<EdgeProps> = ({ id, source, target, markerEnd, style, selected, data }) => {
  const sourceNode = useInternalNode(source);
  const targetNode = useInternalNode(target);
  const debugLogRef = useRef(0);

  if (!sourceNode || !targetNode) {
    return null;
  }

  const { sx, sy, tx, ty, sourcePos: sPos, targetPos: tPos } = resolveDiagramEdgeAnchors(sourceNode, targetNode);

  const [edgePath] = getBezierPath({
    sourceX: sx,
    sourceY: sy,
    sourcePosition: sPos,
    targetX: tx,
    targetY: ty,
    targetPosition: tPos,
  });

  const relationship = data?.relationship as "part-of" | "reference";
  let stroke = relationship === "part-of" ? "var(--accent-secondary)" : "var(--foreground)";
  let strokeWidth = relationship === "reference" ? 1 : 3;
  let dasharray = relationship === "reference" ? "5 5" : undefined;
  let opacity = 1;

  if (selected) {
    stroke = "var(--active-base)";
    strokeWidth = Math.max(strokeWidth, 3);
    dasharray = undefined;
    opacity = 1;
  }

  return (
    <g>
      <BaseEdge
        id={id}
        path={edgePath}
        style={{
          ...style,
          stroke,
          strokeWidth,
          strokeDasharray: dasharray,
          opacity,
        }}
        className="transition-colors duration-200"
      />
      {KIT_DIAGRAM_DEBUG ? <circle cx={sx} cy={sy} r={3} fill="var(--accent-secondary)" stroke="none" pointerEvents="none" /> : null}
      {KIT_DIAGRAM_DEBUG ? <circle cx={tx} cy={ty} r={3} fill="var(--foreground)" stroke="none" pointerEvents="none" /> : null}
    </g>
  );
};
/**
 * FloatingConnectionLine holds the data fields for a FloatingConnectionLine record.
 **/
const FloatingConnectionLine: FC<ConnectionLineComponentProps> = ({ fromX, fromY, toX, toY, fromNode, toNode, pointer }) => {
  const { getNodes } = useReactFlow();
  const fromKind = resolveDiagramNodeKind(fromNode);
  const fromPosition = resolveDiagramNodePosition(fromNode);
  const fromFrame = resolveDiagramNodeFrame(fromNode, fromKind);
  const targetPoint = pointer ?? { x: toX, y: toY };
  const sourceDirection = kitDiagramVector(kitDiagramToAbsolutePoint(fromPosition, { x: fromFrame.width / 2, y: fromFrame.height / 2 }), targetPoint);
  const sourceAnchor = getKitDiagramShapeStrategy(fromKind).resolveNearestPoint(sourceDirection, fromFrame);
  let sourceX = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).x;
  let sourceY = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).y;
  let sourcePosition = toReactFlowPosition(sourceAnchor.side);
  let targetX = toX;
  let targetY = toY;
  let targetPosition = toNode ? Position.Top : toY >= fromY ? Position.Bottom : Position.Top;

  if (toNode) {
    const resolved = resolveDiagramEdgeAnchors(fromNode, toNode);
    sourceX = resolved.sx;
    sourceY = resolved.sy;
    sourcePosition = resolved.sourcePos;
    targetX = resolved.tx;
    targetY = resolved.ty;
    targetPosition = resolved.targetPos;
  } else {
    const proximity = getNodes()
      .filter((node) => node.id !== fromNode.id)
      .map((node) => {
        const kind = resolveDiagramNodeKind(node);
        const position = resolveDiagramNodePosition(node);
        const frame = resolveDiagramNodeFrame(node, kind);
        return resolveKitDiagramProximityAnchor(node.id, { kind, position, frame }, targetPoint);
      })
      .sort((a, b) => a.distance - b.distance)[0];

    if (proximity && proximity.distance <= KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE) {
      targetX = proximity.anchor.absolutePoint.x;
      targetY = proximity.anchor.absolutePoint.y;
      targetPosition = toReactFlowPosition(proximity.anchor.localPoint.side);
    } else {
      targetPosition = toReactFlowPosition(kitDiagramInferSnapSide({ x: toX - fromPosition.x, y: toY - fromPosition.y }, fromFrame, fromFrame));
    }
  }
  const edgePath = getBezierPath({
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  })[0];

  return <BaseEdge path={edgePath} style={{ stroke: "var(--active-base)", strokeWidth: 3 }} />;
};
/**
 * buildKitDiagramData holds the data fields for a buildKitDiagramData record.
 **/
const buildKitDiagramData = (kit: Kit): { nodes: Node<KitDiagramNode>[]; edges: Edge[] } => {
  const nodes: Node<KitDiagramNode>[] = [];
  const edges: Edge[] = [];

  const kindGroups: KitDiagramNodeKind[] = ["type", "design", "quality", "port", "file", "folder", "author"];

  for (const kind of kindGroups) {
    let items: Array<{ id: string; name: string; icon?: any; parentId?: string }> = [];

    switch (kind) {
      case "type":
        items = (kit.types ?? []).filter(Boolean).map((t) => ({
          id: t.id,
          name: t.name,
          icon: t.icon,
          parentId: t.parent?.id,
        }));
        break;
      case "design":
        items = (kit.designs ?? []).filter(Boolean).map((d) => ({
          id: d.id,
          name: d.name,
          icon: d.icon,
          parentId: d.parent?.id,
        }));
        break;
      case "quality":
        items = (kit.qualities ?? []).filter(Boolean).map((q) => ({ id: q.id, name: q.name, icon: q.icon }));
        break;
      case "port":
        items = (kit.ports ?? []).filter(Boolean).map((i) => ({ id: i.id, name: i.name, icon: i.icon }));
        break;
      case "file":
        items = (kit.files ?? []).filter(Boolean).map((f) => ({ id: f.id, name: f.name, icon: getFileIcon(f.name), parentId: f.folder?.id }));
        break;
      case "folder":
        items = (kit.folders ?? []).filter(Boolean).map((f) => ({ id: f.id, name: f.name, icon: <FolderIcon className="size-tiny" />, parentId: f.parent?.id }));
        break;
      case "author":
        items = (kit.authors ?? []).filter(Boolean).map((a) => ({ id: a.id, name: a.name, icon: <UserIcon className="size-tiny" /> }));
        break;
    }

    for (const item of items) {
      const nodeId = `${kind}:${item.id}`;
      const frame = getKitDiagramNodeFrameForKind(kind);
      nodes.push({
        id: nodeId,
        type: "artifact",
        position: { x: 0, y: 0 },
        width: frame.width,
        height: frame.height,
        data: {
          id: item.id,
          name: item.name,
          kind,
          icon: item.icon,
          parentId: item.parentId,
        },
      });

      if (item.parentId) {
        let parentKind = kind;
        if (kind === "file") parentKind = "folder";
        edges.push({
          id: `${kind}-${item.parentId}-${item.id}`,
          source: `${parentKind}:${item.parentId}`,
          target: nodeId,
          type: "floating",
          style: edgeStyle["part-of"],
          data: { relationship: "part-of" },
        });
      }
    }
  }

  for (const design of kit.designs ?? []) {
    for (const piece of design.pieces ?? []) {
      if (piece.type?.id) {
        const typeId = piece.type.id;
        const sourceId = `type:${typeId}`;
        const targetId = `design:${design.id}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
      if (piece.design?.id) {
        const nestedDesignId = piece.design.id;
        const sourceId = `design:${nestedDesignId}`;
        const targetId = `design:${design.id}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
    }
  }

  const portToTypes = new Map<string, Set<string>>();
  const typeById = new Map((kit.types ?? []).map((typeRecord) => [typeRecord.id, typeRecord]));
  const resolveTypeLineage = (typeId: string): string[] => {
    const lineage: string[] = [];
    const visited = new Set<string>();
    let currentId: string | undefined = typeId;
    while (currentId && !visited.has(currentId)) {
      visited.add(currentId);
      lineage.push(currentId);
      const currentType = typeById.get(currentId);
      currentId = currentType?.parent?.id;
    }
    return lineage;
  };
  for (const type of kit.types ?? []) {
    for (const connector of type.connectors ?? []) {
      const portId = connector.port?.id;
      if (portId) {
        const sourceId = `port:${portId}`;
        for (const relatedTypeId of resolveTypeLineage(type.id)) {
          const targetId = `type:${relatedTypeId}`;
          const edgeId = `ref-${sourceId}-${targetId}`;
          if (!edges.some((e) => e.id === edgeId)) {
            edges.push({
              id: edgeId,
              source: sourceId,
              target: targetId,
              type: "floating",
              style: edgeStyle["reference"],
              data: { relationship: "reference" },
            });
          }
          if (!portToTypes.has(portId)) portToTypes.set(portId, new Set());
          portToTypes.get(portId)!.add(relatedTypeId);
        }
      }
    }
  }

  const portGroups = createPortGroupMap(kit.ports ?? []);
  const groupToTypes = new Map<string, Set<string>>();
  for (const [portId, typeIds] of portToTypes) {
    const groupRoot = portGroups.get(portId) ?? portId;
    if (!groupToTypes.has(groupRoot)) groupToTypes.set(groupRoot, new Set());
    for (const typeId of typeIds) groupToTypes.get(groupRoot)!.add(typeId);
  }
  for (const typeIds of groupToTypes.values()) {
    const arr = Array.from(typeIds);
    for (let i = 0; i < arr.length; i++) {
      for (let j = i + 1; j < arr.length; j++) {
        const sourceId = `type:${arr[i]}`;
        const targetId = `type:${arr[j]}`;
        const edgeId = `compat-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
    }
  }

  return { nodes, edges };
};

const hasAnySelection = (selection: KitAppSelection): boolean =>
  (selection.types?.length ?? 0) > 0 ||
  (selection.designs?.length ?? 0) > 0 ||
  (selection.qualities?.length ?? 0) > 0 ||
  (selection.ports?.length ?? 0) > 0 ||
  (selection.tags?.length ?? 0) > 0 ||
  (selection.files?.length ?? 0) > 0 ||
  (selection.folders?.length ?? 0) > 0 ||
  (selection.authors?.length ?? 0) > 0;

const buildSelectionKit = (kit: Kit, selection: KitAppSelection): Kit => {
  const selectedTypeIds = new Set(selection.types ?? []);
  const selectedDesignIds = new Set(selection.designs ?? []);
  const selectedPortIds = new Set(selection.ports ?? []);
  const selectedTagIds = new Set(selection.tags ?? []);
  const selectedFileIds = new Set(selection.files ?? []);
  const selectedFolderIds = new Set(selection.folders ?? []);
  const selectedAuthorIds = new Set(selection.authors ?? []);
  const selectedQualityIds = new Set(selection.qualities ?? []);
  const typeById = new Map((kit.types ?? []).map((t) => [t.id, t]));
  const collectAncestorTypes = (id: string, collected: Set<string>) => {
    if (collected.has(id)) return;
    collected.add(id);
    const t = typeById.get(id);
    if (t?.parent?.id) collectAncestorTypes(t.parent.id, collected);
  };
  const allTypeIds = new Set(selectedTypeIds);
  for (const id of selectedTypeIds) collectAncestorTypes(id, allTypeIds);
  const designById = new Map((kit.designs ?? []).map((d) => [d.id, d]));
  const collectAncestorDesigns = (id: string, collected: Set<string>) => {
    if (collected.has(id)) return;
    collected.add(id);
    const d = designById.get(id);
    if (d?.parent?.id) collectAncestorDesigns(d.parent.id, collected);
  };
  const allDesignIds = new Set(selectedDesignIds);
  for (const id of selectedDesignIds) collectAncestorDesigns(id, allDesignIds);
  for (const designId of allDesignIds) {
    const d = designById.get(designId);
    for (const piece of d?.pieces ?? []) {
      if (piece.type?.id && typeById.has(piece.type.id)) collectAncestorTypes(piece.type.id, allTypeIds);
    }
  }
  for (const typeId of allTypeIds) {
    const t = typeById.get(typeId);
    for (const connector of t?.connectors ?? []) {
      if (connector.port?.id) selectedPortIds.add(connector.port.id);
    }
  }
  const types = (kit.types ?? []).filter((t) => allTypeIds.has(t.id));
  const designs = (kit.designs ?? []).filter((d) => allDesignIds.has(d.id));
  const ports = (kit.ports ?? []).filter((p) => selectedPortIds.has(p.id));
  const tags = (kit.tags ?? []).filter((t) => selectedTagIds.has(t.id));
  const files = (kit.files ?? []).filter((f) => selectedFileIds.has(f.id));
  const folders = (kit.folders ?? []).filter((f) => selectedFolderIds.has(f.id));
  const authors = (kit.authors ?? []).filter((a) => selectedAuthorIds.has(a.id));
  const qualities = (kit.qualities ?? []).filter((q) => selectedQualityIds.has(q.id));
  return {
    ...kit,
    types,
    designs,
    ports,
    tags,
    files,
    folders,
    authors,
    qualities,
  };
};

interface KitDiagramProps {}

interface ForceNode extends SimulationNodeDatum {
  id: string;
  data: KitDiagramNode;
}

/**
 * ForceLink holds the data fields for a ForceLink record.
 **/
interface ForceLink extends SimulationLinkDatum<ForceNode> {
  id: string;
  relationship: "part-of" | "reference";
}
/**
 * KitDiagramInner holds the data fields for a KitDiagramInner record.
 **/
const KitDiagramInner: FC = () => {
  const kit = useKit() as Kit | undefined;
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const kitCommands = useKitAppCommands();
  const [selection] = useKitAppSelection();
  const [setHover] = useKitAppSetHover();
  const [clearHover] = useKitAppClearHover();
  const kitScope = useKitScope();
  const kitId = kitScope?.id ?? "";
  const [activeTool] = useKitAppActiveTool();
  const isHandTool = activeTool === ToolKind.HAND;
  const actor = useSketchpadActor();
  const [diagramForce] = useKitAppDiagramForce();
  const [diagramNodes, setDiagramNodes] = useState<Node<KitDiagramNode>[]>([]);
  const [diagramEdges, setDiagramEdges] = useState<Edge[]>([]);
  const diagramNodesRef = useRef<Node<KitDiagramNode>[]>([]);
  const diagramEdgesRef = useRef<Edge[]>([]);
  const simulationRef = useRef<Simulation<ForceNode, ForceLink> | null>(null);
  const draggingNodeIdRef = useRef<string | null>(null);
  const pinnedNodeIdsRef = useRef<Set<string>>(new Set());
  const isDragReheatActiveRef = useRef(false);
  const debugTickRef = useRef(0);
  const diagramForceConfig = useMemo(() => ({ ...defaultDiagramForceSettings, ...diagramForce }), [diagramForce]);

  const filterSearchSelector = useMemo(() => createKitFilterSearchSelector(kitId), [kitId]);
  const expandedRowsSelector = useMemo(() => createKitExpandedRowsSelector(kitId), [kitId]);
  const filterSearch = useSelector(actor, filterSearchSelector) ?? "";
  const expandedRowsSet = useSelector(actor, expandedRowsSelector);
  const expandedRowsArray = useMemo(() => (expandedRowsSet ? Array.from(expandedRowsSet) : []), [expandedRowsSet]);
  const expandedRowsKey = expandedRowsArray.join(",");
  const expandedRows = useMemo(() => new Set(expandedRowsArray), [expandedRowsKey]);

  const [searchParams] = useSearchParams();
  const selectedKinds = useMemo(() => new Set(searchParams.getAll("kind") as ArtifactKind[]), [searchParams]);

  const fileUrls = useFileUrls();
  const importedFilePaths = useMemo(() => {
    const paths = new Set<string>();
    fileUrls.forEach((_url, path) => {
      const normalizedPath = path.replace(/^\.?\//, "").replace(/\/+$/, "");
      if (normalizedPath) paths.add(normalizedPath);
    });
    return paths;
  }, [fileUrls]);
  const importedFolderPaths = useMemo(() => {
    const paths = new Set<string>();
    importedFilePaths.forEach((filePath) => {
      const segments = filePath.split("/").filter(Boolean);
      for (let i = 1; i < segments.length; i++) {
        paths.add(segments.slice(0, i).join("/"));
      }
    });
    return paths;
  }, [importedFilePaths]);

  const visibleIds = useMemo(() => {
    if (!kit) return new Set<string>();
    const ids = new Set<string>();
    const searchLower = filterSearch.toLowerCase();

    const designById = new Map((kit.designs ?? []).map((d) => [d.id, d]));
    const typeById = new Map((kit.types ?? []).map((t) => [t.id, t]));
    const folderById = new Map((kit.folders ?? []).map((f) => [f.id, f]));

    const isAncestorChainExpanded = (rowId: string, parentRowId: string | undefined): boolean => {
      if (!parentRowId) return true;
      if (!expandedRows.has(parentRowId)) return false;

      const [kind, id] = parentRowId.split("-", 2);
      if (kind === "design") {
        const parentDesign = designById.get(id);
        if (parentDesign?.parent?.id) {
          return isAncestorChainExpanded(parentRowId, `design-${parentDesign.parent.id}`);
        }

        if (parentDesign?.folder) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentDesign.folder}`);
        }
      } else if (kind === "type") {
        const parentType = typeById.get(id);
        if (parentType?.parent?.id) {
          return isAncestorChainExpanded(parentRowId, `type-${parentType.parent.id}`);
        }

        if (parentType?.folder) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentType.folder}`);
        }
      } else if (kind === "folder") {
        const parentFolder = folderById.get(id);
        if (parentFolder?.parent?.id) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentFolder.parent.id}`);
        }
      }
      return true;
    };

    const isRowVisible = (rowId: string, parentRowId: string | undefined, name: string, kind: ArtifactKind): boolean => {
      if (searchLower && !name.toLowerCase().includes(searchLower)) return false;
      if (selectedKinds.size > 0 && !selectedKinds.has(kind)) return false;
      return isAncestorChainExpanded(rowId, parentRowId);
    };

    (kit.designs ?? []).filter(Boolean).forEach((d) => {
      const rowId = `design-${d.id}`;
      let parentRowId: string | undefined;
      if (d.parent?.id) {
        parentRowId = `design-${d.parent.id}`;
      } else if (d.folder) {
        parentRowId = `folder-${d.folder}`;
      }
      if (isRowVisible(rowId, parentRowId, d.name, "designs")) {
        ids.add(d.id);
      }
    });

    (kit.types ?? []).filter(Boolean).forEach((t) => {
      const rowId = `type-${t.id}`;
      let parentRowId: string | undefined;
      if (t.parent?.id) {
        parentRowId = `type-${t.parent.id}`;
      } else if (t.folder) {
        parentRowId = `folder-${t.folder}`;
      }
      if (isRowVisible(rowId, parentRowId, t.name, "types")) {
        ids.add(t.id);
      }
    });

    (kit.qualities ?? []).filter(Boolean).forEach((q) => {
      const rowId = `quality-${q.id}`;
      const parentRowId = q.folder ? `folder-${q.folder}` : undefined;
      if (isRowVisible(rowId, parentRowId, q.name, "qualities")) {
        ids.add(q.id);
      }
    });

    (kit.ports ?? []).filter(Boolean).forEach((i) => {
      if ((!searchLower || i.name.toLowerCase().includes(searchLower)) && (selectedKinds.size === 0 || selectedKinds.has("ports"))) {
        ids.add(i.id);
      }
    });

    const diagramFoldersById = new Map((kit.folders ?? []).map((f) => [f.id, f]));
    const getDiagramFolderStoragePath = (folderId?: string): string => {
      if (!folderId) return "";
      const folder = diagramFoldersById.get(folderId);
      if (!folder) return "";
      const parentPath = getDiagramFolderStoragePath(folder.parent?.id);
      return parentPath ? `${parentPath}/${folder.name}` : folder.name;
    };

    const filteredDiagramFolders = new Set(
      (kit.folders ?? [])
        .filter(Boolean)
        .filter((folder) => importedFolderPaths.has(getDiagramFolderStoragePath(folder.id)))
        .map((f) => f.id),
    );
    const filteredDiagramFiles = new Set(
      (kit.files ?? [])
        .filter(Boolean)
        .filter((file) => {
          if (!file.name?.includes(".")) return false;
          if (diagramFoldersById.has(file.id)) return false;
          const parentPath = getDiagramFolderStoragePath(file.folder?.id);
          const storagePath = parentPath ? `${parentPath}/${file.name}` : file.name;
          if (importedFolderPaths.has(storagePath)) return false;
          return importedFilePaths.has(storagePath);
        })
        .map((f) => f.id),
    );

    (kit.files ?? []).filter(Boolean).forEach((f) => {
      if (!filteredDiagramFiles.has(f.id)) return;
      const rowId = `file-${f.id}`;
      const parentRowId = f.folder?.id ? `folder-${f.folder.id}` : undefined;
      if (isRowVisible(rowId, parentRowId, f.name, "files")) {
        ids.add(f.id);
      }
    });

    (kit.folders ?? []).filter(Boolean).forEach((f) => {
      if (!filteredDiagramFolders.has(f.id)) return;
      const rowId = `folder-${f.id}`;
      const parentRowId = f.parent?.id ? `folder-${f.parent.id}` : undefined;
      if (isRowVisible(rowId, parentRowId, f.name, "folders")) {
        ids.add(f.id);
      }
    });

    (kit.authors ?? []).filter(Boolean).forEach((a) => {
      if ((!searchLower || a.name.toLowerCase().includes(searchLower)) && (selectedKinds.size === 0 || selectedKinds.has("authors"))) {
        ids.add(a.id);
      }
    });

    return ids;
  }, [kit, filterSearch, expandedRows, selectedKinds, importedFilePaths, importedFolderPaths]);

  const { nodes: baseNodes, edges: baseEdges } = useMemo(() => {
    if (!kit) return { nodes: [], edges: [] };
    const { nodes: rfNodes, edges: rfEdges } = buildKitDiagramData(kit);

    const filteredNodes = rfNodes
      .filter((n) => visibleIds.has(n.data.id))
      .map((node) => {
        const [kind, id] = node.id.split(":");
        let isSelected = false;
        if (kind === "type") isSelected = selection?.types?.includes(id) ?? false;
        else if (kind === "design") isSelected = selection?.designs?.includes(id) ?? false;
        else if (kind === "quality") isSelected = selection?.qualities?.includes(id) ?? false;
        else if (kind === "port") isSelected = selection?.ports?.includes(id) ?? false;
        else if (kind === "file") isSelected = selection?.files?.includes(id) ?? false;
        else if (kind === "folder") isSelected = selection?.folders?.includes(id) ?? false;
        else if (kind === "author") isSelected = selection?.authors?.includes(id) ?? false;

        return {
          ...node,
          selected: isSelected,
          style: { ...node.style, width: node.width ?? getKitDiagramNodeFrameForKind(node.data.kind).width, height: node.height ?? getKitDiagramNodeFrameForKind(node.data.kind).height },
        };
      });

    const filteredNodeIds = new Set(filteredNodes.map((n) => n.id));
    const filteredEdges = rfEdges.filter((e) => filteredNodeIds.has(e.source) && filteredNodeIds.has(e.target));

    return { nodes: filteredNodes, edges: filteredEdges };
  }, [kit, visibleIds, selection]);
  const baseNodeIdsKey = useMemo(() => baseNodes.map((node) => node.id).join("|"), [baseNodes]);
  const baseEdgeIdsKey = useMemo(() => baseEdges.map((edge) => edge.id).join("|"), [baseEdges]);

  const commitDiagramNodes = useCallback((nextNodes: Node<KitDiagramNode>[]) => {
    diagramNodesRef.current = nextNodes;
    setDiagramNodes(nextNodes);
  }, []);

  const syncSimulationPositions = useCallback((positions: Map<string, Node["position"]>) => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      const pos = positions.get(simNode.id);
      if (pos) {
        simNode.x = pos.x;
        simNode.y = pos.y;
      }
    }
  }, []);

  const setPinnedPositions = useCallback((positions: Map<string, Node["position"]>) => {
    pinnedNodeIdsRef.current = new Set(positions.keys());
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      const pos = positions.get(simNode.id);
      if (pos) {
        simNode.fx = pos.x;
        simNode.fy = pos.y;
      }
    }
  }, []);

  const clearPinnedPositions = useCallback(() => {
    pinnedNodeIdsRef.current = new Set();
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      simNode.fx = null;
      simNode.fy = null;
    }
  }, []);

  const logSimulationState = useCallback((label: string, node?: Node) => {
    if (!KIT_DIAGRAM_DEBUG) return;
    const simulation = simulationRef.current;
    if (!simulation) return;
  }, []);

  const startDragReheat = useCallback(() => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    if (!isDragReheatActiveRef.current) {
      isDragReheatActiveRef.current = true;
    }
    simulation.alphaTarget(0.3).restart();
  }, []);

  const stopDragReheat = useCallback(() => {
    const simulation = simulationRef.current;
    if (simulation) {
      simulation.alphaTarget(0);
    }
    isDragReheatActiveRef.current = false;
    clearPinnedPositions();
    draggingNodeIdRef.current = null;
    logSimulationState("drag-end");
  }, [clearPinnedPositions, logSimulationState]);

  const updateNodesFromSimulation = useCallback(() => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    const pinnedNodeIds = pinnedNodeIdsRef.current;
    const simNodeById = new Map(simulation.nodes().map((node) => [node.id, node]));
    const nextNodes = diagramNodesRef.current.map((node) => {
      if (pinnedNodeIds.has(node.id)) {
        return node;
      }
      const simNode = simNodeById.get(node.id);
      if (!simNode) return node;
      return { ...node, position: { x: simNode.x ?? 0, y: simNode.y ?? 0 } };
    });
    commitDiagramNodes(nextNodes);
  }, [commitDiagramNodes, baseEdgeIdsKey, baseNodeIdsKey]);

  useEffect(() => {
    const previousPositions = new Map(diagramNodesRef.current.map((node) => [node.id, node.position]));
    const nextNodes = baseNodes.map((node) => {
      const previousPosition = previousPositions.get(node.id);
      return previousPosition ? { ...node, position: previousPosition } : node;
    });
    commitDiagramNodes(nextNodes);
    diagramEdgesRef.current = baseEdges;
    setDiagramEdges(baseEdges);
  }, [baseNodes, baseEdges, commitDiagramNodes]);

  useEffect(() => {
    if (diagramNodesRef.current.length === 0) {
      if (simulationRef.current) {
        simulationRef.current.alphaTarget(0);
        simulationRef.current.stop();
        simulationRef.current = null;
      }
      return;
    }
    const nodesSnapshot = diagramNodesRef.current;
    const edgesSnapshot = diagramEdgesRef.current;
    const nodesCopy: ForceNode[] = nodesSnapshot.map((node) => ({
      id: node.id,
      x: node.position.x,
      y: node.position.y,
      data: node.data,
    }));
    const linksCopy: ForceLink[] = edgesSnapshot.map((edge) => ({
      id: edge.id,
      source: edge.source,
      target: edge.target,
      relationship: (edge.data?.relationship as "part-of" | "reference") ?? "reference",
    }));
    const simulation = forceSimulation<ForceNode, ForceLink>(nodesCopy)
      .force("charge", forceManyBody().strength(diagramForceConfig.chargeStrength))
      .force(
        "link",
        forceLink<ForceNode, ForceLink>(linksCopy)
          .id((d) => d.id)
          .distance(diagramForceConfig.linkDistance),
      )
      .force("collide", forceCollide().radius(diagramForceConfig.collideRadius))
      .force("x", forceX(0).strength(diagramForceConfig.centerStrength))
      .force("y", forceY(0).strength(diagramForceConfig.centerStrength));
    simulationRef.current = simulation;
    const snapshotPositions = new Map(nodesSnapshot.map((node) => [node.id, node.position]));
    syncSimulationPositions(snapshotPositions);
    const numTicks = Math.ceil(Math.log(simulation.alphaMin()) / Math.log(1 - simulation.alphaDecay()));
    for (let i = 0; i < numTicks; i += 1) {
      simulation.tick();
    }
    updateNodesFromSimulation();
    simulation.on("tick", updateNodesFromSimulation);

    simulation.alpha(1).restart();
    return () => {
      stopDragReheat();
      simulation.alphaTarget(0);
      simulation.stop();
      simulationRef.current = null;
    };
  }, [baseEdgeIdsKey, baseNodeIdsKey, diagramForceConfig.centerStrength, diagramForceConfig.chargeStrength, diagramForceConfig.collideRadius, diagramForceConfig.linkDistance, stopDragReheat, syncSimulationPositions, updateNodesFromSimulation]);

  const handleNodesChange = useCallback(
    (changes: any[]) => {
      const updatedNodes = applyNodeChanges(changes, diagramNodesRef.current);
      const draggingNodeId = draggingNodeIdRef.current;
      if (draggingNodeId && simulationRef.current) {
        const selectedNodes = updatedNodes.filter((node) => node.selected);
        const selectedPositions = new Map(selectedNodes.map((node) => [node.id, node.position]));
        if (selectedPositions.size > 1 && selectedPositions.has(draggingNodeId)) {
          setPinnedPositions(selectedPositions);
        } else {
          const draggedNode = updatedNodes.find((node) => node.id === draggingNodeId);
          if (draggedNode) {
            setPinnedPositions(new Map([[draggedNode.id, draggedNode.position]]));
          }
        }
      }
      commitDiagramNodes(updatedNodes);
    },
    [commitDiagramNodes, setPinnedPositions],
  );

  const handleNodeDragStart = useCallback(
    (_: any, node: Node) => {
      draggingNodeIdRef.current = node.id;
      const currentPositions = new Map(diagramNodesRef.current.map((item) => [item.id, item.position]));
      currentPositions.set(node.id, node.position);
      syncSimulationPositions(currentPositions);
      const selectedNodes = diagramNodesRef.current.filter((item) => item.selected);
      const selectedPositions = new Map(selectedNodes.map((item) => [item.id, item.position]));
      if (node.selected) {
        selectedPositions.set(node.id, node.position);
      }
      if (selectedPositions.size > 1 && node.selected) {
        setPinnedPositions(selectedPositions);
      } else {
        setPinnedPositions(new Map([[node.id, node.position]]));
      }
      startDragReheat();
      logSimulationState("drag-start", node);
    },
    [logSimulationState, setPinnedPositions, startDragReheat, syncSimulationPositions],
  );

  const handleNodeDrag = useCallback(
    (_: any, node: Node) => {
      if (draggingNodeIdRef.current !== node.id) return;
      const selectedNodes = diagramNodesRef.current.filter((item) => item.selected);
      const selectedPositions = new Map(selectedNodes.map((item) => [item.id, item.position]));
      if (node.selected) {
        selectedPositions.set(node.id, node.position);
      }
      if (selectedPositions.size > 1 && node.selected) {
        setPinnedPositions(selectedPositions);
      } else {
        setPinnedPositions(new Map([[node.id, node.position]]));
      }
      startDragReheat();
      logSimulationState("drag", node);
    },
    [logSimulationState, setPinnedPositions, startDragReheat],
  );

  const handleNodeDragStop = useCallback(
    (_: any, _node: Node) => {
      stopDragReheat();
    },
    [stopDragReheat],
  );

  const handleDragEndFallback = useCallback(() => {
    if (!draggingNodeIdRef.current && !isDragReheatActiveRef.current) return;
    stopDragReheat();
  }, [stopDragReheat]);

  useEffect(() => {
    const wrapper = reactFlowWrapper.current;
    window.addEventListener("pointerup", handleDragEndFallback);
    window.addEventListener("pointercancel", handleDragEndFallback);
    window.addEventListener("blur", handleDragEndFallback);
    if (wrapper) {
      wrapper.addEventListener("pointerleave", handleDragEndFallback);
    }
    return () => {
      window.removeEventListener("pointerup", handleDragEndFallback);
      window.removeEventListener("pointercancel", handleDragEndFallback);
      window.removeEventListener("blur", handleDragEndFallback);
      if (wrapper) {
        wrapper.removeEventListener("pointerleave", handleDragEndFallback);
      }
    };
  }, [handleDragEndFallback]);

  const onSelectionChange = useCallback(
    ({ nodes: selectedNodes }: any) => {
      const newSelection: KitAppSelection = {};
      selectedNodes.forEach((node: any) => {
        const [kind, id] = node.id.split(":");
        if (kind === "type") {
          if (!newSelection.types) newSelection.types = [];
          newSelection.types.push(id);
        } else if (kind === "design") {
          if (!newSelection.designs) newSelection.designs = [];
          newSelection.designs.push(id);
        } else if (kind === "quality") {
          if (!newSelection.qualities) newSelection.qualities = [];
          newSelection.qualities.push(id);
        } else if (kind === "port") {
          if (!newSelection.ports) newSelection.ports = [];
          newSelection.ports.push(id);
        } else if (kind === "file") {
          if (!newSelection.files) newSelection.files = [];
          newSelection.files.push(id);
        } else if (kind === "folder") {
          if (!newSelection.folders) newSelection.folders = [];
          newSelection.folders.push(id);
        } else if (kind === "author") {
          if (!newSelection.authors) newSelection.authors = [];
          newSelection.authors.push(id);
        }
      });

      actor.send({ type: "KIT.SET_SELECTION", kitId, selection: newSelection });
    },
    [actor, kitId],
  );

  const handlePaneClick = useCallback(() => {
    kitCommands.deselectAll?.();
  }, [kitCommands]);

  const handleNodeMouseEnter = useCallback(
    (_: any, node: any) => {
      const data = node.data as KitDiagramNode;
      const kind = data?.kind;
      const id = data?.id;
      if (!kind || !id) return;
      if (!setHover) return;
      if (kind === "type") setHover({ type: id });
      else if (kind === "design") setHover({ design: id });
      else if (kind === "quality") setHover({ quality: id });
      else if (kind === "port") setHover({ port: id });
      else if (kind === "file") setHover({ file: id });
      else if (kind === "folder") setHover({ folder: id });
      else if (kind === "author") setHover({ author: id });
    },
    [setHover],
  );

  const handleNodeMouseLeave = useCallback(() => {
    if (clearHover) clearHover();
  }, [clearHover]);

  const sketchpadCommands = useSketchpadCommands();

  const handleNodeDoubleClick = useCallback(
    (_: React.MouseEvent, node: any) => {
      const data = node.data as KitDiagramNode;
      const kind = data?.kind;
      const id = data?.id;
      if (!kind || !id || !kitId) return;
      if (kind === "design") sketchpadCommands.navigateToDesign(kitId, id);
      else if (kind === "type") sketchpadCommands.navigateToType(kitId, id);
      else if (kind === "quality") sketchpadCommands.navigateToQuality(kitId, id);
    },
    [kitId, sketchpadCommands],
  );

  useEffect(() => {
    const handleCopyKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "c" || !(e.metaKey || e.ctrlKey)) return;
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) return;
      if (!reactFlowWrapper.current?.contains(target)) return;
      e.preventDefault();
      if (!kit) return;
      const payload = selection && hasAnySelection(selection) ? buildSelectionKit(kit, selection) : kit;
      sketchpadCommands.copyJsonToClipboard("semio.sketchpad.app.kit.diagram.copy", payload);
    };
    window.addEventListener("keydown", handleCopyKeyDown);
    return () => window.removeEventListener("keydown", handleCopyKeyDown);
  }, [kit, selection, sketchpadCommands]);

  if (!kit) return null;

  return (
    <div ref={reactFlowWrapper} className="w-full h-full" data-testid="kit-diagram" tabIndex={0} onPointerDown={() => reactFlowWrapper.current?.focus()}>
      <Diagram
        nodes={diagramNodes}
        edges={diagramEdges}
        nodeTypes={kitNodeTypes}
        edgeTypes={{ floating: FloatingEdge }}
        connectionLineComponent={FloatingConnectionLine}
        forceConfig={{ enabled: false }}
        elementsSelectable={true}
        nodesFocusable={true}
        edgesFocusable={true}
        onSelectionChange={onSelectionChange}
        onNodesChangeReactFlow={handleNodesChange}
        onNodeMouseEnter={handleNodeMouseEnter}
        onNodeMouseLeave={handleNodeMouseLeave}
        onNodeDoubleClick={handleNodeDoubleClick}
        onNodeDragStart={handleNodeDragStart}
        onNodeDrag={handleNodeDrag}
        onNodeDragStop={handleNodeDragStop}
        onPaneClick={handlePaneClick}
        selectionMode={SelectionMode.Partial}
        panOnScroll={false}
        panOnDrag={isHandTool ? true : [1, 2]}
        selectionOnDrag={!isHandTool}
        nodesDraggable={!isHandTool}
        proOptions={{ hideAttribution: true }}
      />
    </div>
  );
};
/**
 * KitDiagram holds the data fields for a KitDiagram record.
 **/
const KitDiagram: FC<KitDiagramProps> = () => {
  return (
    <ReactFlowProvider>
      <KitDiagramInner />
    </ReactFlowProvider>
  );
};

/**
 * TableWindow holds the data fields for a TableWindow record.
 **/
const TableWindow = memo(() => {
  return <AppContent />;
});
TableWindow.displayName = "TableWindow";

/**
 * DiagramWindow holds the data fields for a DiagramWindow record.
 **/
const KitDiagramWindow = memo(() => {
  return <KitDiagram />;
});
KitDiagramWindow.displayName = "KitDiagramWindow";
/**
 * MultiWindowApp holds the data fields for a MultiWindowApp record.
 **/
const MultiWindowApp: FC = () => {
  useKitAppYjsToXStateSync();
  const transaction = useKitAppTransaction();
  const actor = useSketchpadActor();
  const sketchpadStore = useSketchpadStore();
  const kitId = useKitScope()?.id;
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const [activeWindow, setActiveWindow] = useState<string>(KitAppWindowKind.Table);
  const [activeTool, setActiveTool] = useKitAppActiveTool();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!setActiveTool || !isSelectionToolKind(activeTool)) return;
      const nextToolKind = toSelectionToolKind(
        resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
          shiftKey: e.shiftKey,
          altKey: e.altKey,
          ctrlKey: e.ctrlKey,
          metaKey: e.metaKey,
        }),
      );
      if (nextToolKind !== ToolKind.SELECTION_NORMAL && nextToolKind !== activeTool) setActiveTool(nextToolKind);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (!setActiveTool || !isSelectionToolKind(activeTool)) return;
      const nextToolKind = toSelectionToolKind(
        resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
          shiftKey: e.shiftKey,
          altKey: e.altKey,
          ctrlKey: e.ctrlKey,
          metaKey: e.metaKey,
        }),
      );
      if (nextToolKind === ToolKind.SELECTION_NORMAL && activeTool !== ToolKind.SELECTION_NORMAL) setActiveTool(ToolKind.SELECTION_NORMAL);
      if (nextToolKind !== ToolKind.SELECTION_NORMAL && nextToolKind !== activeTool) setActiveTool(nextToolKind);
    };
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, [activeTool, setActiveTool]);

  useEffect(() => {
    if (appType !== "kit") return;
    if (!kitId) return;

    addSection("toolbar", {
      id: "semio.sketchpad.app.kit.toolbar.history",
      specificity: 20,
      order: 5,
      toolbarGroup: {
        id: "history",
        labelId: "semio.sketchpad.toolbar.parent.actions",
        order: 5,
      },
      content: () => (
        <KitScopeProvider id={kitId}>
          <KitToolbarHistory />
        </KitScopeProvider>
      ),
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.kit.toolbar.reset",
      specificity: 20,
      order: 6,
      toolbarGroup: {
        id: "history",
        labelId: "semio.sketchpad.toolbar.parent.actions",
        order: 5,
      },
      content: () => (
        <KitScopeProvider id={kitId}>
          <KitToolbarReset />
        </KitScopeProvider>
      ),
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.kit.toolbar.selection",
      specificity: 20,
      order: 10,
      toolbarGroup: {
        id: "selection",
        labelId: "semio.sketchpad.toolbar.parent.selection",
        order: 10,
      },
      content: () => (
        <KitScopeProvider id={kitId}>
          <KitToolbarSelection />
        </KitScopeProvider>
      ),
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.kit.toolbar.filters",
      specificity: 20,
      order: 20,
      toolbarGroup: {
        id: "filter",
        labelId: "semio.sketchpad.toolbar.parent.filter",
        order: 20,
      },
      content: () => (
        <KitScopeProvider id={kitId}>
          <KitFilters />
        </KitScopeProvider>
      ),
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.kit.toolbar.create",
      specificity: 20,
      order: 30,
      toolbarGroup: {
        id: "create",
        labelId: "semio.sketchpad.toolbar.parent.create",
        order: 30,
      },
      content: () => {
        return (
          <KitScopeProvider id={kitId}>
            <KitCreateActions />
          </KitScopeProvider>
        );
      },
    });

    return () => {
      removeSection("toolbar", "semio.sketchpad.app.kit.toolbar.history");
      removeSection("toolbar", "semio.sketchpad.app.kit.toolbar.reset");
      removeSection("toolbar", "semio.sketchpad.app.kit.toolbar.selection");
      removeSection("toolbar", "semio.sketchpad.app.kit.toolbar.filters");
      removeSection("toolbar", "semio.sketchpad.app.kit.toolbar.create");
      removeSection("toolbar", "semio.sketchpad.app.kit.kitApp.toolsGroup");
    };
  }, [appType, addSection, removeSection, kitId]);

  const hasKit = useHasKit(kitId || "");

  const store = useMemo(() => {
    if (!kitId || !sketchpadStore?.hasKitApp?.({ kit: kitId })) return null;
    return sketchpadStore.kitApp(kitId);
  }, [sketchpadStore, kitId]);
  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();

  const storedWindowLayout = useSyncDeep<any, any>(store, (s: KitAppState | null) => s?.windowLayout);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "50%",
            content: [
              {
                type: "component",
                componentName: KitAppWindowKind.Table,
                title: "table",
                componentState: {},
              },
            ],
          },
          {
            type: "stack",
            size: "50%",
            content: [
              {
                type: "component",
                componentName: KitAppWindowKind.Diagram,
                title: "diagram",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );
  const windowLayout = useMemo(() => {
    if (!storedWindowLayout) return defaultLayout;
    const removeLegacySideTabsFromWindowLayout = (layoutNode: any): any => {
      if (!layoutNode || typeof layoutNode !== "object") return layoutNode;
      if (layoutNode.type === "component" && (layoutNode.componentName === "settings" || layoutNode.componentName === "chat")) {
        return null;
      }
      if (layoutNode.root && typeof layoutNode.root === "object") {
        const root = removeLegacySideTabsFromWindowLayout(layoutNode.root);
        if (!root) return undefined;
        return { ...layoutNode, root };
      }
      if (Array.isArray(layoutNode.content)) {
        const content = layoutNode.content.map((item: any) => removeLegacySideTabsFromWindowLayout(item)).filter(Boolean);
        if (content.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, content };
      }
      if (Array.isArray(layoutNode.contentItems)) {
        const contentItems = layoutNode.contentItems.map((item: any) => removeLegacySideTabsFromWindowLayout(item)).filter(Boolean);
        if (contentItems.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, contentItems };
      }
      return layoutNode;
    };
    return removeLegacySideTabsFromWindowLayout(storedWindowLayout) || defaultLayout;
  }, [storedWindowLayout, defaultLayout]);

  useEffect(() => {
    if (appType !== "kit") return;
    return () => {};
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: KitAppWindowKind.Table,
          label: "table",
          component: () => <TableWindow />,
        },
        {
          id: KitAppWindowKind.Diagram,
          label: "diagram",
          component: () => <KitDiagramWindow />,
        },
      ],
      defaultLayout,
    }),
    [defaultLayout],
  );

  useEffect(() => {
    const isValid = windowConfig.windowKinds.some((k) => k.id === activeWindow);
    if (!isValid) {
      setActiveWindow(KitAppWindowKind.Table);
    }
  }, [activeWindow, windowConfig.windowKinds]);

  const handleLayoutChange = useCallback(
    (config: any) => {
      if (store && typeof store.change === "function") {
        store.change({ windowLayout: config });
      }
    },
    [store],
  );

  if (!hasKit) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-sm text-muted-foreground">Loading kit...</p>
      </div>
    );
  }

  return (
    <ErrorBoundary
      fallback={
        <div className="flex items-center justify-center h-full">
          <p className="text-sm text-muted-foreground">Failed to load kit app</p>
        </div>
      }
    >
      <TransactionProvider transaction={transaction}>
        <KitDropZone>
          <Canvas id="semio.sketchpad.app.kit.canvas">
            <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
          </Canvas>
        </KitDropZone>
      </TransactionProvider>
    </ErrorBoundary>
  );
};

// #endregion 🧫Diagram

// #region 🩻Tools
// Tools MUST define Kit app toolbar filter and selection tool components.

/**
 * Returns a hook for the Kit app filter search input state.
 *MUST provide the current filter string and a setter.
 **/
export function useKitAppFilterSearch(): HookResult<string> {
  const store = useKitAppStore();
  const filterSearch = useSyncDeep(store, (s: KitAppState | null) => s?.filterSearch ?? "") || "";
  const setFilterSearch = useCallback(
    (value: string) => {
      store?.change({ filterSearch: value });
    },
    [store],
  );
  return [filterSearch, setFilterSearch, !!store];
}

/**
 * Filter toolbar component rendering the search input for Kit artifacts.
 *MUST render a filter input connected to the Kit app filter search state.
 **/
export const KitFilters: FC = () => {
  return <KitKindToggles />;
};

/**
 * Toolbar selection tool component for the Kit app.
 *MUST render selection mode toggle buttons.
 **/
export const KitToolbarSelection: FC = () => {
  const [activeTool, setActiveTool] = useKitAppActiveTool();
  const additiveLabel = useLabel("semio.sketchpad.app.kit.tools.select.mode.additive");
  const subtractiveLabel = useLabel("semio.sketchpad.app.kit.tools.select.mode.subtractive");
  const intersectLabel = useLabel("semio.sketchpad.app.kit.tools.select.mode.intersect");
  const rectangularLabel = useLabel("semio.sketchpad.app.kit.tools.select.shape.rectangular");
  const lassoLabel = useLabel("semio.sketchpad.app.kit.tools.select.shape.lasso");
  const handLabel = useLabel("semio.sketchpad.app.kit.tools.select.navigation.hand");

  return (
    <ToolbarGroup>
      <ToolbarGroup>
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.mode.additive"
          icon={<AddIcon className="size-tiny" />}
          text={additiveLabel}
          pressed={activeTool === ToolKind.SELECTION_ADDITIVE}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.SELECTION_ADDITIVE : ToolKind.SELECTION_NORMAL)}
        />
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.mode.subtractive"
          icon={<RemoveIcon className="size-tiny" />}
          text={subtractiveLabel}
          pressed={activeTool === ToolKind.SELECTION_SUBTRACTIVE}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.SELECTION_SUBTRACTIVE : ToolKind.SELECTION_NORMAL)}
        />
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.mode.intersect"
          icon={<IntersectIcon className="size-tiny" />}
          text={intersectLabel}
          pressed={activeTool === ToolKind.SELECTION_INTERSECT}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.SELECTION_INTERSECT : ToolKind.SELECTION_NORMAL)}
        />
      </ToolbarGroup>
      <ToolbarDivider />
      <ToolbarGroup>
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.shape.rectangular"
          icon={<DiagramIcon className="size-tiny" />}
          text={rectangularLabel}
          pressed={activeTool === ToolKind.LASSO_RECTANGULAR}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.LASSO_RECTANGULAR : ToolKind.SELECTION_NORMAL)}
        />
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.shape.lasso"
          icon={<SceneIcon className="size-tiny" />}
          text={lassoLabel}
          pressed={activeTool === ToolKind.LASSO_FREEFORM}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.LASSO_FREEFORM : ToolKind.SELECTION_NORMAL)}
        />
      </ToolbarGroup>
      <ToolbarDivider />
      <ToolbarGroup>
        <Toggle
          id="semio.sketchpad.app.kit.tools.select.navigation.hand"
          icon={<HandIcon className="size-tiny" />}
          text={handLabel}
          pressed={activeTool === ToolKind.HAND}
          onPressedChange={(pressed) => setActiveTool?.(pressed ? ToolKind.HAND : ToolKind.SELECTION_NORMAL)}
        />
      </ToolbarGroup>
    </ToolbarGroup>
  );
};

type ToolbarCommandButtonProps = {
  id: string;
  icon: ReactNode;
  text: string;
  disabled?: boolean;
  onClick: () => void;
};

const ToolbarCommandButton: FC<ToolbarCommandButtonProps> = ({ id, icon, text, disabled, onClick }) => <Button id={id} icon={icon} text={text} disabled={disabled} onClick={onClick} />;

export const KitToolbarHistory: FC = () => {
  const store = useKitAppStore();
  const canUndo = useSyncExternalStore(
    (listener) => (store ? store.onChangedDeep(listener) : () => {}),
    () => store?.canUndo() ?? false,
    () => false,
  );
  const canRedo = useSyncExternalStore(
    (listener) => (store ? store.onChangedDeep(listener) : () => {}),
    () => store?.canRedo() ?? false,
    () => false,
  );
  const { undo, redo } = useKitAppCommands();

  return (
    <ToolbarGroup>
      <ToolbarCommandButton id="semio.sketchpad.app.kit.history.undo" icon={<SkipBackIcon className="size-tiny" />} text="Undo" disabled={!canUndo} onClick={() => undo?.()} />
      <ToolbarCommandButton id="semio.sketchpad.app.kit.history.redo" icon={<SkipForwardIcon className="size-tiny" />} text="Redo" disabled={!canRedo} onClick={() => redo?.()} />
    </ToolbarGroup>
  );
};

/**
 * Reset toolbar button for the Kit app.
 * MUST re-import the kit from its remote URL, discarding all local changes.
 **/
export const KitToolbarReset: FC = () => {
  const kit = useKit() as Kit | undefined;
  const kitCommands = useKitCommands();
  const resetLabel = useLabel("semio.sketchpad.app.kit.toolbar.reset");
  const remoteUrl = kit?.remote;
  return (
    <ToolbarGroup>
      <ToolbarCommandButton
        id="semio.sketchpad.app.kit.toolbar.reset"
        icon={<ResetIcon className="size-tiny" />}
        text={resetLabel}
        disabled={!remoteUrl}
        onClick={() => {
          if (remoteUrl && kitCommands) kitCommands.importKit(remoteUrl);
        }}
      />
    </ToolbarGroup>
  );
};

// #endregion 🩻Tools

