// #region 🎏Sketchpad
// Core reactive observation, synchronization hooks, and sketchpad store implementation.

/**
 * Creates a sync observer that triggers the given subscription callback on changes.
 **/
export function createObserver<T>(syncMap: SyncMap<T> | SyncArray<T>, subscribe: Subscribe, deep: boolean = false): Disposable {
  const callback = () => {
    subscribe(() => {});
  };
  if (deep) {
    syncMap.observeDeep(callback);
    return () => syncMap.unobserveDeep(callback);
  } else {
    syncMap.observe(callback);
    return () => syncMap.unobserve(callback);
  }
}

/**
 * Creates a sync field observer that tracks a single key on a SyncMap.
 **/
export function createFieldObserver<T>(syncMap: SyncMap<T>, key: string, subscribe: Subscribe, deep: boolean = false): Disposable {
  const disposables: Disposable[] = [];
  let currentValue = syncMap.get(key);
  const notifySubscriber = () => subscribe(() => {});
  const setupNestedObserver = (value: any) => {
    if (deep && isSyncMap(value)) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      disposables.push(() => value.unobserveDeep(nestedCallback));
    } else if (deep && isSyncArray(value)) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      disposables.push(() => value.unobserveDeep(nestedCallback));
    }
  };
  if (currentValue !== undefined) setupNestedObserver(currentValue);
  const mapCallback = (event: SyncMapEvent) => {
    if (event.keysChanged.has(key)) {
      disposables.forEach((d) => d());
      disposables.length = 0;
      currentValue = syncMap.get(key);
      if (currentValue !== undefined) setupNestedObserver(currentValue);
      notifySubscriber();
    }
  };
  syncMap.observe(mapCallback);
  return () => {
    syncMap.unobserve(mapCallback);
    disposables.forEach((d) => d());
  };
}

/**
 * Creates a sync observer that tracks multiple keys on a SyncMap.
 **/
export function createFieldsObserver<T>(syncMap: SyncMap<T>, keys: string[], subscribe: Subscribe, deep: boolean = false): Disposable {
  const disposables: Disposable[] = [];
  const keySet = new Set(keys);
  const nestedDisposables = new Map<string, Disposable[]>();
  const notifySubscriber = () => subscribe(() => {});
  const setupNestedObserver = (key: string, value: any) => {
    const keyDisposables: Disposable[] = [];
    if (deep && isSyncMap(value)) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      keyDisposables.push(() => value.unobserveDeep(nestedCallback));
    } else if (deep && isSyncArray(value)) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      keyDisposables.push(() => value.unobserveDeep(nestedCallback));
    }
    nestedDisposables.set(key, keyDisposables);
  };
  const cleanupNestedObserver = (key: string) => {
    const keyDisposables = nestedDisposables.get(key);
    if (keyDisposables) {
      keyDisposables.forEach((d) => d());
      nestedDisposables.delete(key);
    }
  };
  keys.forEach((key) => {
    const value = syncMap.get(key);
    if (value !== undefined) setupNestedObserver(key, value);
  });
  const mapCallback = (event: SyncMapEvent) => {
    let shouldNotify = false;
    event.keysChanged.forEach((key) => {
      if (keySet.has(key)) {
        cleanupNestedObserver(key);
        const newValue = syncMap.get(key);
        if (newValue !== undefined) setupNestedObserver(key, newValue);
        shouldNotify = true;
      }
    });
    if (shouldNotify) notifySubscriber();
  };
  syncMap.observe(mapCallback);
  return () => {
    syncMap.unobserve(mapCallback);
    nestedDisposables.forEach((keyDisposables) => keyDisposables.forEach((d) => d()));
    nestedDisposables.clear();
  };
}

/**
 * Creates a sync observer tracking item membership in a SyncArray.
 **/
export function createArrayItemMembershipObserver(getYArray: () => SyncArray<string> | undefined, itemId: string, subscribe: Subscribe): Disposable {
  let wasInArray = false;
  const notifySubscriber = () => subscribe(() => {});

  const checkMembership = () => {
    const syncArray = getYArray();
    return syncArray ? syncArray.toArray().includes(itemId) : false;
  };
  wasInArray = checkMembership();

  let arrayDisposer: Disposable | null = null;

  const setupArrayObserver = () => {
    const syncArray = getYArray();
    if (!syncArray) {
      arrayDisposer = null;
      return;
    }

    const arrayCallback = () => {
      const isInArray = syncArray.toArray().includes(itemId);
      if (isInArray !== wasInArray) {
        wasInArray = isInArray;
        notifySubscriber();
      }
    };

    syncArray.observe(arrayCallback);
    arrayDisposer = () => syncArray.unobserve(arrayCallback);
  };

  setupArrayObserver();

  return () => {
    if (arrayDisposer) arrayDisposer();
  };
}

/**
 * Creates a sync observer tracking nested array item membership within a SyncMap.
 **/
export function createNestedArrayItemMembershipObserver(syncMap: SyncMap<any>, mapKey: string, arrayKey: string, itemId: string, subscribe: Subscribe): Disposable {
  let wasInArray = false;
  let currentNestedMap: SyncMap<any> | undefined;
  let currentArray: SyncArray<string> | undefined;
  let nestedMapDisposer: Disposable | null = null;
  let arrayDisposer: Disposable | null = null;
  const notifySubscriber = () => subscribe(() => {});

  const checkMembership = (): boolean => {
    const nestedMap = syncMap.get(mapKey) as SyncMap<any> | undefined;
    if (!nestedMap) return false;
    const arr = nestedMap.get(arrayKey) as SyncArray<string> | undefined;
    if (!arr) return false;
    return arr.toArray().includes(itemId);
  };

  const setupArrayObserver = () => {
    if (arrayDisposer) {
      arrayDisposer();
      arrayDisposer = null;
    }

    const nestedMap = syncMap.get(mapKey) as SyncMap<any> | undefined;
    if (!nestedMap) return;

    const arr = nestedMap.get(arrayKey) as SyncArray<string> | undefined;
    if (!arr) return;

    currentArray = arr;

    const arrayCallback = () => {
      const isInArray = arr.toArray().includes(itemId);
      if (isInArray !== wasInArray) {
        wasInArray = isInArray;
        notifySubscriber();
      }
    };

    arr.observe(arrayCallback);
    arrayDisposer = () => arr.unobserve(arrayCallback);
  };

  const setupNestedMapObserver = () => {
    if (nestedMapDisposer) {
      nestedMapDisposer();
      nestedMapDisposer = null;
    }

    const nestedMap = syncMap.get(mapKey) as SyncMap<any> | undefined;
    if (!nestedMap) return;

    currentNestedMap = nestedMap;

    const nestedMapCallback = (event: SyncMapEvent) => {
      if (event.keysChanged.has(arrayKey)) {
        const prevInArray = wasInArray;
        setupArrayObserver();
        wasInArray = checkMembership();
        if (wasInArray !== prevInArray) {
          notifySubscriber();
        }
      }
    };

    nestedMap.observe(nestedMapCallback);
    nestedMapDisposer = () => nestedMap.unobserve(nestedMapCallback);
  };

  const topLevelCallback = (event: SyncMapEvent) => {
    if (event.keysChanged.has(mapKey)) {
      const prevInArray = wasInArray;

      if (arrayDisposer) {
        arrayDisposer();
        arrayDisposer = null;
      }
      if (nestedMapDisposer) {
        nestedMapDisposer();
        nestedMapDisposer = null;
      }

      setupNestedMapObserver();
      setupArrayObserver();
      wasInArray = checkMembership();

      if (wasInArray !== prevInArray) {
        notifySubscriber();
      }
    }
  };

  wasInArray = checkMembership();
  setupNestedMapObserver();
  setupArrayObserver();
  syncMap.observe(topLevelCallback);

  return () => {
    syncMap.unobserve(topLevelCallback);
    if (nestedMapDisposer) nestedMapDisposer();
    if (arrayDisposer) arrayDisposer();
  };
}
/**
 * performanceLoggingEnabled holds the data fields for a performanceLoggingEnabled record.
 **/
let performanceLoggingEnabled = false;
/**
 * performanceLogCounts holds the data fields for a performanceLogCounts record.
 **/
const performanceLogCounts = new Map<string, number>();
/** performanceLogTimestamps holds the data fields for a performanceLogTimestamps record.
 **/
/**
 **/
const performanceLogTimestamps = new Map<string, number>();

/**
 * Enables or disables performance logging for store operations.
 **/
export function enablePerformanceLogging(enabled: boolean = true) {
  performanceLoggingEnabled = enabled;
  if (!enabled) {
    performanceLogCounts.clear();
    performanceLogTimestamps.clear();
  }
}

/** logStateAccess holds the data fields for a logStateAccess record.
 **/
/**
 **/
function logStateAccess(hookName: string, storeType: string, selectorInfo?: string) {
  if (!performanceLoggingEnabled) return;
  const key = `${hookName}:${storeType}${selectorInfo ? `:${selectorInfo}` : ""}`;
  const count = (performanceLogCounts.get(key) || 0) + 1;
  performanceLogCounts.set(key, count);
  const now = Date.now();
  const lastTime = performanceLogTimestamps.get(key) || 0;
  performanceLogTimestamps.set(key, now);
  if (now - lastTime < 100) {
    console.warn(`[PERF] Rapid re-render: ${key} (${count}x, ${now - lastTime}ms apart)`);
  }
}

/**
 * Hook synchronizing a store snapshot with React state via useSyncExternalStore.
 **/
export function useSync<T, TSelected = T>(store: { onChanged: (subscribe: Subscribe) => Disposable; snapshot: () => T }, selector: (value: T) => TSelected = identitySelector as any, deep?: boolean): TSelected {
  const subscribe = useCallback(
    (callback: () => void) => {
      return store.onChanged((cb: () => void) => {
        cb();
        callback();
        return () => {};
      });
    },
    [store],
  );
  const getSnapshot = useCallback(() => {
    logStateAccess("useSync", (store as any).constructor?.name || "unknown", selector === identitySelector ? "FULL_STATE" : "selector");
    return selector(store.snapshot());
  }, [store, selector]);
  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook synchronizing an optional store snapshot returning null when absent.
 **/
export function useSyncOptional<T, TSelected = T>(store: { onChanged: (subscribe: Subscribe) => Disposable; snapshot: () => T } | null | undefined, selector: (value: T) => TSelected = identitySelector as any): TSelected | null {
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!store) return () => {};
      return store.onChanged((cb: () => void) => {
        cb();
        callback();
        return () => {};
      });
    },
    [store],
  );
  const getSnapshot = useCallback(() => {
    if (!store) return null as TSelected | null;
    logStateAccess("useSyncOptional", (store as any).constructor?.name || "unknown", selector === identitySelector ? "FULL_STATE" : "selector");
    return selector(store.snapshot());
  }, [store, selector]);
  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook synchronizing a store snapshot with deep observation support.
 **/
export function useSyncDeep<T, TSelected = T>(store: { onChangedDeep: (subscribe: Subscribe) => Disposable; snapshot: () => T } | null | undefined, selector: (value: T) => TSelected = identitySelector as any, deep?: boolean): TSelected | null {
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!store) return () => {};
      return store.onChangedDeep((cb: () => void) => {
        cb();
        callback();
        return () => {};
      });
    },
    [store],
  );
  const getSnapshot = useCallback(() => {
    if (!store) return null as TSelected | null;
    logStateAccess("useSyncDeep", (store as any).constructor?.name || "unknown", selector === identitySelector ? "FULL_STATE_DEEP" : "selector");
    return selector(store.snapshot());
  }, [store, selector]);
  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook synchronizing a single field of a Sync-backed store.
 **/
export function useSyncField<T, TSelected = T>(
  store: { onFieldChanged: (key: string, subscribe: Subscribe, deep?: boolean) => Disposable; snapshot: () => T; getFieldSnapshot?: (key: string) => any },
  key: string,
  selector: (value: T) => TSelected = identitySelector as any,
  deep: boolean = true,
  comparator?: (a: TSelected, b: TSelected) => boolean,
): TSelected {
  const subscribe = useCallback(
    (callback: () => void) => {
      return store.onFieldChanged(
        key,
        (cb: () => void) => {
          cb();
          callback();
          return () => {};
        },
        deep,
      );
    },
    [store, key, deep],
  );

  const lastResultRef = useRef<{ value: TSelected; json?: string }>({ value: undefined as any });

  const getSnapshot = useCallback(() => {
    let newValue: TSelected;
    if (store.getFieldSnapshot) {
      const fieldValue = store.getFieldSnapshot(key);
      newValue = selector({ [key]: fieldValue } as T);
    } else {
      newValue = selector(store.snapshot());
    }

    if (newValue === null || typeof newValue !== "object") {
      if (newValue === lastResultRef.current.value) {
        return lastResultRef.current.value;
      }
      lastResultRef.current = { value: newValue };
      return newValue;
    }

    if (comparator) {
      if (lastResultRef.current.value !== undefined && comparator(lastResultRef.current.value, newValue)) {
        return lastResultRef.current.value;
      }
      lastResultRef.current = { value: newValue };
      return newValue;
    }

    const newJson = JSON.stringify(newValue);
    if (newJson === lastResultRef.current.json) {
      return lastResultRef.current.value;
    }

    lastResultRef.current = { value: newValue, json: newJson };
    return newValue;
  }, [store, selector, key, comparator]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook synchronizing multiple fields of a Sync-backed store.
 **/
export function useSyncFields<T, TSelected = T>(
  store: { onFieldsChanged: (keys: string[], subscribe: Subscribe, deep?: boolean) => Disposable; snapshot: () => T },
  keys: string[],
  selector: (value: T) => TSelected = identitySelector as any,
  deep: boolean = true,
  comparator?: (a: TSelected, b: TSelected) => boolean,
): TSelected {
  const keysRef = useRef(keys);
  if (keys.length !== keysRef.current.length || keys.some((k, i) => k !== keysRef.current[i])) keysRef.current = keys;
  const stableKeys = keysRef.current;
  const subscribe = useCallback(
    (callback: () => void) => {
      return store.onFieldsChanged(
        stableKeys,
        (cb: () => void) => {
          cb();
          callback();
          return () => {};
        },
        deep,
      );
    },
    [store, stableKeys, deep],
  );

  const lastResultRef = useRef<{ value: TSelected; json?: string }>({ value: undefined as any });

  const getSnapshot = useCallback(() => {
    const newValue = selector(store.snapshot());

    if (newValue === null || typeof newValue !== "object") {
      if (newValue === lastResultRef.current.value) {
        return lastResultRef.current.value;
      }
      lastResultRef.current = { value: newValue };
      return newValue;
    }

    if (comparator) {
      if (lastResultRef.current.value !== undefined && comparator(lastResultRef.current.value, newValue)) {
        return lastResultRef.current.value;
      }
      lastResultRef.current = { value: newValue };
      return newValue;
    }

    const newJson = JSON.stringify(newValue);
    if (newJson === lastResultRef.current.json) {
      return lastResultRef.current.value;
    }

    lastResultRef.current = { value: newValue, json: newJson };
    return newValue;
  }, [store, selector, comparator]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook tracking nested array item membership via sync observation.
 **/
export function useSyncNestedArrayItemMembership(store: { syncMap: SyncMap<any> } | null, mapKey: string, arrayKey: string, itemId: string): boolean {
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!store) return () => {};
      return createNestedArrayItemMembershipObserver(store.syncMap, mapKey, arrayKey, itemId, (cb: () => void) => {
        cb();
        callback();
        return () => {};
      });
    },
    [store, mapKey, arrayKey, itemId],
  );

  const getSnapshot = useCallback(() => {
    if (!store) return false;
    const nestedMap = store.syncMap.get(mapKey) as SyncMap<any> | undefined;
    if (!nestedMap) return false;
    const arr = nestedMap.get(arrayKey) as SyncArray<string> | undefined;
    if (!arr) return false;
    return arr.toArray().includes(itemId);
  }, [store, mapKey, arrayKey, itemId]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook tracking selection item membership via sync observation.
 **/
export function useSyncSelectionItemMembership(store: { syncMap: SyncMap<any> } | null, arrayKey: string, itemId: string): boolean {
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!store) return () => {};

      return createNestedArrayItemMembershipObserver(store.syncMap, "selection", arrayKey, itemId, (cb: () => void) => {
        cb();
        callback();
        return () => {};
      });
    },
    [store, arrayKey, itemId],
  );

  const getSnapshot = useCallback(() => {
    if (!store) return false;
    const selection = store.syncMap.get("selection") as SyncMap<any> | undefined;
    if (!selection) return false;
    const arr = selection.get(arrayKey) as SyncArray<string> | undefined;
    if (!arr) return false;
    return arr.toArray().includes(itemId);
  }, [store, arrayKey, itemId]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

/**
 * Hook traversing a sync path and selecting a value from the resolved node.
 **/
export function usePath<T, TSelected = T>(
  store: { onPathChanged: (path: SyncPath, subscribe: Subscribe) => Disposable; getPathSnapshot: (path: SyncPath) => any } | null,
  path: SyncPath,
  selector: (value: any) => TSelected = identitySelector as any,
): TSelected | undefined {
  const pathKey = useMemo(() => JSON.stringify(path), [path]);
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!store) return () => {};
      return store.onPathChanged(path, () => {
        callback();
        return () => {};
      });
    },
    [store, pathKey],
  );
  const lastResultRef = useRef<{ value: TSelected; json?: string }>({ value: undefined as any });
  const getSnapshot = useCallback(() => {
    if (!store) return undefined;
    const rawValue = store.getPathSnapshot(path);
    const value = isSyncMap(rawValue) || isSyncArray(rawValue) ? rawValue.toJSON() : rawValue;
    const newValue = selector(value);
    if (newValue === null || typeof newValue !== "object") {
      if (newValue === lastResultRef.current.value) return lastResultRef.current.value;
      lastResultRef.current = { value: newValue };
      return newValue;
    }
    const newJson = JSON.stringify(newValue);
    if (newJson === lastResultRef.current.json) return lastResultRef.current.value;
    lastResultRef.current = { value: newValue, json: newJson };
    return newValue;
  }, [store, pathKey, selector]);
  return useSyncExternalStore(subscribe, getSnapshot);
}

function jsonReplacerMapSet(_key: string, value: any): any {
  if (value instanceof Map) return Object.fromEntries(value);
  if (value instanceof Set) return [...value];
  return value;
}

/**
 * Hook computing and caching a derived value from store dependencies.
 **/
export function useDerived<T, TSelected = T>(derivedStore: DerivedStore | null, key: string, deps: BaseDependency[], compute: () => T, selector: (value: T) => TSelected = identitySelector as any): TSelected | undefined {
  const nodeRef = useRef<DerivedNode<T> | null>(null);
  const depsKey = useMemo(() => JSON.stringify(deps.map((d) => ({ path: d.path }))), [deps]);
  useEffect(() => {
    if (!derivedStore) return;
    nodeRef.current = derivedStore.getOrCreate(key, deps, compute);
    return () => {
      nodeRef.current = null;
    };
  }, [derivedStore, key, depsKey]);
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!nodeRef.current) return () => {};
      return nodeRef.current.subscribe(callback);
    },
    [derivedStore, key, depsKey],
  );
  const lastResultRef = useRef<{ value: TSelected; json?: string; version: number }>({ value: undefined as any, version: -1 });
  const getSnapshot = useCallback(() => {
    if (!nodeRef.current) return undefined;
    const ver = nodeRef.current.version;
    if (ver === lastResultRef.current.version) return lastResultRef.current.value;
    const rawValue = nodeRef.current.snapshot();
    const newValue = selector(rawValue);
    if (newValue === null || typeof newValue !== "object") {
      if (newValue === lastResultRef.current.value) {
        lastResultRef.current.version = ver;
        return lastResultRef.current.value;
      }
      lastResultRef.current = { value: newValue, version: ver };
      return newValue;
    }
    const newJson = JSON.stringify(newValue, jsonReplacerMapSet);
    if (newJson === lastResultRef.current.json) {
      lastResultRef.current.version = ver;
      return lastResultRef.current.value;
    }
    lastResultRef.current = { value: newValue, json: newJson, version: ver };
    return newValue;
  }, [derivedStore, key, depsKey, selector]);
  return useSyncExternalStore(subscribe, getSnapshot);
}

