//#region 🥁Action Hooks
// Action hooks MUST provide composable React hooks for Kit app selection, hover, sort, filter, and transaction actions.

/**
 * Tuple type for action hook results pairing an action callback with a canAct flag.
 **/
export type ActionHookResult<TArgs extends any[]> = readonly [action: ((...args: TArgs) => void) | undefined, canAct: boolean];

/**
 * Returns an action to select a single type in the Kit app.
 *MUST return a callback that selects the given type ID.
 **/
export function useKitAppSelectType(): ActionHookResult<[typeId: Id]> {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const kitId = kitScope?.id ?? "";
  const canActEvent = useMemo(() => ({ type: "KIT.SELECT_TYPE" as const, kitId, typeId: "" }), [kitId]);
  const canAct = useSelector(actor, (snapshot) => snapshot.can(canActEvent));
  const action = useMemo(() => {
    if (!canAct) return undefined;
    return (typeId: Id) => actor.send({ type: "KIT.SELECT_TYPE", kitId, typeId });
  }, [actor, kitId, canAct]);
  return [action, canAct];
}

/**
 * Returns an action to deselect a single type in the Kit app.
 *MUST return a callback that deselects the given type ID.
 **/
export function useKitAppDeselectType(): ActionHookResult<[typeId: Id]> {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const kitId = kitScope?.id ?? "";
  const canActEvent = useMemo(() => ({ type: "KIT.DESELECT_TYPE" as const, kitId, typeId: "" }), [kitId]);
  const canAct = useSelector(actor, (snapshot) => snapshot.can(canActEvent));
  const action = useMemo(() => {
    if (!canAct) return undefined;
    return (typeId: Id) => actor.send({ type: "KIT.DESELECT_TYPE", kitId, typeId });
  }, [actor, kitId, canAct]);
  return [action, canAct];
}

