// 📑#region 📌Design
const KitSectionLazy = KitSection;

/**
 * Tracks the current piece, connection, and connector selection state for the Design app.
 **/
export interface DesignAppSelection {
  pieces?: Id[];
  connections?: Id[];
  connectors?: Array<{ piece: Id; connector: Id }>;
  connector?: { piece: Id; designPiece?: Id; connector: Id };
}

/**
 * Normalizes an individual design connector selection record.
 *
 * MUST reject incomplete records and preserve the optional design piece ID.
 **/
const normalizeDesignConnectorRecord = (connector: { piece?: Id; designPiece?: Id; connector?: Id } | undefined): DesignAppSelection["connector"] | undefined => {
  if (!connector?.piece || !connector?.connector) return undefined;
  return connector.designPiece ? { piece: connector.piece, connector: connector.connector, designPiece: connector.designPiece } : { piece: connector.piece, connector: connector.connector };
};

/**
 * Returns the primary selected connector from the design selection shape.
 *
 * MUST normalize both singular and array connector selection representations to one record.
 **/
const getPrimaryDesignConnectorSelection = (selection: DesignAppSelection | undefined): DesignAppSelection["connector"] | undefined => {
  const primary = normalizeDesignConnectorRecord(selection?.connector);
  if (primary) return primary;
  for (const connector of selection?.connectors ?? []) {
    const normalizedConnector = normalizeDesignConnectorRecord(connector);
    if (normalizedConnector) return normalizedConnector;
  }
  return undefined;
};

/**
 * Normalizes the design selection shape into the canonical connector-selection representation.
 *
 * MUST keep the singular and array connector lanes in sync and collapse empty arrays to undefined.
 **/
const normalizeDesignAppSelection = (selection: DesignAppSelection | undefined): DesignAppSelection => {
  const normalizedSelection: DesignAppSelection = {};

  if (selection?.pieces?.length) normalizedSelection.pieces = selection.pieces;
  if (selection?.connections?.length) normalizedSelection.connections = selection.connections;

  const normalizedConnector = getPrimaryDesignConnectorSelection(selection);
  if (normalizedConnector) {
    normalizedSelection.connector = normalizedConnector;
    normalizedSelection.connectors = [normalizedConnector];
  }

  return normalizedSelection;
};

/**
 * Builds a normalized design connector selection payload.
 *
 * MUST keep both singular and array connector lanes in sync while clearing piece and connection selection.
 **/
const createDesignConnectorSelection = (pieceId: Id, connectorId: Id, designPieceId?: Id): DesignAppSelection => {
  const connectorSelection = designPieceId ? { piece: pieceId, connector: connectorId, designPiece: designPieceId } : { piece: pieceId, connector: connectorId };
  return normalizeDesignAppSelection({
    pieces: [],
    connections: [],
    connector: connectorSelection,
    connectors: [connectorSelection],
  });
};

/**
 * Removes connector-specific selection lanes from a design selection.
 *
 * MUST preserve all non-connector selection data.
 **/
const stripDesignConnectorSelection = (selection: DesignAppSelection | undefined): DesignAppSelection => {
  const { connector: _connector, connectors: _connectors, ...rest } = selection ?? {};
  return normalizeDesignAppSelection(rest);
};
/**
 * Diff for added/removed piece IDs in a selection change.
 **/
export interface DesignAppSelectionPiecesDiff {
  added?: Id[];
  removed?: Id[];
}
/**
 * Diff for added/removed connection IDs in a selection change.
 **/
export interface DesignAppSelectionConnectionsDiff {
  added?: Id[];
  removed?: Id[];
}
/**
 * Diff for a selected port change identifying the piece and connector.
 **/
export interface DesignAppSelectionPortDiff {
  piece?: Id;
  designPiece?: Id;
  connector?: Id;
}
/**
 * Composite diff combining pieces, connections, and connector selection changes.
 **/
export interface DesignAppSelectionDiff {
  pieces?: DesignAppSelectionPiecesDiff;
  connections?: DesignAppSelectionConnectionsDiff;
  connector?: DesignAppSelectionPortDiff;
}
/**
 * Enumeration of window kinds available in the Design app.
 **/
export enum DesignAppWindowKind {
  Diagram = "diagram",
  Scene = "scene",
  Settings = "settings",
  Chat = "chat",
}
/**
 * Presence state for a Design app user including cursor, camera, and diagram viewport.
 **/
export interface DesignAppPresence {
  cursor?: Coordinate;
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
}
/**
 * Hover state tracking which pieces, connections, connectors, types, and designs are hovered.
 **/
export interface DesignAppHover {
  pieces?: Id[];
  connections?: Id[];
  connectors?: { piece: Id; designPiece?: Id; connector: Id }[];
  types?: Id[];
  designs?: Id[];
}
/**
 * Extended presence for other collaborators including their display name.
 **/
export interface DesignAppPresenceOther extends DesignAppPresence {
  name: string;
}
/**
 * Complete diff describing all mutable Design app state changes.
 **/
export interface DesignAppDiff {
  selection?: DesignAppSelectionDiff;
  presence?: DesignAppPresence;
  hover?: DesignAppHover;
  fullscreenWindow?: DesignAppFullscreenWindow;
  panelVisibility?: Partial<PanelVisibility>;
  activeTool?: ToolKind;
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
  focusedPieceId?: Id | null;
  selectedRepresentationTags?: Record<Id, string[]>;
  windowLayout?: any;
}
/**
 * Edit record extending KitDiffAppEdit with Design app selection diff.
 **/
export interface DesignAppEdit extends KitDiffAppEdit<DesignAppSelectionDiff> {}
/**
 * Complete runtime state for a Design app instance.
 **/
export interface DesignAppState {
  fullscreenWindow: DesignAppFullscreenWindow;
  panelVisibility: PanelVisibility;
  activeTool?: ToolKind;
  selection?: DesignAppSelection;
  hover?: DesignAppHover;
  presence?: DesignAppPresence;
  others: DesignAppPresenceOther[];
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
  focusedPieceId?: Id;
  currentTransactionStackLength?: number;
  selectedRepresentationTags?: Record<Id, string[]>;
  windowLayout?: any;
}

/**
 * Context passed to Design app commands including app state, ID, and design data.
 **/
export interface DesignAppCommandContext extends KitCommandContext {
  designApp: DesignAppState;
  Id: Id;
  design: Design;
}
/**
 * Result returned by Design app commands containing diffs to apply.
 **/
export interface DesignAppCommandResult {
  diff?: DesignAppDiff;
  kitDiff?: KitDiff;
}

// #endregion 📌Types

// #region 💧Commands
// Commands MUST define all executable Design app actions dispatched by keyboard shortcuts and UI interactions.

