/**
 * Returns a hook result for the Design app diagram center coordinate.
 *MUST provide the current diagram center, a setter, and a canSet flag.
 **/
export function useDesignAppDiagramCenter(): HookResult<Coordinate | undefined> {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const kitId = kitScope?.id ?? "";
  const designId = designScope?.id ?? "";
  const selector = useMemo(() => createDesignDiagramCenterSelector(kitId, designId), [kitId, designId]);
  const rawValue = useSelector(actor, selector);
  const value = useMemo(() => (rawValue ? { u: rawValue.x, v: rawValue.y } : undefined), [rawValue]);
  const canSetEvent = useMemo(() => ({ type: "DESIGN.SET_DIAGRAM_CENTER" as const, kitId, designId, center: { x: 0, y: 0 } }), [kitId, designId]);
  const canSet = useSelector(actor, (snapshot) => snapshot.can(canSetEvent));
  const setter = useMemo(() => {
    if (!canSet) return undefined;
    return (center: Coordinate | undefined) => {
      if (center) {
        actor.send({ type: "DESIGN.SET_DIAGRAM_CENTER", kitId, designId, center: { x: center.u, y: center.v } });
      }
    };
  }, [actor, kitId, designId, canSet]);
  return conditionalHookResult(canSet, value, setter);
}

