  execute: () => {},
  startTransaction: () => {},
  finalizeTransaction: () => {},
  abortTransaction: () => {},
  undo: () => {},
  redo: () => {},
  selectAll: () => {},
  deselectAll: () => {},
  selectPiece: () => {},
  selectPieces: () => {},
  addPieceToSelection: () => {},
  removePieceFromSelection: () => {},
  selectConnection: () => {},
  addConnectionToSelection: () => {},
  removeConnectionFromSelection: () => {},
  selectPiecePort: () => {},
  deselectPiecePort: () => {},
  deleteSelected: () => {},
  toggleDiagramFullscreen: () => {},
  toggleAccesslFullscreen: () => {},
  setActiveTool: () => {},
  addPiece: () => {},
  addPieces: () => {},
  removePiece: () => {},
  removePieces: () => {},
