class MeshErrorBoundary extends React.Component<{ children: ReactNode; fallback: ReactNode }, { hasError: boolean }> {
  constructor(props: { children: ReactNode; fallback: ReactNode }) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error: Error) {
    console.debug(`[DEBUG] [MeshErrorBoundary] Caught error loading 3D representation:`, error.message);
  }
  render() {
    if (this.state.hasError) {
      return this.props.fallback;
    }
    return this.props.children;
  }
}

const LoadedPieceMesh: FC<{ url: string; fileExtension: string; highlightColor: string | null } & DesignMeshEventProps> = ({ url, fileExtension, highlightColor, onClick, onDoubleClick, onPointerEnter, onPointerLeave }) => {
  const ext = fileExtension.toLowerCase();
  if (ext === "glb" || ext === "gltf") {
    return <GLTFMesh url={url} highlightColor={highlightColor} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} />;
  } else if (ext === "fbx") {
    return <FBXMesh url={url} highlightColor={highlightColor} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} />;
  } else if (ext === "obj") {
    return <OBJMesh url={url} highlightColor={highlightColor} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} />;
  } else {
    return <GLTFMesh url={url} highlightColor={highlightColor} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} />;
  }
};

const PieceMesh: FC<{ highlightColor: string | null } & DesignMeshEventProps> = ({ highlightColor, onClick, onDoubleClick, onPointerEnter, onPointerLeave }) => {
  const piece = usePiece() as Piece;
  const type = useType(undefined, typeof piece.type === "string" ? piece.type : piece.type?.id) as Type | undefined;
  const typeConcepts = type?.concepts;
  const files = useKitFiles();
  const kitStoreRaw = useKitStoreFromProvider();
  const kitStore = useMemo(
    () => (kitStoreRaw ? new CollaborativeKitStore(kitStoreRaw) : null),
    [kitStoreRaw],
  );
  const [selectedRepresentationTags] = useDesignAppSelectedRepresentationTags();
  const [blobUrl, setBlobUrl] = useState<string | null>(null);
  const prevRepresentationIdRef = useRef<string | null>(null);

  useEffect(() => {
    const typeRef = typeof piece.type === "string" ? piece.type : piece.type?.id;
    console.log("[DEBUG] [PieceMesh] piece.id:", piece.id, "piece.type:", piece.type, "typeRef:", typeRef, "resolvedType:", type?.id, type?.name, "representations:", type?.representations?.length, "files:", files?.length);
  }, [piece.id, piece.type, type, files]);

  const { representationUrl, fileExtension, fileId, representationId, selectionReason } = useMemo(() => {
    if (!type?.representations || type.representations.length === 0) {
      console.log("[DEBUG] [PieceMesh] No representations for type:", type?.id, type?.name, "type object:", type);
      return { representationUrl: null, fileExtension: "", fileId: null, representationId: null, selectionReason: "no-representations" };
    }

    const tagsForType = selectedRepresentationTags[type.id] ?? [];
    let representation: Representation | undefined;
    let reason = "";

    if (tagsForType.length > 0) {
      representation = selectBestRepresentation(type.representations, tagsForType);
      reason = "manual-tags";
    } else {
      const conceptIds = typeConcepts?.map((concept) => concept.id) ?? [];
      if (conceptIds.length > 0) {
        representation = findRepresentation(type.representations, conceptIds);
        reason = "type-concepts";
      } else {
        const defaultRepresentation = type.representations.find((entry) => !entry.tags || entry.tags.length === 0);
        representation = defaultRepresentation ?? type.representations[0];
        reason = "default/first";
      }
    }

    if (!representation) {
      return { representationUrl: null, fileExtension: "", fileId: null, representationId: null, selectionReason: "no-representation-found" };
    }

    const fileId = typeof representation.file === "string" ? representation.file : representation.file?.id;
    const file = files.find((f) => f.id === fileId);
    if (!file) {
      return { representationUrl: null, fileExtension: "", fileId: null, representationId: representation.id, selectionReason: "file-not-found" };
    }

    const ext = file.name?.split(".").pop() || "";
    if (!kitStore) {
      return { representationUrl: null, fileExtension: ext, fileId: file.id, representationId: representation.id, selectionReason: reason };
    }
    const url = kitStore.getFileUrl(file.id);
    if (!url) {
      return { representationUrl: null, fileExtension: ext, fileId: file.id, representationId: representation.id, selectionReason: reason };
    }

    return { representationUrl: url, fileExtension: ext, fileId: file.id, representationId: representation.id, selectionReason: reason };
  }, [type, typeConcepts, files, kitStore, selectedRepresentationTags]);

  useEffect(() => {
    if (representationId && representationId !== prevRepresentationIdRef.current) {
      prevRepresentationIdRef.current = representationId;
    } else if (!representationId && selectionReason === "no-representations") {
      console.warn("[PieceMesh] No representations available for type:", type?.id, type?.name);
    } else if (!representationId && selectionReason === "no-representation-found") {
      console.warn("[PieceMesh] No representation found for type:", type?.id);
    } else if (selectionReason === "file-not-found" && representationId !== prevRepresentationIdRef.current) {
      prevRepresentationIdRef.current = representationId;
      console.warn("[PieceMesh] File not found in kit for representation:", representationId);
    }
  }, [representationId, selectionReason, type]);

  useEffect(() => {
    setBlobUrl(representationUrl ?? null);
    if (!fileId || !kitStore) {
      return;
    }
    let cancelled = false;
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    let retryCount = 0;
    const maxRetries = 3;
    const load = async () => {
      try {
        const url = await kitStore.getFileBlobUrl(fileId);
        if (!cancelled && url) {
          setBlobUrl(url);
        } else if (!cancelled && !url && retryCount < maxRetries) {
          retryCount++;
          console.debug(`[DEBUG] [PieceMesh] No URL for file ${fileId}, retry ${retryCount}/${maxRetries}`);
          retryTimer = setTimeout(load, 1000 * retryCount);
        } else if (!cancelled && !url) {
          console.warn("[PieceMesh] No URL available for file after retries:", fileId);
        }
      } catch (error) {
        console.error("[PieceMesh] Failed to get blob URL:", error);
      }
    };
    load();

    return () => {
      cancelled = true;
      if (retryTimer) clearTimeout(retryTimer);
    };
  }, [fileId, kitStore, representationUrl]);

  const renderUrl = blobUrl ?? representationUrl;

  if (!renderUrl) {
    return <Geometry hovered={false} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} showEdges={true} />;
  }

  const fallbackGeometry = <Geometry hovered={false} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} showEdges={true} />;

  return (
    <MeshErrorBoundary fallback={fallbackGeometry}>
      <Suspense fallback={null}>
        <LoadedPieceMesh url={renderUrl} fileExtension={fileExtension} highlightColor={highlightColor} onClick={onClick} onDoubleClick={onDoubleClick} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} />
      </Suspense>
    </MeshErrorBoundary>
  );
};

interface RepresentationPieceProps {}
// [👤semio📚js🗃️sketchpad💻design🔖canvas🔖scene🪨representationpiece](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Canvas/s/Scene/d/i/RepresentationPiece)
/**
 * RepresentationPiece holds the data fields for a RepresentationPiece record.
 **/
const RepresentationPiece: FC<RepresentationPieceProps> = () => {
  const piece = usePiece() as Piece;
  const diffedPiece = useDiffedPiece() as Piece;
  const isSelected = useIsPieceSelected();
  const isHovered = useIsPieceTransitiveHovered();
  const status = usePieceStatus();
  const flatPlane = useFlatPiecePlane();

  const [selection, setSelection] = useDesignAppSelection();
  const { hoverPiece, clearHover } = useDesignAppHoverActions();
  const [focusPiece] = useDesignAppFocusPiece();
  const { currentHoveredPieceIdRef, hoverClearTimeoutRef } = useHoverIntent();
  const [activeTool] = useDesignAppActiveTool();

  const { fill } = useDesignAppPieceColor(undefined, piece.id);

  const foregroundColor = useMemo(() => getComputedColor("--foreground"), []);
  const mutedForegroundColor = useMemo(() => getComputedColor("--muted-foreground"), []);
  const activeBaseColor = useMemo(() => getComputedColor("--active-base"), []);
  const hoverBaseColor = useMemo(() => getComputedColor("--hover-base"), []);
  const highlightColor = useMemo(() => (isSelected ? activeBaseColor : isHovered ? hoverBaseColor : null), [isSelected, isHovered, activeBaseColor, hoverBaseColor]);

  const isConnectedChild = useIsConnectedPiece();
  const originalPlane = isConnectedChild ? flatPlane : piece.plane || flatPlane;
  const diffedPlane = isConnectedChild ? flatPlane : diffedPiece.plane || flatPlane;

  const hasDiff = useMemo(() => {
    if (status === DiffStatus.Unchanged) return false;
    if (!originalPlane || !diffedPlane) return false;

    const p1 = originalPlane;
    const p2 = diffedPlane;
    return (
      p1.origin.x !== p2.origin.x ||
      p1.origin.y !== p2.origin.y ||
      p1.origin.z !== p2.origin.z ||
      p1.xAxis.x !== p2.xAxis.x ||
      p1.xAxis.y !== p2.xAxis.y ||
      p1.xAxis.z !== p2.xAxis.z ||
      p1.yAxis.x !== p2.yAxis.x ||
      p1.yAxis.y !== p2.yAxis.y ||
      p1.yAxis.z !== p2.yAxis.z
    );
  }, [status, originalPlane, diffedPlane]);

  const onSelect = useCallback(
    (e?: ThreeEvent<MouseEvent>) => {
      const compositionKind = resolveSelectionCompositionKind(activeTool, {
        shiftKey: e?.shiftKey === true,
        altKey: e?.altKey === true,
        ctrlKey: e?.ctrlKey === true,
        metaKey: e?.metaKey === true,
      });
      setSelection?.({
        ...(selection || {}),
        pieces: applySelectionComposition(selection?.pieces, [piece.id], compositionKind),
        connections: compositionKind === "replace" ? [] : selection?.connections || [],
      });
    },
    [activeTool, piece.id, selection, setSelection],
  );

  const onDoubleClick = useCallback(
    (e?: ThreeEvent<MouseEvent>) => {
      e?.stopPropagation();
      if (focusPiece) focusPiece(piece.id);
    },
    [focusPiece, piece.id],
  );

  const handlePointerEnter = useCallback(
    (e?: ThreeEvent<PointerEvent>) => {
      e?.stopPropagation();
      if (hoverClearTimeoutRef.current) {
        clearTimeout(hoverClearTimeoutRef.current);
        hoverClearTimeoutRef.current = null;
      }
      if (currentHoveredPieceIdRef.current !== piece.id) {
        currentHoveredPieceIdRef.current = piece.id;
        if (hoverPiece) hoverPiece(piece.id);
      }
    },
    [piece.id, hoverPiece, currentHoveredPieceIdRef, hoverClearTimeoutRef],
  );

  const handlePointerLeave = useCallback(
    (e?: ThreeEvent<PointerEvent>) => {
      e?.stopPropagation();
      if (hoverClearTimeoutRef.current) clearTimeout(hoverClearTimeoutRef.current);
      const pieceIdAtLeave = piece.id;
      hoverClearTimeoutRef.current = setTimeout(() => {
        if (currentHoveredPieceIdRef.current === pieceIdAtLeave) {
          currentHoveredPieceIdRef.current = null;
          if (clearHover) clearHover();
        }
        hoverClearTimeoutRef.current = null;
      }, 50);
    },
    [piece.id, clearHover, currentHoveredPieceIdRef, hoverClearTimeoutRef],
  );

  const materialColor = useMemo(() => {
    const tempDiv = document.createElement("div");
    tempDiv.style.position = "absolute";
    tempDiv.style.visibility = "hidden";
    tempDiv.style.pointerEvents = "none";
    document.body.appendChild(tempDiv);
    tempDiv.style.color = fill;
    const computedColor = getComputedStyle(tempDiv).color;
    document.body.removeChild(tempDiv);

    const canvas = document.createElement("canvas");
    canvas.width = 1;
    canvas.height = 1;
    const ctx = canvas.getContext("2d");
    if (!ctx) return computedColor;

    ctx.fillStyle = computedColor;
    ctx.fillRect(0, 0, 1, 1);
    const imageData = ctx.getImageData(0, 0, 1, 1);
    const [r, g, b, a] = imageData.data;

    if (a === 0) {
      return foregroundColor;
    }

    return `rgb(${r}, ${g}, ${b})`;
  }, [fill, foregroundColor]);
  const emissiveColor = materialColor;

  const originalMatrix = useMemo(() => {
    if (!originalPlane) return null;
    const planeMatrix = planeToMatrix(originalPlane as Plane);
    const threeMatrix = new THREE.Matrix4().multiplyMatrices(toThreeRotation(), planeMatrix).multiply(toSemioRotation());
    return threeMatrix;
  }, [originalPlane]);

  const diffedMatrix = useMemo(() => {
    if (!diffedPlane || !hasDiff) return null;
    const planeMatrix = planeToMatrix(diffedPlane as Plane);
    const threeMatrix = new THREE.Matrix4().multiplyMatrices(toThreeRotation(), planeMatrix).multiply(toSemioRotation());
    return threeMatrix;
  }, [diffedPlane, hasDiff]);

  const transformProps = useMemo(() => {
    const matrix = diffedMatrix || originalMatrix;
    if (!matrix || !originalPlane) return null;
    const position = new THREE.Vector3();
    const quaternion = new THREE.Quaternion();
    const scale = new THREE.Vector3();
    matrix.decompose(position, quaternion, scale);
    return { position, quaternion, scale };
  }, [diffedMatrix, originalMatrix, originalPlane]);

  const originalMeshContent =
    hasDiff && originalMatrix ? (
      <group matrix={originalMatrix} matrixAutoUpdate={false}>
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshStandardMaterial transparent opacity={0} />
          <Edges scale={1.001} color={mutedForegroundColor} />
        </mesh>
      </group>
    ) : null;

  const userData = useMemo(() => ({ id: piece.id, pieceId: piece.id }), [piece.id]);

  const diffedMeshContent = piece.design ? (
    <Geometry
      selected={isSelected}
      hovered={isHovered}
      onClick={onSelect}
      onDoubleClick={onDoubleClick}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      color={materialColor}
      emissiveColor={emissiveColor}
      emissiveIntensity={0.45}
      showEdges
      userData={userData}
    />
  ) : (
    <group userData={userData}>
      <PieceMesh highlightColor={highlightColor} onClick={onSelect} onDoubleClick={onDoubleClick} onPointerEnter={handlePointerEnter} onPointerLeave={handlePointerLeave} />
    </group>
  );

  const pieceMatrix = diffedMatrix || originalMatrix;

  return (
    <>
      {originalMeshContent}
      {pieceMatrix && (
        <group userData={userData} matrix={pieceMatrix} matrixAutoUpdate={false}>
          {diffedMeshContent}
        </group>
      )}
    </>
  );
};

/** RepresentationDesign holds the data fields for a RepresentationDesign record.
 **/
/**
 **/
const RepresentationDesign: FC = () => {
  const [transaction] = useDesignAppTransaction();
  const [updatePiece] = useDesignAppUpdatePiece();
  const [selection] = useDesignAppSelection();
  const [others] = useDesignAppOthers();
  const design = useDesign();
  const flatDesign = design as Design;
  const { showPieces } = useDesignFilters();

  const [selectPieces] = useDesignAppSelectPieces();

  // ♻️Memoize resolvePieceId to avoid recreating it on every onChange
  const resolvePieceId = useCallback((object: THREE.Object3D | undefined): string | undefined => {
    let current: THREE.Object3D | null | undefined = object;
    while (current) {
      const pieceId = current.userData?.pieceId;
      if (typeof pieceId === "string" && pieceId.length > 0) return pieceId;
      const id = current.userData?.id;
      if (typeof id === "string" && id.length > 0) return id;
      current = current.parent;
    }
    return undefined;
  }, []);

  // 🆕Create a stable Set reference for previous selection for O(1) lookups
  const previousSelectionSet = useMemo(() => new Set((selection.pieces ?? []).map((entry) => resolveSelectionEntryId(entry)).filter((entry): entry is Id => typeof entry === "string" && entry.length > 0)), [selection.pieces]);

  const onChange = useCallback(
    (selected: THREE.Object3D[]) => {
      // 🔷Resolve piece IDs
      const newSelectedPieceIds = Array.from(new Set(selected.map((item) => resolvePieceId(item)).filter((value): value is string => !!value)));

      // 🗃️Fast Set-based comparison - O(n) instead of O(n²)
      const newSelectionSet = new Set(newSelectedPieceIds);

      // ✔️Check if selection changed using Set comparison
      const changed = newSelectionSet.size !== previousSelectionSet.size || Array.from(newSelectionSet).some((id) => !previousSelectionSet.has(id));

      if (changed) {
        if (selectPieces) selectPieces(newSelectedPieceIds);
      }
    },
    [selectPieces, resolvePieceId, previousSelectionSet],
  );

  type TransformableRepresentation = { id: string; plane: Plane | undefined; isTransformable: boolean; isSelected: boolean };

  // 🔶Optimize selectedRepresentations using Set for O(1) lookup instead of O(n) includes
  const selectedRepresentations = useMemo((): TransformableRepresentation[] => {
    if (!selection.pieces || !flatDesign?.pieces) return [];

    const selectedPiecesSet = new Set((selection.pieces || []).map((entry) => resolveSelectionEntryId(entry)).filter((entry): entry is Id => typeof entry === "string" && entry.length > 0));
    return flatDesign.pieces
      .filter((piece) => selectedPiecesSet.has(piece.id))
      .map((piece) => ({
        id: piece.id,
        plane: piece.plane,
        isTransformable: !piece.isLocked && piece.plane !== undefined && piece.center !== undefined,
      }));
  }, [selection.pieces, flatDesign?.pieces]);

  const handleMultiPlaneUpdate = useCallback(
    (updates: Array<{ representationId: string; newPlane: Plane }>) => {
      updates.forEach(({ representationId, newPlane }) => {
        updatePiece?.(representationId, { plane: newPlane });
      });
    },
    [updatePiece],
  );

  return (
    <>
      <DreiSelect box multiple onChange={onChange}>
        <group>
          {showPieces &&
            flatDesign?.pieces?.map((piece: Piece) => (
              <PieceScopeProvider key={piece.id} id={piece.id}>
                <RepresentationPiece />
              </PieceScopeProvider>
            ))}
          {others.map((presence, id) => (
            <PresenceThree key={id} {...presence} />
          ))}
        </group>
      </DreiSelect>
    </>
  );
};

/** DesignAppScene holds the data fields for a DesignAppScene record.
 **/
/**
 **/
/** SceneContextBridge re-provides DOM-tree React contexts inside the R3F reconciler.
 * R3F v9 creates a separate React root, so contexts from the DOM tree are not available.
 * This bridge reads context values in the DOM tree and re-provides them inside R3F.
 **/
const SceneContextBridge: FC<{
  designScope: React.ContextType<typeof DesignScopeContext>;
  kitScope: React.ContextType<typeof KitScopeContext>;
  sketchpadScope: React.ContextType<typeof SketchpadScopeContext>;
  sketchpadActor: React.ContextType<typeof SketchpadActorContext>;
  designAppScope: React.ContextType<typeof DesignAppScopeContext>;
  designAppActor: React.ContextType<typeof DesignAppActorContext>;
  designFilterState: React.ContextType<typeof DesignFilterContext>;
  hoverIntentValue: React.ContextType<typeof HoverIntentContext>;
  transactionPiecesValue: React.ContextType<typeof TransactionPiecesContext>;
  hoverPiecesValue: React.ContextType<typeof HoverPiecesStoreContext>;
  children: React.ReactNode;
}> = ({ designScope, kitScope, sketchpadScope, sketchpadActor, designAppScope, designAppActor, designFilterState, hoverIntentValue, transactionPiecesValue, hoverPiecesValue, children }) => {
  return (
    <SketchpadScopeContext.Provider value={sketchpadScope}>
      <SketchpadActorContext.Provider value={sketchpadActor}>
        <KitScopeContext.Provider value={kitScope}>
          <DesignScopeContext.Provider value={designScope}>
            <DesignAppScopeContext.Provider value={designAppScope}>
              <DesignAppActorContext.Provider value={designAppActor}>
                <DesignFilterContext.Provider value={designFilterState}>
                  <HoverIntentContext.Provider value={hoverIntentValue}>
                    <TransactionPiecesContext.Provider value={transactionPiecesValue}>
                      <HoverPiecesStoreContext.Provider value={hoverPiecesValue}>{children}</HoverPiecesStoreContext.Provider>
                    </TransactionPiecesContext.Provider>
                  </HoverIntentContext.Provider>
                </DesignFilterContext.Provider>
              </DesignAppActorContext.Provider>
            </DesignAppScopeContext.Provider>
          </DesignScopeContext.Provider>
        </KitScopeContext.Provider>
      </SketchpadActorContext.Provider>
    </SketchpadScopeContext.Provider>
  );
};

const DesignAppScene: FC = () => {
  const [transaction] = useDesignAppTransaction();
  const [addPiece] = useDesignAppAddPiece();
  const [deselectAll] = useDesignAppDeselectAll();
  const [toggleAccesslFullscreen] = useDesignAppToggleAccesslFullscreen();
  const [, setCamera] = useDesignAppCamera();
  const [clearFocus] = useDesignAppClearFocus();
  const [camera] = useDesignAppCamera();
  const [activeTool] = useDesignAppActiveTool();
  const selectionOnDrag = activeTool !== ToolKind.HAND;
  const [focusedPieceId] = useDesignAppFocusedPieceId();
  const [projection, setProjection] = React.useState<"camera" | "orthographic">("camera");
  const sceneTypes = useKitTypes();
  const sceneDesigns = useKitDesigns();
  const { setActiveDraggedType, setActiveDraggedDesign } = useDragDrop();
  const sceneDropZoneRef = useRef<HTMLDivElement | null>(null);
  const sceneId = useRef(id()).current;

  // 🔭Read all context values in DOM tree for bridging into R3F
  const designScope = useDesignScope();
  const kitScope = useKitScope();
  const sketchpadScope = useSketchpadScope();
  const sketchpadActor = useSketchpadActor();
  const designAppScope = useDesignAppScope();
  const designAppActor = useDesignAppActor();
  const designFilterState = useDesignFilters();
  const hoverIntentValue = useContext(HoverIntentContext);
  const transactionPiecesValue = useContext(TransactionPiecesContext);
  const hoverPiecesValue = useContext(HoverPiecesStoreContext);

  const handleSceneDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, delta } = event;
      if (!sceneDropZoneRef.current) return;
      if (!(event.activatorEvent instanceof MouseEvent)) return;
      const dropX = event.activatorEvent.clientX + delta.x;
      const dropY = event.activatorEvent.clientY + delta.y;
      const dropZoneBounds = sceneDropZoneRef.current.getBoundingClientRect();
      const isWithinBounds = dropX >= dropZoneBounds.left && dropX <= dropZoneBounds.right && dropY >= dropZoneBounds.top && dropY <= dropZoneBounds.bottom;
      if (!isWithinBounds) return;
      const dragData = active.data.current as { type: string; typeId?: string; designId?: string } | undefined;
      if (!dragData) return;
      const localX = dropX - dropZoneBounds.left;
      const localY = dropY - dropZoneBounds.top;
      const ndcX = (localX / dropZoneBounds.width) * 2 - 1;
      const ndcY = -(localY / dropZoneBounds.height) * 2 + 1;
      const zoom = 50;
      const camPos = camera?.position ?? { x: 10, y: 10, z: 10 };
      const camForward = camera?.forward ?? { x: -1, y: -1, z: -1 };
      const camUp = camera?.up ?? { x: 0, y: 1, z: 0 };
      const fwdLen = Math.sqrt(camForward.x ** 2 + camForward.y ** 2 + camForward.z ** 2);
      const fwd = { x: camForward.x / fwdLen, y: camForward.y / fwdLen, z: camForward.z / fwdLen };
      const rightX = camUp.y * fwd.z - camUp.z * fwd.y;
      const rightY = camUp.z * fwd.x - camUp.x * fwd.z;
      const rightZ = camUp.x * fwd.y - camUp.y * fwd.x;
      const rightLen = Math.sqrt(rightX ** 2 + rightY ** 2 + rightZ ** 2);
      const right = { x: rightX / rightLen, y: rightY / rightLen, z: rightZ / rightLen };
      const upX = fwd.y * right.z - fwd.z * right.y;
      const upY = fwd.z * right.x - fwd.x * right.z;
      const upZ = fwd.x * right.y - fwd.y * right.x;
      const upLen = Math.sqrt(upX ** 2 + upY ** 2 + upZ ** 2);
      const actualUp = { x: upX / upLen, y: upY / upLen, z: upZ / upLen };
      const halfWidth = dropZoneBounds.width / (2 * zoom);
      const halfHeight = dropZoneBounds.height / (2 * zoom);
      const perspectiveFieldOfViewRadians = (75 * Math.PI) / 180;
      const perspectiveAspectRatio = dropZoneBounds.width / Math.max(dropZoneBounds.height, 1);
      const perspectiveHalfHeight = Math.tan(perspectiveFieldOfViewRadians / 2);
      const perspectiveHalfWidth = perspectiveHalfHeight * perspectiveAspectRatio;
      const rayOrigin =
        projection === "orthographic"
          ? {
              x: camPos.x + right.x * ndcX * halfWidth + actualUp.x * ndcY * halfHeight,
              y: camPos.y + right.y * ndcX * halfWidth + actualUp.y * ndcY * halfHeight,
              z: camPos.z + right.z * ndcX * halfWidth + actualUp.z * ndcY * halfHeight,
            }
          : camPos;
      const rayDirection =
        projection === "orthographic"
          ? fwd
          : (() => {
              const perspectiveDirection = {
                x: fwd.x + right.x * ndcX * perspectiveHalfWidth + actualUp.x * ndcY * perspectiveHalfHeight,
                y: fwd.y + right.y * ndcX * perspectiveHalfWidth + actualUp.y * ndcY * perspectiveHalfHeight,
                z: fwd.z + right.z * ndcX * perspectiveHalfWidth + actualUp.z * ndcY * perspectiveHalfHeight,
              };
              const perspectiveDirectionLength = Math.sqrt(perspectiveDirection.x ** 2 + perspectiveDirection.y ** 2 + perspectiveDirection.z ** 2);
              return {
                x: perspectiveDirection.x / perspectiveDirectionLength,
                y: perspectiveDirection.y / perspectiveDirectionLength,
                z: perspectiveDirection.z / perspectiveDirectionLength,
              };
            })();
      if (Math.abs(rayDirection.y) <= 0.0001) return;
      const t = -rayOrigin.y / rayDirection.y;
      const threeX = rayOrigin.x + rayDirection.x * t;
      const threeZ = rayOrigin.z + rayDirection.z * t;
      const semioX = threeX;
      const semioY = -threeZ;
      const semioZ = 0;
      const plane: Plane = { origin: { x: semioX, y: semioY, z: semioZ }, xAxis: { x: 1, y: 0, z: 0 }, yAxis: { x: 0, y: 1, z: 0 } };
      const center = { u: semioX * 0.3 + 6, v: semioY * 0.3 - 7 };
      if (dragData.type === "type" && dragData.typeId) {
        const droppedType = sceneTypes?.find((t) => t.id === dragData.typeId);
        if (!droppedType) return;
        transaction?.start();
        const pieceId = id();
        const piece = { id: pieceId, id_: pieceId, type: { id: droppedType.id }, plane, center };
        addPiece?.(piece);
        transaction?.finalize();
      } else if (dragData.type === "design" && dragData.designId) {
        const droppedDesign = sceneDesigns?.find((d) => d.id === dragData.designId);
        if (!droppedDesign) return;
        transaction?.start();
        const pieceId = id();
        const piece = { id: pieceId, id_: pieceId, design: { id: droppedDesign.id }, plane, center };
        addPiece?.(piece);
        transaction?.finalize();
      }
      setActiveDraggedType(null);
      setActiveDraggedDesign(null);
    },
    [sceneTypes, sceneDesigns, camera, projection, transaction, addPiece, setActiveDraggedType, setActiveDraggedDesign],
  );

  useEffect(() => {
    const listener = (e: Event) => {
      const customEvent = e as CustomEvent<DragEndEvent>;
      handleSceneDragEnd(customEvent.detail);
    };
    window.addEventListener("design-drag-end", listener);
    return () => window.removeEventListener("design-drag-end", listener);
  }, [handleSceneDragEnd]);

  const onDoubleClickCapture = useCallback(
    (e: React.MouseEvent) => {
      if (toggleAccesslFullscreen) toggleAccesslFullscreen();
    },
    [toggleAccesslFullscreen],
  );
  const onPointerMissed = useCallback(
    (e: MouseEvent) => {
      if (!(e.ctrlKey || e.metaKey) && !e.shiftKey && deselectAll) deselectAll();
    },
    [deselectAll],
  );
  const onCameraChange = useCallback(
    (newCamera: Camera) => {
      if (setCamera) setCamera(newCamera);
    },
    [setCamera],
  );
  const onFocusComplete = useCallback(() => {
    setTimeout(() => {
      if (clearFocus) clearFocus();
    }, 100);
  }, [clearFocus]);

  return (
    <div ref={sceneDropZoneRef} data-drop-zone="scene" data-drop-zone-id={sceneId} className="h-full w-full">
      <SceneComponent
        showGizmo={true}
        camera={camera}
        onCameraChange={onCameraChange}
        onDoubleClickCapture={onDoubleClickCapture}
        onPointerMissed={onPointerMissed}
        focusedItemId={focusedPieceId}
        onFocusComplete={onFocusComplete}
        orthographic={projection === "orthographic"}
        projection={projection}
        onProjectionChange={setProjection}
        selectionOnDrag={selectionOnDrag}
      >
        <SceneContextBridge
          designScope={designScope}
          kitScope={kitScope}
          sketchpadScope={sketchpadScope}
          sketchpadActor={sketchpadActor}
          designAppScope={designAppScope}
          designAppActor={designAppActor}
          designFilterState={designFilterState}
          hoverIntentValue={hoverIntentValue}
          transactionPiecesValue={transactionPiecesValue}
          hoverPiecesValue={hoverPiecesValue}
        >
          <RepresentationDesign />
        </SceneContextBridge>
      </SceneComponent>
    </div>
  );
};

// #endregion 📍Scene

// #endregion ⚙️Canvas

// #region 🧿Windows
// Window components MUST wrap diagram and scene views with hover and transaction providers.

/** Props interface for the Design app root component.
 **/
export interface AppProps {}

/**
 * DesignDiagramWindow holds the data fields for a DesignDiagramWindow record.
 **/
const DesignDiagramWindow = memo<{ reactFlowInstanceRef: React.RefObject<ReactFlowInstance | null> }>(({ reactFlowInstanceRef }) => {
  return (
    <HoverIntentProvider>
      <TransactionPiecesProvider>
        <HoverPiecesProvider>
          <DesignDiagram reactFlowInstanceRef={reactFlowInstanceRef} />
        </HoverPiecesProvider>
      </TransactionPiecesProvider>
    </HoverIntentProvider>
  );
});
DesignDiagramWindow.displayName = "DesignDiagramWindow";

/**
 * SceneWindow holds the data fields for a SceneWindow record.
 **/
const SceneWindow = memo(() => {
  return (
    <HoverIntentProvider>
      <TransactionPiecesProvider>
        <HoverPiecesProvider>
          <DesignAppScene />
        </HoverPiecesProvider>
      </TransactionPiecesProvider>
    </HoverIntentProvider>
  );
});
SceneWindow.displayName = "SceneWindow";

// #endregion 🧿Windows

// #endregion 🪅Panels
// #region 🖲️App
// App MUST compose all Design app panels, canvas, toolbar, and footer into the main Design app layout.

/** App holds the data fields for a App record.
 **/
/**
 **/
const DesignWindowApp: FC<AppProps> = () => {
  useDesignAppInitialize();

  const { t } = useTranslation();
  const [transaction] = useDesignAppTransaction();
  const [deleteSelected] = useDesignAppDeleteSelected();
  const [undo] = useDesignAppUndo();
  const [redo] = useDesignAppRedo();
  const [addPiece] = useDesignAppAddPiece();
  const [selectAll] = useDesignAppSelectAll();
  const [deselectAll] = useDesignAppDeselectAll();
  const [toggleDiagramFullscreen] = useDesignAppToggleDiagramFullscreen();
  const [toggleAccesslFullscreen] = useDesignAppToggleAccesslFullscreen();
  const [togglePanel] = useDesignAppTogglePanel();
  const [, setActiveTool] = useDesignAppActiveTool();
  const [hoverTypes] = useDesignAppHoverTypes();
  const [hoverDesigns] = useDesignAppHoverDesigns();
  const [clearHover] = useDesignAppClearHover();
  const [activeTool] = useDesignAppActiveTool();

  const [selection] = useDesignAppSelection();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const kit = useKit(undefined, undefined, true) as Kit | null;
  const designFromScope = useDesign() as Design | null;
  const design = useMemo(() => {
    if (designFromScope) return designFromScope;
    if (!kit || !designScope) return undefined;
    return kit.designs?.find((entry) => entry.id === designScope.id);
  }, [designFromScope, kit, designScope?.id]);
  const kitId = kitScope?.id ?? kit?.id;
  const workbenchTypes = useKitTypes();
  const workbenchDesigns = useKitDesigns();
  const appSettings = useSketchpad((s) => s.settings?.apps) as any;
  const panelVisibility = useAppPanelVisibility();
  const { activeDraggedType, activeDraggedDesign, setActiveDraggedType, setActiveDraggedDesign } = useDragDrop();

  const reactFlowInstanceRef = useRef<ReactFlowInstance | null>(null);

  const store = useDesignStore() as DesignStore | null;
  const storedWindowLayout = useDesignApp((s) => s.windowLayout);

  const defaultLayout = useMemo(() => {
    return {
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "50%",
            content: [
              {
                type: "component",
                componentName: DesignAppWindowKind.Diagram,
                title: "diagram",
                componentState: {},
              },
            ],
          },
          {
            type: "stack",
            size: "50%",
            content: [
              {
                type: "component",
                componentName: DesignAppWindowKind.Scene,
                title: "scene",
                componentState: {},
              },
            ],
          },
        ],
      },
    };
  }, []);

  const windowLayout = useMemo(() => {
    if (!storedWindowLayout) {
      return defaultLayout;
    }
    const removeLegacySideTabsFromWindowLayout = (layoutNode: any): any => {
      if (!layoutNode || typeof layoutNode !== "object") return layoutNode;
      if (layoutNode.type === "component" && (layoutNode.componentName === "workbench" || layoutNode.componentName === DesignAppWindowKind.Settings || layoutNode.componentName === DesignAppWindowKind.Chat)) {
        return null;
      }
      if (layoutNode.root && typeof layoutNode.root === "object") {
        const root = removeLegacySideTabsFromWindowLayout(layoutNode.root);
        if (!root) return undefined;
        return { ...layoutNode, root };
      }
      if (Array.isArray(layoutNode.content)) {
        const content = layoutNode.content.map((item: any) => removeLegacySideTabsFromWindowLayout(item)).filter(Boolean);
        if (content.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, content };
      }
      if (Array.isArray(layoutNode.contentItems)) {
        const contentItems = layoutNode.contentItems.map((item: any) => removeLegacySideTabsFromWindowLayout(item)).filter(Boolean);
        if (contentItems.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, contentItems };
      }
      return layoutNode;
    };
    const sanitizedLayout = removeLegacySideTabsFromWindowLayout(storedWindowLayout);

    const hasWindowKind = (layout: any, windowKind: DesignAppWindowKind): boolean => {
      if (!layout) return false;

      if (layout.type === "component" && layout.componentName === windowKind) return true;

      if (layout.root && typeof layout.root === "object") {
        return hasWindowKind(layout.root, windowKind);
      }

      if (layout.content && Array.isArray(layout.content)) {
        return layout.content.some((item: any) => hasWindowKind(item, windowKind));
      }
      if (layout.contentItems && Array.isArray(layout.contentItems)) {
        return layout.contentItems.some((item: any) => hasWindowKind(item, windowKind));
      }

      return false;
    };

    const hasScene = hasWindowKind(sanitizedLayout, DesignAppWindowKind.Scene);
    const hasDiagram = hasWindowKind(sanitizedLayout, DesignAppWindowKind.Diagram);
    if (!hasScene || !hasDiagram) {
      return defaultLayout;
    }

    return sanitizedLayout;
  }, [defaultLayout, storedWindowLayout]);

  const storedWindowLayoutHash = useMemo(() => (storedWindowLayout === undefined ? "__undefined__" : JSON.stringify(storedWindowLayout)), [storedWindowLayout]);
  const windowLayoutHash = useMemo(() => (windowLayout === undefined ? "__undefined__" : JSON.stringify(windowLayout)), [windowLayout]);

  useEffect(() => {
    if (!store || !storedWindowLayout) return;
    if (windowLayout === undefined) {
      try {
        store.change({ windowLayout: undefined });
      } catch (error) {
        console.error("[DesignApp] Failed to clear layout:", error);
      }
      return;
    }
    if (windowLayoutHash !== storedWindowLayoutHash) {
      try {
        store.change({ windowLayout });
      } catch (error) {
        console.error("[DesignApp] Failed to migrate layout:", error);
      }
    }
  }, [store, storedWindowLayout, storedWindowLayoutHash, windowLayout, windowLayoutHash]);

  const windowConfig: AppWindowConfig = useMemo(() => {
    return {
      defaultLayout,
      windowKinds: [
        {
          id: DesignAppWindowKind.Diagram,
          label: "diagram",
          component: (props: any) => <DesignDiagramWindow reactFlowInstanceRef={reactFlowInstanceRef} />,
        },
        {
          id: DesignAppWindowKind.Scene,
          label: "scene",
          component: (props: any) => <SceneWindow />,
        },
      ],
    };
  }, [defaultLayout, reactFlowInstanceRef]);

  const handleLayoutChange = useCallback(
    (config: any) => {
      if (store && typeof store.change === "function") {
        store.change({ windowLayout: config });
      }
    },
    [store],
  );

  const addSection = useAddPanelSection();
  const addSidePanelTab = useAddSidePanelTab();
  const removeSection = useRemovePanelSection();
  const removeSidePanelTab = useRemoveSidePanelTab();
  const kitAppCommands = useKitAppCommands();
  const sketchpadCommands = useSketchpadCommands();
  const { navigateToType, navigateToDesign, navigateToKit } = sketchpadCommands;
  const designDetailsKey = useMemo(
    () =>
      JSON.stringify({
        designId: design?.id ?? null,
        pieceIds: (design?.pieces ?? []).map((entry) => entry.id),
        connectionIds: (design?.connections ?? []).map((entry) => entry.id),
        includedDesignIds: getIncludedDesigns(design || ({} as Design)).map((entry) => entry.id),
        selectionPieces: (selection.pieces ?? []).map((entry) => resolveSelectionEntryId(entry) ?? entry),
        selectionConnections: (selection.connections ?? []).map((entry) => resolveSelectionEntryId(entry) ?? entry),
        selectionConnector: selection.connector ?? null,
        selectionConnectors: selection.connectors ?? [],
        kitId,
      }),
    [design, selection, kitId],
  );

  useHotkeys(
    "ctrl+a",
    () => {
      if (selectAll) selectAll();
    },
    { enableOnFormTags: true },
  );
  useHotkeys(
    "ctrl+d",
    () => {
      if (deselectAll) deselectAll();
    },
    { enableOnFormTags: true },
  );
  useHotkeys("delete,backspace", () => deleteSelected?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+z", () => undo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+y", () => redo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+shift+z", () => redo?.(), { enableOnFormTags: true });

  const appType = useAppType();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!setActiveTool || !isSelectionToolKind(activeTool)) return;
      const nextToolKind = toSelectionToolKind(
        resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
          shiftKey: e.shiftKey,
          altKey: e.altKey,
          ctrlKey: e.ctrlKey,
          metaKey: e.metaKey,
        }),
      );
      if (nextToolKind !== ToolKind.SELECTION_NORMAL && nextToolKind !== activeTool) setActiveTool(nextToolKind);
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (!setActiveTool || !isSelectionToolKind(activeTool)) return;
      const nextToolKind = toSelectionToolKind(
        resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
          shiftKey: e.shiftKey,
          altKey: e.altKey,
          ctrlKey: e.ctrlKey,
          metaKey: e.metaKey,
        }),
      );
      if (nextToolKind === ToolKind.SELECTION_NORMAL && activeTool !== ToolKind.SELECTION_NORMAL) setActiveTool(ToolKind.SELECTION_NORMAL);
      if (nextToolKind !== ToolKind.SELECTION_NORMAL && nextToolKind !== activeTool) setActiveTool(nextToolKind);
    };
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, [activeTool, setActiveTool]);

  useEffect(() => {
    const detailDesignId = design?.id;

    const selectionPieceEntries = (selection.pieces || []) as any[];
    const selectionConnectionEntries = (selection.connections || []) as any[];
    const designConnections = design?.connections || [];
    const knownPieceIds = [...new Set([...(design?.pieces || []).map((entry) => entry.id), ...getIncludedDesigns(design || ({} as Design)).map((entry) => entry.id)])];
    const knownConnectionIds = new Set(designConnections.map((entry) => entry.id));
    const selectedPieceIds = selectionPieceEntries.map((entry) => resolveSelectionEntryIdByKnownIds(entry, knownPieceIds)).filter((entry): entry is Id => typeof entry === "string" && entry.length > 0);
    const knownPieceIds = new Set(knownPieceIds);
    const selectedKnownPieceIds = selectedPieceIds.filter((id) => knownPieceIds.has(id));
    const selectedConnectionIds = selectionConnectionEntries.map((entry) => resolveSelectionEntryId(entry)).filter((entry): entry is Id => typeof entry === "string" && entry.length > 0 && knownConnectionIds.has(entry));
    const selectedConnectionIds = selectionConnectionEntries.filter((entry) => {
      if (typeof entry !== "object" || entry === null) return false;
      const resolvedId = resolveSelectionEntryId(entry);
      return resolvedId === undefined;
    }) as ConnectionId[];
    const idConnections = designConnections.filter((connection) => selectedConnectionIds.includes(connection.id));
    const idConnections = designConnections.filter((connection) => selectedConnectionIds.some((connectionId) => areSameConnection(connection, connectionId as any)));
    const selectedConnections = [...idConnections, ...idConnections.filter((connection) => !idConnections.some((idConnection) => idConnection.id === connection.id))];
    const primaryConnector = selection.connector ?? selection.connectors?.[0];
    const hasPieces = selectedKnownPieceIds.length > 0;
    const hasConnections = selectedConnections.length > 0;
    const hasPortSelected = primaryConnector !== undefined;
    const hasSelection = hasPieces || hasConnections || hasPortSelected;

    const pieceSingleId = "semio.sketchpad.app.design.panel.details.section.piece.properties";
    const pieceMultipleId = "semio.sketchpad.app.design.panel.details.section.piece.multipleTitle";
    const connectionSingleId = "semio.sketchpad.app.design.panel.details.section.connection.properties";
    const connectionMultipleId = "semio.sketchpad.app.design.panel.details.section.connection.multipleTitle";
    const selectionMultipleId = "semio.sketchpad.app.design.panel.details.section.selection.multipleTitle";

    removeSection("details", "semio.sketchpad.app.design.properties");
    removeSection("details", "semio.sketchpad.app.type.connector.properties");
    removeSection("details", pieceSingleId);
    removeSection("details", pieceMultipleId);
    removeSection("details", connectionSingleId);
    removeSection("details", connectionMultipleId);
    removeSection("details", selectionMultipleId);
    removeSection("details", "semio.sketchpad.app.kit.properties");

    if (!hasSelection) {
      addSection("details", {
        id: "semio.sketchpad.app.design.properties",
        specificity: 20,
        order: 50,
        defaultOpen: true,
        content: () =>
          detailDesignId && kitId ? (
            <KitScopeProvider id={kitId}>
              <DesignScopeProvider id={detailDesignId}>
                <DesignSection />
              </DesignScopeProvider>
            </KitScopeProvider>
          ) : null,
      });
    } else if (hasPortSelected) {
      const connectorPieceId = primaryConnector!.piece;
      const connectorId = primaryConnector!.connector;
      addSection("details", {
        id: "semio.sketchpad.app.type.connector.properties",
        specificity: 30,
        order: 0,
        defaultOpen: true,
        content: () =>
          detailDesignId && kitId ? (
            <KitScopeProvider id={kitId}>
              <DesignScopeProvider id={detailDesignId}>
                <ConnectorSection pieceId={connectorPieceId} connectorId={connectorId} />
              </DesignScopeProvider>
            </KitScopeProvider>
          ) : null,
      });
      addSection("details", {
        id: "semio.sketchpad.app.design.properties",
        specificity: 20,
        order: 50,
        defaultOpen: true,
        content: () =>
          detailDesignId && kitId ? (
            <KitScopeProvider id={kitId}>
              <DesignScopeProvider id={detailDesignId}>
                <DesignSection />
              </DesignScopeProvider>
            </KitScopeProvider>
          ) : null,
      });
    } else {
      if (hasPieces) {
        const piecesCount = selectedKnownPieceIds.length;
        const piecesSectionId = piecesCount === 1 ? pieceSingleId : pieceMultipleId;
        addSection("details", {
          id: piecesSectionId,
          specificity: 30,
          order: 0,
          defaultOpen: true,
          content: () =>
            detailDesignId && kitId ? (
              <KitScopeProvider id={kitId}>
                <DesignScopeProvider id={detailDesignId}>
                  <PiecesSection />
                </DesignScopeProvider>
              </KitScopeProvider>
            ) : null,
        });
      }
      if (hasConnections) {
        const connectionsSectionId = selectedConnections.length === 1 ? connectionSingleId : connectionMultipleId;
        addSection("details", {
          id: connectionsSectionId,
          specificity: 30,
          order: 10,
          defaultOpen: true,
          content: () =>
            detailDesignId && kitId ? (
              <KitScopeProvider id={kitId}>
                <DesignScopeProvider id={detailDesignId}>
                  <ConnectionsSection connections={selectedConnections} isSingle={selectedConnections.length === 1} count={selectedConnections.length} />
                </DesignScopeProvider>
              </KitScopeProvider>
            ) : null,
        });
      }
      if (hasPieces && hasConnections) {
        addSection("details", {
          id: selectionMultipleId,
          specificity: 30,
          order: 20,
          content: () => (
            <HelperRow propertyAligned>
              <p className="text-sm text-muted-foreground">{useLabel("semio.sketchpad.app.design.selectOnlyPiecesOrConnections")}</p>
            </HelperRow>
          ),
        });
      }
      addSection("details", {
        id: "semio.sketchpad.app.design.properties",
        specificity: 20,
        order: 50,
        defaultOpen: true,
        content: () =>
          detailDesignId && kitId ? (
            <KitScopeProvider id={kitId}>
              <DesignScopeProvider id={detailDesignId}>
                <DesignSection />
              </DesignScopeProvider>
            </KitScopeProvider>
          ) : null,
      });
    }

    addSection("details", {
      id: "semio.sketchpad.app.kit.properties",
      specificity: 10,
      order: 100,
      content: () =>
        kitId ? (
          <React.Suspense fallback={null}>
            <KitScopeProvider id={kitId}>
              <KitSectionLazy />
            </KitScopeProvider>
          </React.Suspense>
        ) : null,
    });

    return () => {
      removeSection("details", "semio.sketchpad.app.design.properties");
      removeSection("details", "semio.sketchpad.app.type.connector.properties");
      removeSection("details", pieceSingleId);
      removeSection("details", pieceMultipleId);
      removeSection("details", connectionSingleId);
      removeSection("details", connectionMultipleId);
      removeSection("details", selectionMultipleId);
      removeSection("details", "semio.sketchpad.app.kit.properties");
    };
  }, [designDetailsKey, addSection, removeSection, kitId]);

  useEffect(() => {
    addSection("workbench", {
      id: "semio.sketchpad.app.kit.pieces",
      specificity: 20,
      order: 1,
      content: () => <PiecesWorkbenchContent />,
    });
    addSection("tools", {
      id: "semio.sketchpad.app.design.windows",
      specificity: 20,
      order: 2,
      content: () => <WindowLibrary />,
    });
    return () => {
      removeSection("workbench", "semio.sketchpad.app.kit.pieces");
      removeSection("tools", "semio.sketchpad.app.design.windows");
    };
  }, [addSection, removeSection]);

  const PiecesWorkbenchContent: FC = () => {
    const kit = useKit() as Kit;
    const resolveParentId = (parent: any): string | undefined => (typeof parent === "string" ? parent : parent?.id);

    const handleCreateTypeChild = (parentType: Type) => {
      const existingChildren = workbenchTypes?.filter((type) => resolveParentId(type.parent) === parentType.id) || [];
      const uniqueName = generateUniqueName(parentType.name, [parentType.name, ...existingChildren.map((type) => type.name)]);
      const newType: Type = {
        id: id(),
        name: uniqueName,
        parent: { id: parentType.id },
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      kitAppCommands.addType(newType);
    };

    const handleCreateDesignChild = (parentDesign: Design) => {
      const existingChildren = workbenchDesigns?.filter((design) => resolveParentId(design.parent) === parentDesign.id) || [];
      const uniqueName = generateUniqueName(parentDesign.name, [parentDesign.name, ...existingChildren.map((design) => design.name)]);
      const newDesign: Design = {
        id: id(),
        name: uniqueName,
        parent: { id: parentDesign.id },
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      kitAppCommands.addDesign(newDesign);
      if (kitId) navigateToDesign(kitId, newDesign.id);
    };

    const renderTypeTree = (types: Type[]): ReactNode[] => {
      return types.map((type) => {
        const children = workbenchTypes?.filter((item) => resolveParentId(item.parent) === type.id) || [];
        return (
          <div
            key={type.id}
            onPointerEnter={() => {
              if (hoverTypes) hoverTypes([type.id]);
            }}
            onPointerLeave={() => {
              if (clearHover) clearHover();
            }}
          >
            <TypeTreeItem type={type} onCreateChild={handleCreateTypeChild}>
              {children.length > 0 && renderTypeTree(children)}
            </TypeTreeItem>
          </div>
        );
      });
    };

    const renderDesignTree = (designs: Design[]): ReactNode[] => {
      return designs.map((workbenchDesign) => {
        const children = workbenchDesigns?.filter((child) => resolveParentId(child.parent) === workbenchDesign.id) || [];

        const isDisabled = design && kit ? areDesignsInSameFamily(kit, design.id, workbenchDesign.id) : false;
        return (
          <div
            key={workbenchDesign.id}
            onPointerEnter={() => {
              if (hoverDesigns) hoverDesigns([workbenchDesign.id]);
            }}
            onPointerLeave={() => {
              if (clearHover) clearHover();
            }}
          >
            <DesignTreeItem design={workbenchDesign} onCreateChild={handleCreateDesignChild} disabled={isDisabled}>
              {children.length > 0 && renderDesignTree(children)}
            </DesignTreeItem>
          </div>
        );
      });
    };

    const rootTypes = workbenchTypes?.filter((type) => !resolveParentId(type.parent)) || [];
    const rootDesigns = workbenchDesigns?.filter((design) => !resolveParentId(design.parent)) || [];

    const handleCreateType = () => {
      const existingTypes = workbenchTypes || [];
      const typeNumber = existingTypes.length + 1;
      const newType: Type = {
        id: id(),
        name: `Type ${typeNumber}`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      kitAppCommands.addType(newType);
      if (kitId) navigateToType(kitId, newType.id);
    };

    const handleCreateDesign = () => {
      const existingDesigns = workbenchDesigns || [];
      const designNumber = existingDesigns.length + 1;
      const newDesign: Design = {
        id: id(),
        name: `Design ${designNumber}`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      kitAppCommands.addDesign(newDesign);
      if (kitId) navigateToDesign(kitId, newDesign.id);
    };

    return (
      <>
        <div
          onPointerEnter={() => {
            if (!workbenchTypes || workbenchTypes.length === 0) return;
            if (hoverTypes) hoverTypes(workbenchTypes.map((type) => type.id));
          }}
          onPointerLeave={() => {
            if (clearHover) clearHover();
          }}
        >
          <TreeItem
            id="semio.sketchpad.app.kit.types"
            actions={[
              {
                id: "semio.sketchpad.common.addType",
                icon: <AddIcon size={12} />,
                onClick: handleCreateType,
              },
            ]}
            onDoubleClick={() => {
              if (!kitId) return;
              navigateToKit(kitId, "kind=types");
            }}
          >
            {renderTypeTree(rootTypes)}
          </TreeItem>
        </div>
        <div
          onPointerEnter={() => {
            if (!workbenchDesigns || workbenchDesigns.length === 0) return;
            if (hoverDesigns) hoverDesigns(workbenchDesigns.map((design) => design.id));
          }}
          onPointerLeave={() => {
            if (clearHover) clearHover();
          }}
        >
          <TreeItem
            id="semio.sketchpad.app.kit.designs"
            actions={[
              {
                id: "semio.sketchpad.common.addDesign",
                icon: <AddIcon size={12} />,
                onClick: handleCreateDesign,
              },
            ]}
            onDoubleClick={() => {
              if (!kitId) return;
              navigateToKit(kitId, "kind=designs");
            }}
          >
            {renderDesignTree(rootDesigns)}
          </TreeItem>
        </div>
      </>
    );
  };

  const TypeTreeItem: FC<{ type: Type; onCreateChild: (type: Type) => void; children?: ReactNode }> = ({ type, onCreateChild, children }) => {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
      id: `type-${type.id}`,
      data: { type: "type", typeId: type.id },
    });

    const handleDragStart = () => {
      setActiveDraggedType(type);
    };

    useEffect(() => {
      if (isDragging) {
        handleDragStart();
      }
    }, [isDragging]);

    return (
      <TreeItem
        label={
          <div className="flex items-center gap-double min-w-0">
            <DraggableAvatar
              ref={setNodeRef}
              dragRef={setNodeRef}
              dragListeners={listeners}
              dragAttributes={attributes}
              content={type.name.substring(0, 2).toUpperCase()}
              isSelected={false}
              isHovered={false}
              shouldFade={isDragging}
              title={type.name}
              avatarClassName="size-workbench"
              dataDragKind="type"
              dataDragId={type.id}
            />
            <span className="truncate">{type.name}</span>
          </div>
        }
        onDoubleClick={(event) => {
          if ((event.target as HTMLElement).closest('[data-slot="action"]') || (event.target as HTMLElement).closest('[data-slot="avatar"]')) {
            return;
          }
          event.preventDefault();
          event.stopPropagation();
          if (kitId) navigateToType(kitId, type.id);
        }}
        actions={
          type.isAbstract
            ? []
            : [
                {
                  icon: <AddIcon size={12} />,
                  onClick: () => {
                    const center = { u: 6, v: -7 };
                    const plane: Plane = { origin: { x: 0, y: 0, z: 0 }, xAxis: { x: 1, y: 0, z: 0 }, yAxis: { x: 0, y: 1, z: 0 } };
                    transaction?.start();
                    addPiece?.({ id: id(), type: { id: type.id }, center, plane });
                    transaction?.finalize();
                  },
                  id: "semio.sketchpad.app.design.panel.workbench.types.addPiece",
                },
                {
                  icon: <CopyIcon size={12} />,
                  onClick: () => {
                    const newType: Type = {
                      ...type,
                      id: id(),
                      name: `${type.name} Copy`,
                      createdAt: new Date().toISOString(),
                      updatedAt: new Date().toISOString(),
                    };
                    kitAppCommands.addType(newType);
                  },
                  id: "semio.sketchpad.app.design.panel.workbench.types.duplicateType",
                },
              ]
        }
      >
        {children}
      </TreeItem>
    );
  };

  const DesignTreeItem: FC<{ design: Design; onCreateChild: (design: Design) => void; disabled?: boolean; children?: ReactNode }> = ({ design, onCreateChild, disabled, children }) => {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
      id: `design-${design.id}`,
      data: { type: "design", designId: design.id },
      disabled: disabled,
    });

    const handleDragStart = () => {
      if (!disabled) {
        setActiveDraggedDesign(design);
      }
    };

    useEffect(() => {
      if (isDragging && !disabled) {
        handleDragStart();
      }
    }, [isDragging, disabled]);

    return (
      <TreeItem
        label={
          <div className={`flex items-center gap-double min-w-0 ${disabled ? "opacity-50 cursor-not-allowed" : ""}`}>
            <DraggableAvatar
              ref={setNodeRef}
              dragRef={setNodeRef}
              dragListeners={disabled ? {} : listeners}
              dragAttributes={disabled ? {} : attributes}
              content={design.name.substring(0, 2).toUpperCase()}
              isSelected={false}
              isHovered={false}
              shouldFade={isDragging}
              title={disabled ? `${design.name} (same design family - cannot be used as design piece)` : design.name}
              avatarClassName="size-workbench"
              dataDragKind="design"
              dataDragId={design.id}
            />
            <span className="truncate">{design.name}</span>
          </div>
        }
        onDoubleClick={(event) => {
          if ((event.target as HTMLElement).closest('[data-slot="action"]') || (event.target as HTMLElement).closest('[data-slot="avatar"]')) {
            return;
          }
          event.preventDefault();
          event.stopPropagation();
          if (kitId) navigateToDesign(kitId, design.id);
        }}
        actions={[
          {
            icon: <AddIcon size={12} />,
            onClick: () => {
              if (disabled) return;
              const pieceId = id();
              const center = { u: 6, v: -7 };
              const plane: Plane = { origin: { x: 0, y: 0, z: 0 }, xAxis: { x: 1, y: 0, z: 0 }, yAxis: { x: 0, y: 1, z: 0 } };
              transaction?.start();
              addPiece?.({ id: pieceId, id_: pieceId, design: { id: design.id }, center, plane });
              transaction?.finalize();
            },
            id: "semio.sketchpad.app.design.panel.workbench.designs.addPiece",
          },
          {
            icon: <AddIcon size={12} />,
            onClick: () => onCreateChild(design),
            id: "semio.sketchpad.common.addChild",
          },
        ]}
      >
        {children}
      </TreeItem>
    );
  };

  return (
    <ReactFlowProvider>
      <Canvas id="semio.sketchpad.app.design.canvas">
        <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
      </Canvas>
      <DesignAppFooter />
    </ReactFlowProvider>
  );
};

// #region 🎡Settings

const DesignSettingsContent: FC = () => {
  const [theme, setTheme, canSetTheme] = useTheme();
  const [language, setLanguage, canSetLanguage] = useLanguage();
  const [device, setDevice, canSetDevice] = useDevice();
  const [expertise, setExpertise, canSetExpertise] = useExpertise();
  const [mode, setMode, canSetMode] = useMode();
  const [panelVisibility, setPanelVisibility, canSetPanelVisibility] = useDesignAppPanelVisibility();

  const languageEnLabel = useLabel("semio.sketchpad.settings.language.en");
  const languageDeLabel = useLabel("semio.sketchpad.settings.language.de");
  const languagePlaceholder = useLabel("semio.sketchpad.app.home.settings.language.placeholder");
  const showToolbarLabel = useLabel("semio.sketchpad.navbar.panelToggle.toolbar.show");
  const showWorkbenchLabel = useLabel("semio.sketchpad.navbar.panelToggle.workbench.show");
  const showDetailsLabel = useLabel("semio.sketchpad.navbar.panelToggle.details.show");
  const showWindowsLabel = useLabel("semio.sketchpad.navbar.panelToggle.tools.show");
  const togglePanelVisibility = useCallback(
    (panelKey: "toolbar" | "leftSidePanel" | "rightSidePanel" | "details") => {
      if (!canSetPanelVisibility || !setPanelVisibility) return;
      setPanelVisibility({ ...panelVisibility, [panelKey]: !panelVisibility[panelKey] });
    },
    [canSetPanelVisibility, panelVisibility, setPanelVisibility],
  );
  return (
    <>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.design.settings.theme"
          value={theme}
          onValueChange={(value: string) => setTheme?.(value as Theme)}
          showLabel
          kind="single"
          disabled={!canSetTheme}
          items={[
            { value: Theme.SYSTEM, id: "semio.sketchpad.settings.theme.system", icon: <MonitorIcon className="size-small" /> },
            { value: Theme.LIGHT, id: "semio.sketchpad.settings.theme.light", icon: <SunIcon className="size-small" /> },
            { value: Theme.DARK, id: "semio.sketchpad.settings.theme.dark", icon: <MoonIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <Select id="semio.sketchpad.app.design.settings.language" value={language || "en"} onValueChange={(value: string) => setLanguage?.(value)} showLabel disabled={!canSetLanguage}>
          <SelectTrigger>
            <SelectValue placeholder={languagePlaceholder} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="en">{languageEnLabel}</SelectItem>
            <SelectItem value="de">{languageDeLabel}</SelectItem>
          </SelectContent>
        </Select>
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.design.settings.device"
          value={typeof device === "object" ? "desktop" : device}
          onValueChange={(value: string) => setDevice?.(value as "desktop" | "tablet")}
          showLabel
          kind="single"
          disabled={!canSetDevice}
          items={[
            { value: "desktop", id: "semio.sketchpad.settings.device.desktop", icon: <MousePointerIcon className="size-small" /> },
            { value: "tablet", id: "semio.sketchpad.settings.device.tablet", icon: <HandIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.design.settings.expertise"
          value={expertise}
          onValueChange={(value: string) => setExpertise?.(value as Expertise)}
          showLabel
          kind="single"
          disabled={!canSetExpertise}
          items={[
            { value: Expertise.BEGINNER, id: "semio.sketchpad.settings.expertise.beginner", icon: <TutorialIcon className="size-small" /> },
            { value: Expertise.NORMAL, id: "semio.sketchpad.settings.expertise.normal", icon: <UserIcon className="size-small" /> },
            { value: Expertise.EXPERT, id: "semio.sketchpad.settings.expertise.expert", icon: <AwardIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.design.settings.mode"
          value={mode}
          onValueChange={(value: string) => setMode?.(value as Mode)}
          showLabel
          kind="single"
          disabled={!canSetMode}
          items={[
            { value: Mode.USER, id: "semio.sketchpad.settings.mode.user", icon: <UserIcon className="size-small" /> },
            { value: Mode.DEV, id: "semio.sketchpad.settings.mode.dev", icon: <CodeIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <Toggle id="semio.sketchpad.app.design.settings.panel.toolbar" pressed={!!panelVisibility.toolbar} onPressedChange={() => togglePanelVisibility("toolbar")} text={showToolbarLabel} disabled={!canSetPanelVisibility} />
      </TreeRow>
      <TreeRow>
        <Toggle id="semio.sketchpad.app.design.settings.panel.workbench" pressed={!!panelVisibility.leftSidePanel} onPressedChange={() => togglePanelVisibility("leftSidePanel")} text={showWorkbenchLabel} disabled={!canSetPanelVisibility} />
      </TreeRow>
      <TreeRow>
        <Toggle id="semio.sketchpad.app.design.settings.panel.windows" pressed={!!panelVisibility.rightSidePanel} onPressedChange={() => togglePanelVisibility("rightSidePanel")} text={showWindowsLabel} disabled={!canSetPanelVisibility} />
      </TreeRow>
      <TreeRow>
        <Toggle id="semio.sketchpad.app.design.settings.panel.details" pressed={!!panelVisibility.details} onPressedChange={() => togglePanelVisibility("details")} text={showDetailsLabel} disabled={!canSetPanelVisibility} />
      </TreeRow>
    </>
  );
};

const DesignApp: FC = () => {
  initializeDesignStore();

  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();

  useEffect(() => {
    addSection("toolbar", {
      id: "semio.sketchpad.app.design.toolbar.history",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "history",
        labelId: "semio.sketchpad.toolbar.parent.actions",
        order: 5,
      },
      content: <DesignHistorySettings />,
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.design.tools.select",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "selection",
        labelId: "semio.sketchpad.toolbar.parent.selection",
        order: 10,
      },
      content: <DesignSelectSettings />,
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.design.toolbar.filters",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "filter",
        labelId: "semio.sketchpad.toolbar.parent.filter",
        order: 20,
      },
      content: <DesignToolbarFilters />,
    });

    return () => {
      removeSection("toolbar", "semio.sketchpad.app.design.toolbar.history");
      removeSection("toolbar", "semio.sketchpad.app.design.tools.select");
      removeSection("toolbar", "semio.sketchpad.app.design.toolbar.filters");
    };
  }, [addSection, removeSection]);

  return (
    <DesignFilterProvider>
      <DesignAppTransactionProvider>
        <DesignWindowApp />
      </DesignAppTransactionProvider>
    </DesignFilterProvider>
  );
};

// #endregion 🎡App

// #region ⏱️Config
// Config MUST export the Design app configuration with route segments, panel definitions, and path matching.

/**
 * Exported Design app configuration including routes, panels, and path matching.
 **/
export const designConfig: AppConfig = {
  id: "design",
  component: DesignApp,
  routeSegments: [
    {
      path: "kits/:kit",
      paramName: "kit",
      scopeProvider: KitScopeProvider,
    },
    {
      path: "designs/:design",
      paramName: "design",
      scopeProvider: DesignScopeProvider,
    },
  ],
  getPanels: (): PanelDefinition[] => [
    createPanelDefinition(PanelKind.WORKBENCH, "semio.sketchpad.navbar.panelToggle.workbench.show"),
    createPanelDefinition(PanelKind.TOOLS, "semio.sketchpad.navbar.panelToggle.tools.show"),
    createPanelDefinition(PanelKind.TOOLBAR, "semio.sketchpad.navbar.panelToggle.toolbar.show"),
    createPanelDefinition(PanelKind.STATS, "semio.sketchpad.navbar.panelToggle.stats.show"),
    createPanelDefinition(PanelKind.DETAILS, "semio.sketchpad.navbar.panelToggle.details.show"),
  ],
  matchesPath: (pathParts: string[]) => {
    const isUuidPattern = (str: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str);
    return pathParts.length === 4 && pathParts[0] === "kits" && isUuidPattern(pathParts[1]) && pathParts[2] === "designs" && isUuidPattern(pathParts[3]);
  },
  order: 20,
};

// #endregion ⏱️Config

