/**
 * Selects a single connector replacing the current selection.
 *MUST clear representation selection when selecting a connector.
 **/
export function useTypeAppSelectConnector(): ActionHookResult<[connectorId: string]> {
  const [, setSelection, canSetSelection] = useTypeAppSelection();
  const [selection] = useTypeAppSelection();
  const action = useMemo(() => {
    if (!canSetSelection || !setSelection) return undefined;
    return (connectorId: string) => setSelection({ ...selection, connectors: [connectorId], representations: [] });
  }, [setSelection, canSetSelection, selection]);
  return [action, canSetSelection];
}

/**
 * Removes a connector from the current selection.
 *MUST filter the connector ID from the selection array.
 **/
export function useTypeAppDeselectConnector(): ActionHookResult<[connectorId: string]> {
  const [, setSelection, canSetSelection] = useTypeAppSelection();
  const [selection] = useTypeAppSelection();
  const action = useMemo(() => {
    if (!canSetSelection || !setSelection) return undefined;
    return (connectorId: string) => {
      const currentConnectors = selection?.connectors ?? [];
      setSelection({ ...selection, connectors: currentConnectors.filter((p) => p !== connectorId) });
    };
  }, [setSelection, canSetSelection, selection]);
  return [action, canSetSelection];
}

