// #region 🖥️DropZone
// DropZone component MUST handle drag-and-drop kit imports.

/** HomeDropZone holds the data fields for a HomeDropZone record.
 **/
/**
 **/
const HomeDropZone: FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isDragging, setIsDragging] = useState(false);
  const { t } = useTranslation();
  const { createKit, navigateToKit, storeKitFileBlobs } = useSketchpadCommands();
  const actor = useSketchpadActor();

  const startKitImport = (operationId: string, kitName: string) => {
    actor.send({ type: "BACKGROUND.START", operationId, operationType: `kit-import:${kitName}` });
  };

  const completeKitImport = (operationId: string) => {
    actor.send({ type: "BACKGROUND.COMPLETE", operationId });
  };

  const failKitImport = (operationId: string, error: string) => {
    actor.send({ type: "BACKGROUND.FAIL", operationId, error });
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      const hasZip = Array.from(e.dataTransfer.items).some((item) => item.kind === "file" && (item.type === "application/zip" || item.type === "application/x-zip-compressed"));
      if (hasZip) {
        setIsDragging(true);
      }
    }
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.currentTarget === e.target) {
      setIsDragging(false);
    }
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const files = Array.from(e.dataTransfer.files);
    const zipFile = files.find((f) => f.name.endsWith(".zip") || f.name.endsWith(".semio.zip"));

    if (zipFile) {
      const operationId = `kit-import-${id()}`;
      const kitName = zipFile.name.replace(/\.(semio\.)?zip$/, "");
      startKitImport(operationId, kitName);

      await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      try {
        const { kit } = await importKit(zipFile);
        await createKit("semio.sketchpad.app.home.dropzone", kit, false, false);

        await storeKitFileBlobs(kit.id, kit);
        completeKitImport(operationId);
      } catch (error) {
        console.error("[Home] Failed to import kit:", error);
        failKitImport(operationId, error instanceof Error ? error.message : String(error));
      }
    }
  };

  const handleFileInputChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.name.endsWith(".zip") || file.name.endsWith(".semio.zip")) {
      const operationId = `kit-import-${id()}`;
      const kitName = file.name.replace(/\.(semio\.)?zip$/, "");
      startKitImport(operationId, kitName);

      await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      try {
        const { kit } = await importKit(file);
        await createKit("semio.sketchpad.app.home.fileInput", kit, false, false);

        await storeKitFileBlobs(kit.id, kit);
        completeKitImport(operationId);
        // Don't auto-navigate - let user click the now-enabled row
      } catch (error) {
        console.error("[Home] Failed to import kit:", error);
        failKitImport(operationId, error instanceof Error ? error.message : String(error));
      }
    }
    e.target.value = "";
  };

  return (
    <div className="relative h-full w-full" onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}>
      <Input id="semio.sketchpad.app.home.importKit" type="file" accept=".zip,.semio.zip,application/zip,application/x-zip-compressed" className="hidden" onChange={handleFileInputChange} />
      {children}
      {isDragging && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-base/80 backdrop-blur-sm">
          <div className="flex flex-col items-center gap-2 text-center">
            <DocumentIcon className="h-12 w-12 text-muted-foreground" />
            <p className="text-lg font-medium">{t("semio.sketchpad.app.home.dropzone.label.normal")}</p>
            <p className="text-sm text-muted-foreground">{t("semio.sketchpad.app.home.dropzone.description.normal")}</p>
          </div>
        </div>
      )}
    </div>
  );
};

// #endregion 🖥️DropZone

// #region 🖲️App
// App components MUST compose the Home app toolbar, table, and logic.

/**
 * KitKind holds the data fields for a KitKind record.
 **/
type KitKind = "temporary" | "file" | "folder" | "remote";
/**
 * HomeToolbarFilters holds the data fields for a HomeToolbarFilters record.
 **/
const HomeToolbarFilters: FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const availableKitKinds = useAvailableKitKinds();
  const selectedKind = searchParams.get("kind") as KitKind | null;

  const toggleKind = (type: KitKind) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedKind === type) {
      newParams.delete("kind");
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("kind", type);
      newParams.delete("name");
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  const labelTemporary = useLabel("semio.sketchpad.app.home.toolbar.showTemporary");
  const labelFile = useLabel("semio.sketchpad.app.home.toolbar.showFile");
  const labelFolder = useLabel("semio.sketchpad.app.home.toolbar.showFolder");
  const labelRemote = useLabel("semio.sketchpad.app.home.toolbar.showRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.temporary && <Toggle pressed={selectedKind === "temporary"} onPressedChange={() => toggleKind("temporary")} id="semio.sketchpad.app.home.toolbar.showTemporary" icon={<TemporaryKitIcon />} text={labelTemporary} />}
      {availableKitKinds.file && <Toggle pressed={selectedKind === "file"} onPressedChange={() => toggleKind("file")} id="semio.sketchpad.app.home.toolbar.showFile" icon={<DocumentIcon />} text={labelFile} />}
      {availableKitKinds.folder && <Toggle pressed={selectedKind === "folder"} onPressedChange={() => toggleKind("folder")} id="semio.sketchpad.app.home.toolbar.showFolder" icon={<FolderIcon />} text={labelFolder} />}
      {availableKitKinds.remote && <Toggle pressed={selectedKind === "remote"} onPressedChange={() => toggleKind("remote")} id="semio.sketchpad.app.home.toolbar.showRemote" icon={<RemoteKitIcon />} text={labelRemote} />}
    </ToolbarGroup>
  );
};
/**
 * HomeToolbarCreate holds the data fields for a HomeToolbarCreate record.
 **/
const HomeToolbarCreate: FC = () => {
  const kits = useKits();
  const availableKitKinds = useAvailableKitKinds();
  const defaultKitName = useLabel("semio.sketchpad.app.kit.defaultName");
  const { createKit, navigateToKit } = useSketchpadCommands();

  const handleCreateKit = useCallback(
    async (type: KitKind) => {
      const existingNames = kits.map((kit) => kit.name);
      const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames) ?? defaultKitName ?? "";
      const newKit: Kit = {
        id: id(),
        name: uniqueName,
        version: "",
        types: [],
        designs: [],
      };
      try {
        const result = await createKit("semio.sketchpad.app.home.toolbar.createKit", newKit, type);
        const registeredId = result?.kitId ?? newKit.id;
        navigateToKit(registeredId);
      } catch (error) {
        console.error("[Home] Failed to create kit:", error);
      }
    },
    [createKit, defaultKitName, kits, navigateToKit],
  );

  const labelTemporary = useLabel("semio.sketchpad.app.home.toolbar.createTemporary");
  const labelFile = useLabel("semio.sketchpad.app.home.toolbar.createFile");
  const labelFolder = useLabel("semio.sketchpad.app.home.toolbar.createFolder");
  const labelRemote = useLabel("semio.sketchpad.app.home.toolbar.createRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.temporary && <Action id="semio.sketchpad.app.home.toolbar.createTemporary" icon={<TemporaryKitIcon />} text={labelTemporary} onClick={() => handleCreateKit("temporary")} />}
      {availableKitKinds.file && <Action id="semio.sketchpad.app.home.toolbar.createFile" icon={<DocumentIcon />} text={labelFile} onClick={() => handleCreateKit("file")} />}
      {availableKitKinds.folder && <Action id="semio.sketchpad.app.home.toolbar.createFolder" icon={<FolderIcon />} text={labelFolder} onClick={() => handleCreateKit("folder")} />}
      {availableKitKinds.remote && <Action id="semio.sketchpad.app.home.toolbar.createRemote" icon={<RemoteKitIcon />} text={labelRemote} onClick={() => handleCreateKit("remote")} />}
    </ToolbarGroup>
  );
};
/**
 * Toolbar group for opening existing synchronized kits from folder, file, or remote URL.
 *
 * Specs: Folder kit opens a native folder picker (desktop only via folderKitStoreFactory).
 * File kit opens a file picker for .kit.semio.json files (via fileKitStoreFactory).
 * Remote kit asks for a semio/server URL and connects (via remoteKitStoreFactory).
 * Each kind is only shown when the corresponding factory is available.
 **/
const HomeToolbarOpen: FC = () => {
  const availableKitKinds = useAvailableKitKinds();
  const { openKit, navigateToKit } = useSketchpadCommands();

  const handleOpenFolder = useCallback(async () => {
    try {
      const result = await openKit("semio.sketchpad.app.home.toolbar.openFolder", "folder");
      if (result?.kitId) navigateToKit(result.kitId);
    } catch (error) {
      console.error("[Home] Failed to open folder kit:", error);
    }
  }, [openKit, navigateToKit]);

  const handleOpenFile = useCallback(async () => {
    try {
      const result = await openKit("semio.sketchpad.app.home.toolbar.openFile", "file");
      if (result?.kitId) navigateToKit(result.kitId);
    } catch (error) {
      console.error("[Home] Failed to open file kit:", error);
    }
  }, [openKit, navigateToKit]);

  const handleOpenRemote = useCallback(async () => {
    const url = prompt("Enter semio server URL:");
    if (!url) return;
    try {
      const result = await openKit("semio.sketchpad.app.home.toolbar.openRemote", "remote", url);
      if (result?.kitId) navigateToKit(result.kitId);
    } catch (error) {
      console.error("[Home] Failed to open remote kit:", error);
    }
  }, [openKit, navigateToKit]);

  const labelFolder = useLabel("semio.sketchpad.app.home.toolbar.openFolder");
  const labelFile = useLabel("semio.sketchpad.app.home.toolbar.openFile");
  const labelRemote = useLabel("semio.sketchpad.app.home.toolbar.openRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.folder && <Action id="semio.sketchpad.app.home.toolbar.openFolder" icon={<FolderIcon />} text={labelFolder ?? "Folder"} onClick={handleOpenFolder} />}
      {availableKitKinds.file && <Action id="semio.sketchpad.app.home.toolbar.openFile" icon={<DocumentIcon />} text={labelFile ?? "File"} onClick={handleOpenFile} />}
      {availableKitKinds.remote && <Action id="semio.sketchpad.app.home.toolbar.openRemote" icon={<RemoteKitIcon />} text={labelRemote ?? "Remote"} onClick={handleOpenRemote} />}
    </ToolbarGroup>
  );
};
/**
 * HomeToolbarExport provides the Export - Archive action for the Home toolbar.
 * Exports selected kits as *.kit.semio.zip archive files.
 **/
const HomeToolbarExport: FC = () => {
  const selection = useHomeSelection();
  const store = useSketchpadStore();
  const selectedKits = selection?.kits || [];

  const handleExportArchive = useCallback(() => {
    for (const kitId of selectedKits) {
      if (store.hasKit(kitId)) {
        store.kit(kitId).execute("semio.kit.export", "semio.sketchpad.app.home.toolbar.exportArchive");
      }
    }
  }, [selectedKits, store]);

  const labelExportArchive = useLabel("semio.sketchpad.app.home.toolbar.exportArchive");

  if (selectedKits.length === 0) return null;

  return (
    <ToolbarGroup>
      <Action id="semio.sketchpad.app.home.toolbar.exportArchive" icon={<FileArchiveIcon />} text={labelExportArchive ?? "Archive"} onClick={handleExportArchive} />
    </ToolbarGroup>
  );
};

/**
 * TableRow holds the data fields for a TableRow record.
 **/
type HomeTableRow = {
  id: string;
  name: string;
  level: number;
  parentId?: string;
  hasChildren: boolean;
  isExpanded: boolean;
  type: KitKind | "docs" | "loading";
  updatedAt: string;
  createdAt: string;
  kit?: KitShallow;
  docsPath?: string;
  icon?: string;
  isLoading?: boolean;
};
/**
 * HomeTableContent holds the data fields for a HomeTableContent record.
 **/
const HomeTableContent: FC = () => {
  const navigate = useNavigate();
  const navigation = useNavigation();
  const docsMetadataVersion = useDocsMetadataVersion();
  const [searchParams, setSearchParams] = useSearchParams();
  const kits = useKits();
  const getKitKind = useGetKitKind();
  const { createKit, navigateToKit } = useSketchpadCommands();

  const homeState = useHome() as any;
  const homeCommands = useHomeCommands();
  const isMobile = useIsMobile();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const tooltip = useTooltip();

  const selection = homeState?.selection?.kits || [];
  const hover = useHomeHover();
  const lastClickedIdRef = React.useRef<string | null>(null);

  const defaultKitName = useLabel("semio.sketchpad.app.kit.defaultName");
  const newVersionLabel = useLabel("semio.sketchpad.app.kit.newVersion");
  const defaultVersionLabel = useLabel("semio.sketchpad.app.kit.defaultVersion");

  useEffect(() => {
    if (appType !== "home") return;

    const hasKits = selection.length > 0;
    const hasSingleKit = selection.length === 1;
    const hasMultipleKits = selection.length > 1;

    removeSection("details", "semio.sketchpad.app.kit.properties");
    removeSection("details", "semio.sketchpad.app.home.kits.multiple");

    if (hasKits) {
      const sectionId = hasSingleKit ? "semio.sketchpad.app.kit.properties" : "semio.sketchpad.app.home.kits.multiple";
      addSection("details", {
        id: sectionId,
        specificity: 0,
        order: 0,
        content: () => {
          return <HomeKitSection />;
        },
      });
    }

    return () => {
      removeSection("details", "semio.sketchpad.app.kit.properties");
      removeSection("details", "semio.sketchpad.app.home.kits.multiple");
    };
  }, [appType, addSection, removeSection, selection.length]);

  const selectedKind = searchParams.get("kind") as KitKind | null;
  const selectedName = searchParams.get("name");
  const selectedVersion = searchParams.get("version");

  const searchQuery = searchParams.get("q") || "";

  const expandedRowsParam = searchParams.getAll("e");
  const expandedRows = new Set(expandedRowsParam);

  const sortColumn = homeState?.sortColumn;
  const sortDirection = homeState?.sortDirection || "asc";

  const uniqueNames = useMemo(() => {
    const nameSet = new Set<string>();
    kits.forEach((kit) => {
      const type = getKitKind(kit.id) || "temporary";

      if (selectedKind && selectedKind !== type) return;
      nameSet.add(kit.name);
    });
    return Array.from(nameSet).sort();
  }, [kits, getKitKind, selectedKind]);

  const uniqueVersions = useMemo(() => {
    if (!selectedName) return [];
    const versionSet = new Set<string>();
    kits.forEach((kit) => {
      if (kit.name === selectedName) {
        versionSet.add(kit.version || "");
      }
    });
    return Array.from(versionSet).sort();
  }, [kits, selectedName]);

  const rows = useMemo<HomeTableRow[]>(() => {
    const result: HomeTableRow[] = [];
    const locale = i18n.language === "de" ? de : enUS;
    const formatDate = (date?: Date | string) => {
      if (!date) return "";
      const parsedDate = date instanceof Date ? date : new Date(date);
      if (isNaN(parsedDate.getTime())) return "";
      return formatDistanceToNow(parsedDate, { addSuffix: true, locale });
    };

    const allDocsPages = docsRegistry.getAllPages();
    const allDocsSections = docsRegistry.getAllSections();

    const docsParentId = "docs-root";
    result.push({
      id: docsParentId,
      name: "Documentation",
      level: 0,
      hasChildren: true,
      isExpanded: expandedRows.has(docsParentId),
      type: "docs",
      updatedAt: "",
      createdAt: "",
      kit: undefined,
      docsPath: undefined,
    });

    if (expandedRows.has(docsParentId)) {
      allDocsSections.forEach((section) => {
        const sectionId = `docs-section-${section.id}`;
        const sectionPages = docsRegistry.getPagesBySection(section.id);

        result.push({
          id: sectionId,
          name: section.label,
          level: 1,
          parentId: docsParentId,
          hasChildren: sectionPages.length > 0,
          isExpanded: expandedRows.has(sectionId),
          type: "docs",
          updatedAt: "",
          createdAt: "",
          kit: undefined,
          docsPath: undefined,
          icon: section.icon,
        });

        if (expandedRows.has(sectionId)) {
          sectionPages.forEach((page) => {
            result.push({
              id: `docs-page-${page.path}`,
              name: page.title,
              level: 2,
              parentId: sectionId,
              hasChildren: false,
              isExpanded: false,
              type: "docs",
              updatedAt: "",
              createdAt: "",
              kit: undefined,
              docsPath: page.path,
              icon: page.icon,
            });
          });
        }
      });
    }

    const loadingKits = homeState?.loadingKits || [];
    loadingKits.forEach((loadingKit: LoadingKit) => {
      result.push({
        id: `loading-${loadingKit.tempId}`,
        name: loadingKit.name,
        level: 0,
        hasChildren: false,
        isExpanded: false,
        type: "loading",
        updatedAt: "",
        createdAt: "",
        kit: undefined,
        isLoading: true,
      });
    });

    const kitGroups = new Map<string, KitShallow[]>();

    kits.forEach((kit) => {
      const type = getKitKind(kit.id) || "temporary";

      if (selectedKind && selectedKind !== type) return;
      if (searchQuery && !kit.name.toLowerCase().includes(searchQuery.toLowerCase())) return;
      if (selectedName && kit.name !== selectedName) return;
      if (selectedVersion && (kit.version || "") !== selectedVersion) return;

      const key = kit.name;
      if (!kitGroups.has(key)) kitGroups.set(key, []);
      kitGroups.get(key)!.push(kit);
    });

    kitGroups.forEach((groupKits, name) => {
      const parentId = `kit-${name}`;
      const defaultKit = groupKits.find((k) => !k.version);
      const parentKit = defaultKit || groupKits[0];
      const hasChildren = groupKits.some((k) => k.id !== parentKit.id);

      const type = getKitKind(parentKit.id) || "temporary";

      result.push({
        id: parentId,
        name: name,
        level: 0,
        hasChildren,
        isExpanded: expandedRows.has(parentId),
        type,
        updatedAt: formatDate(parentKit.updatedAt),
        createdAt: formatDate(parentKit.createdAt),
        kit: parentKit,
      });

      if (expandedRows.has(parentId) && hasChildren) {
        groupKits.forEach((kit) => {
          if (kit.id === parentKit.id) return;
          const kitKind = getKitKind(kit.id) || "temporary";

          const versionId = `${parentId}-${kit.version || "default"}`;
          result.push({
            id: versionId,
            name: kit.version || "(default)",
            level: 1,
            parentId,
            hasChildren: false,
            isExpanded: false,
            type: kitKind,
            updatedAt: formatDate(kit.updatedAt),
            createdAt: formatDate(kit.createdAt),
            kit: kit,
          });
        });
      }
    });

    if (sortColumn) {
      const topLevelRows = result.filter((r) => r.level === 0);
      const childRows = result.filter((r) => r.level > 0);
      topLevelRows.sort((a, b) => {
        let comparison = 0;
        switch (sortColumn) {
          case "name":
            comparison = a.name.localeCompare(b.name);
            break;
          case "type":
            comparison = a.type.localeCompare(b.type);
            break;
          case "updatedAt":
            comparison = a.updatedAt.localeCompare(b.updatedAt);
            break;
          case "createdAt":
            comparison = a.createdAt.localeCompare(b.createdAt);
            break;
        }
        return sortDirection === "asc" ? comparison : -comparison;
      });
      const sortedResult: HomeTableRow[] = [];
      topLevelRows.forEach((parent) => {
        sortedResult.push(parent);
        const children = childRows.filter((c) => c.parentId === parent.id);
        children.sort((a, b) => {
          let comparison = 0;
          switch (sortColumn) {
            case "name":
              comparison = a.name.localeCompare(b.name);
              break;
            case "type":
              comparison = a.type.localeCompare(b.type);
              break;
            case "updatedAt":
              comparison = a.updatedAt.localeCompare(b.updatedAt);
              break;
            case "createdAt":
              comparison = a.createdAt.localeCompare(b.createdAt);
              break;
          }
          return sortDirection === "asc" ? comparison : -comparison;
        });
        sortedResult.push(...children);
      });
      return sortedResult;
    }

    return result;
  }, [docsMetadataVersion, kits, getKitKind, selectedKind, searchQuery, selectedName, selectedVersion, expandedRows, sortColumn, sortDirection, homeState?.loadingKits]);

  const { setFocusItems, setOnFocusItem } = useFocus();
  const [focusedItemId, setFocusedItemId] = useState<string | undefined>();
  const prevRowsRef = useRef<string>("");

  useEffect(() => {
    const items = rows.map((row) => ({
      id: row.id,
      label: row.name,
      category: row.level === 0 ? "Kits" : "Versions",
    }));

    const itemsKey = items.map((item) => `${item.id}:${item.label}`).join("|");
    if (prevRowsRef.current !== itemsKey) {
      prevRowsRef.current = itemsKey;
      setFocusItems(items);
    }
  }, [rows, setFocusItems]);

  useEffect(() => {
    const handleFocus = (itemId: string) => {
      setFocusedItemId(itemId);
    };
    setOnFocusItem(handleFocus);
    return () => setOnFocusItem(undefined);
  }, [setOnFocusItem]);

  const handleCreateKit = async (type: KitKind) => {
    const existingNames = kits.map((k) => k.name);
    const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames) ?? defaultKitName ?? "";
    const newKit: Kit = {
      id: id(),
      name: uniqueName,
      version: "",
      types: [],
      designs: [],
    };
    try {
      const result = await createKit("semio.sketchpad.app.home.canvas.table.createKit", newKit, type);
      navigateToKit(result?.kitId ?? newKit.id);
    } catch (error) {
      console.error("[Home] Failed to create kit:", error);
    }
  };

  const handleCreateVersion = async (kitName: string, type: KitKind) => {
    const existingVersions = kits.filter((k) => k.name === kitName).map((k) => k.version || "");
    const uniqueVersion = generateUniqueName(newVersionLabel ?? "", existingVersions) ?? newVersionLabel ?? "";
    const newKit: Kit = {
      id: id(),
      name: kitName,
      version: uniqueVersion,
      types: [],
      designs: [],
    };
    try {
      const result = await createKit("semio.sketchpad.app.home.canvas.table.createVersion", newKit, type);
      navigateToKit(result?.kitId ?? newKit.id);
    } catch (error) {
      console.error("[Home] Failed to create version:", error);
    }
  };

  const toggleKind = (type: KitKind) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedKind === type) {
      newParams.delete("kind");
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("kind", type);
      newParams.delete("name");
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  useHotkeys("semio.sketchpad.app.home.filter.kind.temporary", () => toggleKind("temporary"));
  useHotkeys("semio.sketchpad.app.home.filter.kind.file", () => toggleKind("file"));
  useHotkeys("semio.sketchpad.app.home.filter.kind.folder", () => toggleKind("folder"));
  useHotkeys("semio.sketchpad.app.home.filter.kind.remote", () => toggleKind("remote"));

  const toggleName = (name: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedName === name) {
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("name", name);
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  const toggleVersion = (version: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedVersion === version) {
      newParams.delete("version");
    } else {
      newParams.set("version", version);
    }
    setSearchParams(newParams);
  };

  const toggleRow = (rowId: string) => {
    const currentUrl = new URL(window.location.href);
    const currentRows = currentUrl.searchParams.getAll("e");

    if (currentRows.includes(rowId)) {
      currentUrl.searchParams.delete("e");
      currentRows.filter((r) => r !== rowId).forEach((r) => currentUrl.searchParams.append("e", r));
    } else {
      currentUrl.searchParams.append("e", rowId);
    }

    window.history.replaceState(window.history.state, "", currentUrl);

    window.dispatchEvent(new PopStateEvent("popstate", { state: window.history.state }));
  };

  const handleSearchChange = (value: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (value) {
      newParams.set("q", value);
    } else {
      newParams.delete("q");
    }
    setSearchParams(newParams);
  };

  const handleRowClick = (kitId: string, e: React.MouseEvent) => {
    const compositionKind = resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
      shiftKey: e.shiftKey,
      altKey: e.altKey,
      ctrlKey: e.ctrlKey,
      metaKey: e.metaKey,
    });
    const useRangeSelection = e.shiftKey && !e.altKey && !e.ctrlKey && !e.metaKey;
    if (useRangeSelection && lastClickedIdRef.current) {
      const currentIndex = rows.findIndex((r) => r.kit?.id === kitId);
      const lastIndex = rows.findIndex((r) => r.kit?.id === lastClickedIdRef.current);
      if (lastIndex !== -1 && currentIndex !== -1) {
        const start = Math.min(lastIndex, currentIndex);
        const end = Math.max(lastIndex, currentIndex);
        const rangeIds = rows
          .slice(start, end + 1)
          .map((r) => r.kit?.id)
          .filter((id): id is string => id !== undefined);
        const newSelection = applySelectionComposition(selection, rangeIds, compositionKind);
        homeCommands.clearSelection();
        for (const id of newSelection) {
          homeCommands.addKitToSelection("semio.sketchpad.app.home.canvas.table.selectKitsRange", id);
        }
      }
    } else {
      const newSelection = applySelectionComposition(selection, [kitId], compositionKind);
      homeCommands.clearSelection();
      for (const id of newSelection) {
        homeCommands.addKitToSelection("semio.sketchpad.app.home.canvas.table.selectKit", id);
      }
      lastClickedIdRef.current = kitId;
    }
  };

  const handleSortClick = (column: "name" | "type" | "updatedAt" | "createdAt") => {
    homeCommands.toggleSort("semio.sketchpad.app.home.canvas.table.toggleSort", column);
  };

  if (isMobile) {
    return (
      <div
        className="flex flex-col h-full"
        onClick={(e: React.MouseEvent) => {
          if (e.target === e.currentTarget) {
            homeCommands.deselectAll("semio.sketchpad.app.home.canvas.table.deselect");
          }
        }}
      >
        <div className="flex items-center justify-between border-b border-element px-single h-large">
          <span className="font-medium">{useLabel("semio.sketchpad.app.home.name")}</span>
          <Toggle
            kind="dropdown"
            pressed={sortColumn === "name"}
            value={sortColumn === "name" ? sortDirection : "asc"}
            onValueChange={(value) => {
              homeCommands.setSortColumn("semio.sketchpad.app.home.filter.name.sortColumn", "name");
              homeCommands.setSortDirection("semio.sketchpad.app.home.header.name.sortDirection", value as "asc" | "desc");
            }}
            items={[
              { value: "asc", label: <SortAscendingIcon />, id: "semio.sketchpad.sort.ascending" },
              { value: "desc", label: <SortDescendingIcon />, id: "semio.sketchpad.sort.descending" },
            ]}
            id={"semio.sketchpad.app.home.sortByName"}
          />
        </div>
        <Scrollable className="flex-1">
          <div className="flex flex-col">
            {rows.map((row) => {
              const isSelected = row.kit ? selection.includes(row.kit.id) : false;
              const isDocsRow = row.type === "docs";
              const isLoadingRow = row.isLoading;
              const isHovered = row.kit ? hover?.kits?.includes(row.kit.id) : false;
              return (
                <div
                  key={row.id}
                  data-testid={`home-kit-row-${row.id}`}
                  data-loading={isLoadingRow ? "true" : "false"}
                  className={`border-b border-element p-single cursor-selectable h-medium ${isLoadingRow ? "opacity-50 pointer-events-none" : ""} ${isSelected ? "bg-active-base text-active-foreground" : isHovered ? "bg-hover-base" : "hover:bg-hover-base"}`}
                  role="button"
                  tabIndex={isLoadingRow ? -1 : 0}
                  onClick={(e) => {
                    if (isLoadingRow) return;
                    if (isDocsRow && row.docsPath) {
                      navigate(`/${row.docsPath}`);
                    } else if (row.kit) {
                      handleRowClick(row.kit.id, e);
                    }
                  }}
                  onDoubleClick={() => {
                    if (isLoadingRow) return;
                    if (isDocsRow && row.docsPath) {
                      navigate(`/${row.docsPath}`);
                    } else if (row.kit) {
                      navigateToKit(row.kit.id);
                    }
                  }}
                  onMouseEnter={() => {
                    if (!row.kit) {
                      homeCommands.clearHover("semio.sketchpad.app.home.canvas.table.clearHover");
                      return;
                    }
                    homeCommands.hoverKit("semio.sketchpad.app.home.canvas.table.hover", row.kit.id);
                  }}
                  onMouseLeave={() => {
                    homeCommands.clearHover("semio.sketchpad.app.home.canvas.table.clearHover");
                  }}
                >
                  <div className="flex items-center gap-single w-full" onClick={(e) => e.stopPropagation()}>
                    <div className="flex items-center gap-single flex-1 min-w-0" style={{ paddingLeft: `calc(${row.level} * var(--size-small))` }}>
                      {row.hasChildren ? (
                        <Action
                          id={"semio.sketchpad.app.home.toggleRow"}
                          onClick={(e) => {
                            e.stopPropagation();
                            toggleRow(row.id);
                          }}
                          icon={row.isExpanded ? <ChevronDownIcon className="size-small" /> : <ChevronRightIcon className="size-small" />}
                        />
                      ) : (
                        <span className="size-small shrink-0" />
                      )}
                      <TableAvatar name={row.name} icon={row.kit?.icon} />
                      <span className="text-left flex-1 min-w-0 truncate">{row.name}</span>
                      {isLoadingRow && <Spinner size="small" />}
                    </div>
                    <div className="flex items-center gap-single shrink-0 ml-auto">
                      {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                        <Action
                          onClick={(e) => {
                            e.stopPropagation();
                            handleCreateVersion(row.name, row.type as KitKind);
                          }}
                          id={"semio.sketchpad.app.home.createVersion"}
                          icon={<AddIcon />}
                        />
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </Scrollable>
      </div>
    );
  }

  return (
    <div
      className="flex flex-col h-full"
      onClick={(e: React.MouseEvent) => {
        if (e.target === e.currentTarget) {
          homeCommands.deselectAll("semio.sketchpad.app.home.canvas.table.deselect");
        }
      }}
    >
      <Table<HomeTableRow>
        className="flex-1 min-h-0"
        columns={[
          ...(!selectedKind
            ? [
                {
                  id: "type",
                  header: (
                    <div className="inline-flex items-center gap-single">
                      <span>{useLabel("semio.sketchpad.app.home.kind")}</span>
                      <Toggle
                        kind="dropdown"
                        pressed={sortColumn === "type"}
                        value={sortColumn === "type" ? sortDirection : "asc"}
                        onValueChange={(value) => {
                          homeCommands.setSortColumn("semio.sketchpad.app.home.header.type.sortColumn", "type");
                          homeCommands.setSortDirection("semio.sketchpad.app.home.header.type.sortDirection", value as "asc" | "desc");
                        }}
                        items={[
                          { value: "asc", label: <SortAscendingIcon />, id: "semio.sketchpad.sort.ascending" },
                          { value: "desc", label: <SortDescendingIcon />, id: "semio.sketchpad.sort.descending" },
                        ]}
                        id={"semio.sketchpad.app.home.sortByType"}
                      />
                    </div>
                  ),
                  accessor: (row) => (
                    <>
                      {row.type === "temporary" && <TemporaryKitIcon />}
                      {row.type === "file" && <DocumentIcon />}
                      {row.type === "folder" && <FolderIcon />}
                      {row.type === "remote" && <RemoteKitIcon />}
                      {row.type === "docs" && <DocumentIcon className="size-small" />}
                    </>
                  ),
                  width: "w-0 whitespace-nowrap",
                  headerClassName: "relative group w-0 whitespace-nowrap",
                } as TableColumn<HomeTableRow>,
              ]
            : []),
          {
            id: "name",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("semio.sketchpad.app.home.name")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "name"}
                  value={sortColumn === "name" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("semio.sketchpad.app.home.header.name.sortColumn", "name");
                    homeCommands.setSortDirection("semio.sketchpad.app.home.header.name.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "semio.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "semio.sketchpad.sort.descending" },
                  ]}
                  id={"semio.sketchpad.app.home.sortByName"}
                />
              </div>
            ),
            accessor: (row) => (
              <div className={`flex items-center gap-single w-full ${row.isLoading ? "opacity-50 pointer-events-none" : ""}`} onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center gap-single flex-1 min-w-0" style={{ paddingLeft: `calc(${row.level} * var(--size-small))` }}>
                  {row.hasChildren ? (
                    <Action
                      id={"semio.sketchpad.app.home.toggleRow"}
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleRow(row.id);
                      }}
                      icon={row.isExpanded ? <ChevronDownIcon className="size-small" /> : <ChevronRightIcon className="size-small" />}
                    />
                  ) : (
                    <span className="size-small shrink-0" />
                  )}
                  <TableAvatar name={row.name} icon={row.type === "docs" ? row.icon : row.kit?.icon} />
                  <span className="text-left min-w-0 truncate">{row.name}</span>
                  {row.isLoading && <Spinner size="small" />}
                </div>
                <div className="flex items-center gap-single shrink-0 ml-auto">
                  {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                    <Action
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCreateVersion(row.name, row.type as KitKind);
                      }}
                      id={"semio.sketchpad.app.home.createVersion"}
                      icon={<AddIcon />}
                    />
                  )}
                </div>
              </div>
            ),
            headerClassName: "relative group",
          },
          {
            id: "updatedAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("semio.sketchpad.app.home.lastUpdated")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "updatedAt"}
                  value={sortColumn === "updatedAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("semio.sketchpad.app.home.header.updatedAt.sortColumn", "updatedAt");
                    homeCommands.setSortDirection("semio.sketchpad.app.home.header.updatedAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "semio.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "semio.sketchpad.sort.descending" },
                  ]}
                  id={"semio.sketchpad.app.home.sortByUpdatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.updatedAt,
            headerClassName: "relative group",
          },
          {
            id: "createdAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("semio.sketchpad.app.home.created")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "createdAt"}
                  value={sortColumn === "createdAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("semio.sketchpad.app.home.header.createdAt.sortColumn", "createdAt");
                    homeCommands.setSortDirection("semio.sketchpad.app.home.header.createdAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "semio.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "semio.sketchpad.sort.descending" },
                  ]}
                  id={"semio.sketchpad.app.home.sortByCreatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.createdAt,
            headerClassName: "relative group",
          },
        ]}
        rowClassName={(row) => {
          if (!row.kit) return "";
          if (selection.includes(row.kit.id)) return "";
          return hover?.kits?.includes(row.kit.id) ? "bg-hover-base" : "";
        }}
        onRowMouseEnter={(row) => {
          if (!row.kit) {
            homeCommands.clearHover("semio.sketchpad.app.home.canvas.table.clearHover");
            return;
          }
          homeCommands.hoverKit("semio.sketchpad.app.home.canvas.table.hover", row.kit.id);
        }}
        onRowMouseLeave={() => {
          homeCommands.clearHover("semio.sketchpad.app.home.canvas.table.clearHover");
        }}
        data={rows}
        onRowClick={(row, _, e) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            handleRowClick(row.kit.id, e);
          }
        }}
        onRowDoubleClick={(row) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            navigateToKit(row.kit.id);
          }
        }}
        rowKey={(row) => row.id}
        getRowId={(row) => row.kit?.id || row.id}
        selectedRows={new Set(selection)}
        focusedItemId={focusedItemId}
        onFocusComplete={() => setFocusedItemId(undefined)}
        emptyMessage={useLabel("semio.sketchpad.app.home.noKits")}
        stickyHeader={true}
        headerClassName="sticky top-0 border-b border-element"
        hierarchical={true}
      />
    </div>
  );
};

// #region 🎗️Multi-Window App
// Multi-window app MUST orchestrate the Home canvas and layout.

/**
 * TableWindow holds the data fields for a TableWindow record.
 **/
const HomeTableWindow = memo(() => {
  return <HomeTableContent />;
});
HomeTableWindow.displayName = "HomeTableWindow";
/**
 * Home holds the data fields for a Home record.
 **/
const Home: FC = () => {
  const actor = useSketchpadActor();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const isMobile = useIsMobile();
  const availableKitKinds = useAvailableKitKinds();

  const homeState = useHome() as HomeState;
  const storedWindowLayout = homeState?.windowLayout;

  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "home") return;

    const hasAvailableKitKinds = availableKitKinds.temporary || availableKitKinds.file || availableKitKinds.folder || availableKitKinds.remote;

    addSection("toolbar", {
      id: "semio.sketchpad.app.home.toolbar.open",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "open",
        labelId: "semio.sketchpad.toolbar.parent.open",
        order: 10,
      },
      content: <HomeToolbarOpen />,
    });

    if (hasAvailableKitKinds) {
      addSection("toolbar", {
        id: "semio.sketchpad.app.home.toolbar.filters",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "filter",
          labelId: "semio.sketchpad.toolbar.parent.filter",
          order: 20,
        },
        content: <HomeToolbarFilters />,
      });
      addSection("toolbar", {
        id: "semio.sketchpad.app.home.toolbar.create",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "create",
          labelId: "semio.sketchpad.toolbar.parent.create",
          order: 30,
        },
        content: <HomeToolbarCreate />,
      });
    }

    addSection("toolbar", {
      id: "semio.sketchpad.app.home.toolbar.export",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "export",
        labelId: "semio.sketchpad.toolbar.parent.export",
        order: 40,
      },
      content: <HomeToolbarExport />,
    });

    return () => {
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.open");
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.filters");
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.create");
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.export");
    };
  }, [appType, addSection, removeSection, availableKitKinds]);

  // 🗃️Add Settings and Chat as side panel tabs
  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();

  useEffect(() => {
    if (appType !== "home") return;
    return () => {};
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: HomeAppWindowKind.Table,
                title: "table",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );

  const windowLayout = useMemo(() => storedWindowLayout || defaultLayout, [storedWindowLayout, defaultLayout]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: HomeAppWindowKind.Table,
          label: "table",
          component: () => <HomeTableWindow />,
        },
      ],
      defaultLayout,
    }),
    [defaultLayout],
  );

  const handleLayoutChange = useCallback(
    (config: any) => {
      const configStr = JSON.stringify(config);
      const lastStr = JSON.stringify(lastLayoutRef.current);
      if (configStr === lastStr) return;
    },
    [actor],
  );

  if (isMobile) {
    return (
      <HomeDropZone>
        <HomeTableContent />
      </HomeDropZone>
    );
  }

  return (
    <>
      <HomeFooter />
      <HomeDropZone>
        <Canvas id="semio.sketchpad.app.home.canvas">
          <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
        </Canvas>
      </HomeDropZone>
    </>
  );
};

// #endregion 🎗️Multi-Window App

